  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'jobs/pending',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'jobs/pending',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_items_per_page => 0,
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  CURSOR c_next IS
    SELECT job_id FROM iteria_ai.scout_jobs
     WHERE status = ''PENDING''
     ORDER BY job_id
     FOR UPDATE SKIP LOCKED;
  v_id NUMBER;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401, ''Unauthorized'', FALSE);
    HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;

  -- Atomic claim: open a cursor with FOR UPDATE SKIP LOCKED, fetch exactly one row.
  --
  -- We deliberately do NOT use FETCH FIRST 1 ROWS ONLY here. Oracle''s
  -- row_limiting_clause is documented as incompatible with FOR UPDATE: under
  -- the hood, Oracle rewrites the query as a ROW_NUMBER()-wrapped inline view,
  -- and then refuses to lock through that wrapper, raising
  --   ORA-02014: cannot select FOR UPDATE from view with DISTINCT, GROUP BY, etc.
  -- The previous version of this handler hit that error on every poll, returning
  -- 555 to the worker. An explicit cursor avoids the wrapping: we OPEN, FETCH a
  -- single row, then CLOSE — subseq' || 'uent rows are never locked because they''re
  -- never fetched, leaving them available for other worker replicas via
  -- SKIP LOCKED.
  OPEN c_next;
  FETCH c_next INTO v_id;

  IF c_next%FOUND THEN
    UPDATE iteria_ai.scout_jobs
       SET status = ''RUNNING'', started_at = SYSTIMESTAMP
     WHERE job_id = v_id;
    CLOSE c_next;
    COMMIT;

    HTP.P(''{"items":['');
    FOR r IN (SELECT job_id, job_type, role_id, candidate_id, session_id,
                     payload_json FROM iteria_ai.scout_jobs WHERE job_id = v_id) LOOP
      HTP.P(JSON_OBJECT(
        ''job_id''       VALUE r.job_id,
        ''job_type''     VALUE r.job_type,
        ''role_id''      VALUE r.role_id,
        ''candidate_id'' VALUE r.candidate_id,
        ''session_id''   VALUE r.session_id,
        ''payload_json'' VALUE r.payload_json
      ));
    END LOOP;
    HTP.P('']}'');
  ELSE
    CLOSE c_next;
    HTP.P(''{"items":[]}'');
  END IF;
END;');

