    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;
  HTP.P(''{"roles":['');
  DECLARE
    v_first BOOLEAN := TRUE;
  BEGIN
    FOR r IN (
      WITH cand AS (
        SELECT role_id,
               COUNT(*)                                    AS resume_total,
               COUNT(invited_at)                           AS invited,
               COUNT(interviewed_at)                       AS interviewed,
               COUNT(overall_score)                        AS scored,
               SUM(CASE WHEN status=''PARSE_FAILED'' THEN 1 ELSE 0 END) AS parse_failed
          FROM iteria_ai.scout_candidates
         GROUP BY role_id
      ),
      sl AS (
        SELECT role_id, COUNT(*) AS shortlisted
          FROM iteria_ai.scout_shortlist
         GROUP BY role_id
      )
      SELECT ro.role_id, ro.title, ro.description, ro.department, ro.location,
             ro.status, ro.hi' || 'ring_manager, ro.created_at,
             ro.auto_invite, ro.auto_invite_threshold, ro.rubric_summary,
             ro.rubric_json, ro.must_haves, ro.nice_to_haves, ro.question_bank,
             NVL(cand.resume_total, 0) AS resume_total,
             NVL(cand.invited,      0) AS invited,
             NVL(cand.interviewed,  0) AS interviewed,
             NVL(cand.scored,       0) AS scored,
             NVL(cand.parse_failed, 0) AS parse_failed,
             NVL(sl.shortlisted,    0) AS shortlisted
        FROM iteria_ai.scout_roles ro
        LEFT JOIN cand ON cand.role_id = ro.role_id
        LEFT JOIN sl   ON sl.role_id   = ro.role_id
       ORDER BY ro.role_id
    ) LOOP
      IF NOT v_first THEN HTP.P('',''); END IF;
      v_first := FALSE;
