      HTP.P('',"rubric_json":'');            iteria_ai.scout_htp_clob(NVL(r.rubric_json,   ''{}''));
      HTP.P('',"must_haves":'');             iteria_ai.scout_htp_clob(NVL(r.must_haves,    ''[]''));
      HTP.P('',"nice_to_haves":'');          iteria_ai.scout_htp_clob(NVL(r.nice_to_haves, ''[]''));
      HTP.P('',"question_bank":'');    ' || '      iteria_ai.scout_htp_clob(NVL(r.question_bank, ''{}''));
      HTP.P('',"resume_total":''   || r.resume_total);
      HTP.P('',"invited":''        || r.invited);
      HTP.P('',"interviewed":''    || r.interviewed);
      HTP.P('',"scored":''         || r.scored);
