'
DECLARE
  v_body CLOB := iteria_ai.blob_to_clob_utf8(:body);
  v_id   NUMBER;
  v_desc_len INTEGER;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;

  INSERT INTO iteria_ai.scout_roles
    (title, description, department, location, status,
     auto_invite, auto_invite_threshold, rubric_json, created_at)
  VALUES (
    JSON_VALUE(v_body,''$.title''),
    JSON_VALUE(v_body,''$.description''),
    JSON_VALUE(v_body,''$.department''),
    JSON_VALUE(v_body,''$.location''),
    NVL(JSON_VALUE(v_body,''$.status''),''OPEN''),
    NVL(JSON_VALUE(v_body,''$.auto_invite''),''Y''),
    NVL(JSON_VALUE(v_body,''$.auto_invite_threshold'' RETURNING NUMBER), 75),
    NVL(JSON_QUERY(v_body,''$.rubric_json''),''{}''),
    SYSTIMESTAMP
  ) RETURNING role_id INTO v_id;

  -- Auto-queue rubric extraction if the role has enough text to analyze.
  SELECT NVL(DBMS_LOB.GETLENGTH(description),0)
    INTO v_desc_' || 'len
    FROM iteria_ai.scout_roles
   WHERE role_id = v_id;

  IF v_desc_len > 50 THEN
    INSERT INTO iteria_ai.scout_jobs
      (job_type, status, role_id, payload_json, created_at)
    VALUES (''EXTRACT_RUBRIC'', ''PENDING'', v_id, ''{}'', SYSTIMESTAMP);
  END IF;

  COMMIT;
  HTP.P(''{"role_id":'' || v_id || ''}'');
END;
');

