    HTP.P('',"question_bank":'');            iteria_ai.scout_htp_clob(NVL(r.question_bank, ''{}''));
    HTP.P('',"jd_id":'' || NVL(TO_CHAR(r.jd_id), ''null''));
    HTP.P('',"jd_filename":'');              iteria_ai.scout_htp_json_str(r.jd_filename' || ');
    HTP.P(''}'');
    EXIT;
  END LOOP;
  IF NOT v_found THEN
    OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
    HTP.P(''{"error":"role not found"}'');
  END IF;
