'
DECLARE
  v_role_id NUMBER := NULL;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;
  BEGIN
    IF :role_id IS NOT NULL THEN v_role_id := TO_NUMBER(:role_id); END IF;
  EXCEPTION WHEN OTHERS THEN v_role_id := NULL; END;

  HTP.P(''{"candidates":['');
  DECLARE
    v_first BOOLEAN := TRUE;
  BEGIN
    FOR r IN (
      SELECT candidate_id, role_id, candidate_name, status,
             recommendation, composite_score, overall_score,
             years_experience, current_role, education,
             inferred_gender, intake_mode, summary,
             invited_at, interviewed_at,
             skills_matched, skills_missing, rubric_scores,
             strengths, gaps_to_probe, red_flags
        FROM iteria_ai.scout_candidates
       WHERE v_role_id IS NULL OR role_id = v_role_id
       ORDER BY candidate_id DESC
    ) LOOP
      IF NOT v_first THEN HTP.P('',''); END IF;
   ' || '   v_first := FALSE;
      HTP.P(''{"candidate_id":'' || r.candidate_id);
      HTP.P('',"role_id":'' || NVL(TO_CHAR(r.role_id), ''null''));
      HTP.P('',"candidate_name":'');     iteria_ai.scout_htp_json_str(r.candidate_name);
      HTP.P('',"status":'');             iteria_ai.scout_htp_json_str(r.status);
      HTP.P('',"recommendation":'');     iteria_ai.scout_htp_json_str(r.recommendation);
      HTP.P('',"composite_score":'' || NVL(TO_CHAR(r.composite_score),  ''null''));
      HTP.P('',"overall_score":''   || NVL(TO_CHAR(r.overall_score),    ''null''));
      HTP.P('',"years_experience":''|| NVL(TO_CHAR(r.years_experience), ''null''));
      HTP.P('',"current_role":'');       iteria_ai.scout_htp_json_str(r.current_role);
      HTP.P('',"education":'');          iteria_ai.scout_htp_json_str(r.education);
      HTP.P('',"inferred_gender":'');    iteria_ai.scout_htp_json_str(r.inferred_gender);
      HTP.P('',"intake_mode":'');        iteria_ai.scout_htp_json_str(r.intake_mode);
      HTP.P('',"summary":'');      ' || '      iteria_ai.scout_htp_json_str(r.summary);
      HTP.P('',"invited_at":'');         iteria_ai.scout_htp_json_str(TO_CHAR(r.invited_at,    ''YYYY-MM-DD"T"HH24:MI:SS''));
      HTP.P('',"interviewed_at":'');     iteria_ai.scout_htp_json_str(TO_CHAR(r.interviewed_at,''YYYY-MM-DD"T"HH24:MI:SS''));
      HTP.P('',"skills_matched":'');     iteria_ai.scout_htp_clob(NVL(r.skills_matched, ''[]''));
      HTP.P('',"skills_missing":'');     iteria_ai.scout_htp_clob(NVL(r.skills_missing, ''[]''));
      HTP.P('',"rubric_scores":'');      iteria_ai.scout_htp_clob(NVL(r.rubric_scores,  ''{}''));
      HTP.P('',"strengths":'');          iteria_ai.scout_htp_clob(NVL(r.strengths,      ''[]''));
      HTP.P('',"gaps_to_probe":'');      iteria_ai.scout_htp_clob(NVL(r.gaps_to_probe,  ''[]''));
      HTP.P('',"red_flags":'');          iteria_ai.scout_htp_clob(NVL(r.red_flags,      ''[]''));
      HTP.P(''}'');
    END LOOP;
  END;
  HTP.P('']}'');
END;
');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'candidates',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  -- No bind-variable references in DECLARE initializers. Anything that throws
  -- here escapes the BEGIN block''s EXCEPTION handler and ORDS replaces the
  -- body with its generic InternalServerError JSON — exactly the symptom
  -- we kept seeing on POST /candidates failures.
  v_body  CLOB;
  v_id    NUMBER;
  v_phase VARCHAR2(60) := ''init'';
BEGIN
  v_phase := ''auth'';
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE); HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;

  v_phase := ''parse_body'';
  v_body := iteria_ai.blob_to_clob_utf8(:body);

  v_phase := ''insert_candidate'';
  INSERT INTO iteria_ai.scout_candidates (
    role_id, intake_mode, candidate_name, inferred_gender,
    years_experience, current_role, education,
    skills_matched, skills_missing, rubric_scores, strengths, gaps_to_probe, red_flags,
    overall_score, summary, resume_object_key, ats_candidate_id, status
  ) VALUES (
    JSON_VALUE(v_body,''$.r' || 'ole_id'' RETURNING NUMBER),
    JSON_VALUE(v_body,''$.intake_mode''),
    JSON_VALUE(v_body,''$.candidate_name''),
    NVL(JSON_VALUE(v_body,''$.inferred_gender''),''UNKNOWN''),
    JSON_VALUE(v_body,''$.years_experience'' RETURNING NUMBER),
    JSON_VALUE(v_body,''$.current_role''),
    JSON_VALUE(v_body,''$.education''),
    JSON_QUERY(v_body,''$.skills_matched''),
    JSON_QUERY(v_body,''$.skills_missing''),
    JSON_QUERY(v_body,''$.rubric_scores''),
    JSON_QUERY(v_body,''$.strengths''),
    JSON_QUERY(v_body,''$.gaps_to_probe''),
    JSON_QUERY(v_body,''$.red_flags''),
    JSON_VALUE(v_body,''$.overall_score'' RETURNING NUMBER),
    JSON_VALUE(v_body,''$.summary''),
    JSON_VALUE(v_body,''$.resume_object_key''),
    JSON_VALUE(v_body,''$.ats_candidate_id''),
    NVL(JSON_VALUE(v_body,''$.status''),''PROCESSING'')
  ) RETURNING candidate_id INTO v_id;

  v_phase := ''commit'';
  COMMIT;
  HTP.P(''{"candidate_id":''||v_id||''}'');
EXCEPTION
  WHEN OTHERS THEN
    -- Write the actual error to scout_debug_log via AUTONOMOUS_T' || 'RANSACTION so
    -- the SQLERRM survives no matter what ORDS does to the HTTP response body.
    -- The HTTP response will still be 422 (so the worker''s retry logic stops
    -- and the job is marked failed), but the real diagnostic is in the log
    -- table. Query: SELECT * FROM iteria_ai.scout_debug_log ORDER BY occurred_at DESC.
    iteria_ai.scout_log_error(''POST /candidates'', v_phase, SQLCODE, SQLERRM, v_body);
    ROLLBACK;
    OWA_UTIL.STATUS_LINE(422,''Unprocessable Entity'',FALSE);
    HTP.P(''{"error":"see scout_debug_log"}'');
END;');

