DECLARE v_body CLOB := iteria_ai.blob_to_clob_utf8(:body);
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE); HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;
  UPDATE iteria_ai.scout_candidates SET
    status           = NVL(JSON_VALUE(v_body,''$.status''),           status),
    recommendation   = NVL(JSON_VALUE(v_body,''$.recommendation''),   recommendation),
    composite_score  = NVL(JSON_VALUE(v_body,''$.composite_score'' RETURNING NUMBER), composite_score),
    overall_score    = NVL(JSON_VALUE(v_body,''$.overall_score''   RETURNING NUMBER), overall_score),
    candidate_name   = NVL(JSON_VALUE(v_body,''$.candidate_name''),   candidate_name),
    years_experience = NVL(JSON_VALUE(v_body,''$.years_experience'' RETURNING NUMBER), years_experience),
    current_role     = NVL(JSON_VALUE(v_body,''$.current_role''),     current_role),
    education        = NVL(JSON_VALUE(v_body,''$.education''),        education),
    skills_matched ' || '  = NVL(JSON_QUERY(v_body,''$.skills_matched''),   skills_matched),
    skills_missing   = NVL(JSON_QUERY(v_body,''$.skills_missing''),   skills_missing),
    rubric_scores    = NVL(JSON_QUERY(v_body,''$.rubric_scores''),    rubric_scores),
    strengths        = NVL(JSON_QUERY(v_body,''$.strengths''),        strengths),
    gaps_to_probe    = NVL(JSON_QUERY(v_body,''$.gaps_to_probe''),    gaps_to_probe),
    red_flags        = NVL(JSON_QUERY(v_body,''$.red_flags''),        red_flags),
    summary          = NVL(JSON_VALUE(v_body,''$.summary''),          summary),
    hold_note        = NVL(JSON_VALUE(v_body,''$.hold_note''),        hold_note),
    interviewed_at   = COALESCE(TO_TIMESTAMP_TZ(REPLACE(JSON_VALUE(v_body,''$.interviewed_at''),''Z'',''+00:00''),''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''), interviewed_at),
    invited_at       = COALESCE(TO_TIMESTAMP_TZ(REPLACE(JSON_VALUE(v_body,''$.invited_at''),''Z'',''+00:00''),''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''), invited_at)
  WHERE candidate_id = :id;
  COMMIT;
  HTP.P(''{"ok"' || ':true}'');
END;');

