      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  v_after       NUMBER := NVL(TO_NUMBER(:after), 0);
  v_sess_status VARCHAR2(30);
  v_sess_phase  VARCHAR2(30);
  v_found_turn  BOOLEAN := FALSE;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;
  BEGIN
    SELECT status, current_phase
      INTO v_sess_status, v_sess_phase
      FROM iteria_ai.scout_sessions
     WHERE session_id = :id;
  EXCEPTION WHEN NO_DATA_FOUND THEN
    OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
    HTP.P(''{"error":"session not found"}'');
    RETURN;
  END;

  FOR r IN (
    SELECT turn_id, utterance, metadata
      FROM iteria_ai.scout_transcript
     WHERE session_id = :id AND speaker = ''AVATAR'' AND turn_id > v_after
     ORDER BY turn_id DESC FETCH FIRST 1 ROWS ONLY
  ) LOOP
    v_found_turn := TRUE;
    HTP.P(''{"new":true,"turn_id":'' || r.turn_id);
    HTP.P('',"utterance":'');     iteria_ai.scout_htp_json_str(r.utterance);
    HT' || 'P.P('',"phase":'');         iteria_ai.scout_htp_json_str(v_sess_phase);
    HTP.P('',"session_status":'');iteria_ai.scout_htp_json_str(v_sess_status);
    HTP.P('',"metadata":'');      iteria_ai.scout_htp_clob(NVL(r.metadata, ''{}''));
    HTP.P(''}'');
    RETURN;
  END LOOP;

  IF NOT v_found_turn THEN
    HTP.P(''{"new":false,"session_status":'');
    iteria_ai.scout_htp_json_str(v_sess_status);
    HTP.P('',"phase":'');
    iteria_ai.scout_htp_json_str(v_sess_phase);
    HTP.P(''}'');
  END IF;
END;
');

