      ''candidate_name'' VALUE r.candidate_name, ''overall_score'' VALUE r.overall_score,
      ''composite_score'' VALUE r.composite_score, ''recommendation'' VALUE r.recommendation,
      ''summary'' VALUE r.summary,
      ''ranked_at'' VALUE TO_CHAR(r.ranked_at, ''YYYY-MM-DD"T"HH24:MI:SS'')
    ));
  END LOOP;
  HTP.' || 'P('']}'');
