'
DECLARE v_body CLOB := iteria_ai.blob_to_clob_utf8(:body);
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE); HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;
  MERGE INTO iteria_ai.scout_shortlist s
  USING (SELECT
           JSON_VALUE(v_body,''$.role_id''      RETURNING NUMBER) AS role_id,
           JSON_VALUE(v_body,''$.candidate_id'' RETURNING NUMBER) AS candidate_id,
           JSON_VALUE(v_body,''$.composite_score'' RETURNING NUMBER) AS composite_score,
           JSON_VALUE(v_body,''$.recommendation'') AS recommendation,
           SYSTIMESTAMP AS ranked_at
         FROM dual) src
  ON (s.role_id = src.role_id AND s.candidate_id = src.candidate_id)
  WHEN MATCHED THEN UPDATE SET
    s.composite_score = src.composite_score,
    s.recommendation  = src.recommendation,
    s.ranked_at       = src.ranked_at
  WHEN NOT MATCHED THEN INSERT (role_id, candidate_id, composite_score, recommendation, ranked_at)
    VALUES (src.rol' || 'e_id, src.candidate_id, src.composite_score, src.recommendation, src.ranked_at);
  COMMIT;
  HTP.P(''{"ok":true}'');
END;');

