      FROM iteria_ai.scout_sessions
     WHERE candidate_id = :id
     ORDER BY session_id DESC
  ) LOOP
    IF v_first THEN v_first := FALSE; ELSE HTP.P('',''); END IF;
    HTP.P(JSON_OBJECT(
