      ''answers_submitted'' VALUE r.answers_submitte' || 'd,
      ''invited_at''        VALUE TO_CHAR(r.invited_at,        ''YYYY-MM-DD"T"HH24:MI:SS''),
      ''started_at''        VALUE TO_CHAR(r.started_at,        ''YYYY-MM-DD"T"HH24:MI:SS''),
      ''completed_at''      VALUE TO_CHAR(r.completed_at,      ''YYYY-MM-DD"T"HH24:MI:SS''),
      ''last_activity_at''  VALUE TO_CHAR(r.last_activity_at,  ''YYYY-MM-DD"T"HH24:MI:SS''),
      ''expires_at''        VALUE TO_CHAR(CAST(r.expires_at AS TIMESTAMP), ''YYYY-MM-DD"T"HH24:MI:SS'')
