  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'roles/:id/resumes/upload',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'roles/:id/resumes/upload',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  -- Note: NO bind-variable references in the DECLARE initializers. Exceptions
  -- that fire when evaluating an initializer in DECLARE are NOT caught by the
  -- BEGIN block''s EXCEPTION handler — they propagate up to ORDS, which
  -- replaces the body with its generic Problem+JSON error. All :body / :filename
  -- access must happen inside BEGIN.
  v_staging_id NUMBER;
  v_job_id     NUMBER;
  v_size       NUMBER;
  v_filename   VARCHAR2(500);
  v_ctype      VARCHAR2(100);
  v_phase      VARCHAR2(60) := ''init'';
BEGIN
  v_phase := ''auth'';
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"unauthorized"}'');
    RETURN;
  END IF;

  v_phase := ''parse_inputs'';
  v_filename := NVL(:filename, ''resume_'' || TO_CHAR(SYSTIMESTAMP,''YYYYMMDDHH24MISS'') || ''.pdf'');
  v_ctype := CASE
    WHEN LOWER(v_filename) LIKE ''%.pdf''  THEN ''application/pdf''
    WHEN LOWER(v_filename) LIKE ''%.docx'' THEN ''application/vnd.openxml' || 'formats-officedocument.wordprocessingml.document''
    WHEN LOWER(v_filename) LIKE ''%.doc''  THEN ''application/msword''
    ELSE ''application/octet-stream'' END;

  -- Reference :body ONCE inside a single INSERT statement, alongside
  -- DBMS_LOB.GETLENGTH(:body) in the same SQL. This is the only pattern that
  -- reliably works across ORDS versions for raw-binary uploads — Oracle''s SQL
  -- engine binds :body once and uses it for both column expressions, avoiding
  -- the "second-read returns empty" behavior we hit with CREATETEMPORARY+APPEND.
  -- The RETURNING clause reads back DBMS_LOB.GETLENGTH(file_bytes) so we can
  -- verify what actually persisted vs. what the request said it sent.
  v_phase := ''insert_staging'';
  INSERT INTO iteria_ai.scout_staging
    (role_id, filename, content_type, file_bytes, byte_size, status, uploaded_by)
  VALUES
    (:id, v_filename, v_ctype, :body, NVL(DBMS_LOB.GETLENGTH(:body), 0), ''PENDING'', ''hr-upload'')
  RETURNING staging_id, DBMS_LOB.GETLENGTH(file' || '_bytes)
       INTO v_staging_id, v_size;

  v_phase := ''verify_blob_persisted'';
  IF v_size IS NULL OR v_size = 0 THEN
    ROLLBACK;
    -- Use 422 instead of 500 because ORDS in some versions overrides 500
    -- response bodies with a generic InternalServerError JSON, swallowing
    -- our diagnostic detail. 422 ("Unprocessable Entity") is the correct
    -- semantic here (request was syntactically OK but couldn''t be processed)
    -- and ORDS lets the body through unchanged.
    OWA_UTIL.STATUS_LINE(422,''Unprocessable Entity'',FALSE);
    HTP.P(JSON_OBJECT(
      ''error'' VALUE ''file_bytes persisted as NULL or zero-length after INSERT'',
      ''staging_id_attempted'' VALUE v_staging_id,
      ''actual_blob_size'' VALUE v_size,
      ''hint'' VALUE '':body bind may be empty in this ORDS context; check Content-Type and request body''
    ));
    RETURN;
  END IF;

  v_phase := ''insert_job'';
  INSERT INTO iteria_ai.scout_jobs (job_type, status, role_id, payload_json, created_at)
  VALUES (''INGE' || 'ST'', ''PENDING'', :id,
          JSON_OBJECT(''intake_mode'' VALUE ''STAGING'',
                      ''staging_id'' VALUE v_staging_id,
                      ''filename''   VALUE v_filename,
                      ''role_id''    VALUE :id),
          SYSTIMESTAMP)
  RETURNING job_id INTO v_job_id;

  v_phase := ''commit'';
  COMMIT;

