  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'staging/:id',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'staging/:id',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  v_blob   BLOB;
  v_ctype  VARCHAR2(100);
  v_name   VARCHAR2(500);
  v_size   NUMBER;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE); HTP.P(''{"error":"unauthorized"}''); RETURN;
  END IF;

  -- Phase 1: fetch and validate. Any error here can still return JSON
  -- because we haven''t started the BLOB response yet.
  BEGIN
    SELECT file_bytes, content_type, filename
      INTO v_blob, v_ctype, v_name
      FROM iteria_ai.scout_staging
     WHERE staging_id = :id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
      HTP.P(''{"error":"staging row not found","staging_id":'' || :id || ''}'');
      RETURN;
    WHEN OTHERS THEN
      OWA_UTIL.STATUS_LINE(500,''Internal Server Error'',FALSE);
      HTP.P(JSON_OBJECT(
        ''error'' VALUE SQLERRM,
        ''code''  VALUE SQLCODE,
        ''where'' VALUE ''GET /staging/:id SELECT''
      ));
      RETURN;
  END;

  -- Verify the BLOB is a' || 'ctually present and non-empty before handing it to
  -- WPG_DOCLOAD. A NULL or zero-length BLOB makes DOWNLOAD_FILE throw
  -- ORA-22275 (invalid LOB locator) with no useful diagnostic, which is the
  -- exact failure mode we hit in production: the row existed, the upload
  -- toast claimed success, but file_bytes was empty so the worker''s GET
  -- crashed mid-response.
  v_size := NVL(DBMS_LOB.GETLENGTH(v_blob), 0);
  IF v_size = 0 THEN
    OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
    HTP.P(JSON_OBJECT(
      ''error'' VALUE ''staging row has no file bytes'',
      ''staging_id'' VALUE :id,
      ''filename'' VALUE v_name,
      ''blob_length'' VALUE v_size,
      ''hint'' VALUE ''upload likely failed to write file_bytes; check the upload handler''
    ));
    RETURN;
  END IF;

  -- Phase 2: stream the BLOB. Once MIME_HEADER fires the response is
  -- committed; any error after this point produces a partial download
  -- rather than a JSON error. Keep these three calls tight and minimal.
  OWA' || '_UTIL.MIME_HEADER(NVL(v_ctype,''application/octet-stream''), FALSE);
  HTP.P(''Content-Disposition: attachment; filename="'' || v_name || ''"'');
  HTP.P(''Content-Length: '' || v_size);
  OWA_UTIL.HTTP_HEADER_CLOSE;
  WPG_DOCLOAD.DOWNLOAD_FILE(v_blob);
END;');

