      IF v_reveal THEN
        v_shown := v_key;
      ELSIF v_key IS NULL THEN
        v_shown := NULL;
      ELSIF LENGTH(v_key) > 4 THEN
        v_shown := LPAD(SUBSTR(v_key, -4), LENGTH(v_key' || '), ''*'');
