    RETURN;
  END IF;
  v_body := iteria_ai.blob_to_clob_utf8(:body);

  UPDATE iteria_ai.scout_connectors
     SET enabled = CASE
                     WHEN JSON_VALUE(v_body,''$.enabled'') = ''true''  THEN ''Y''
                     WHEN JSON_VALUE(v_body,''$.enabled'') = ''false'' THEN ''N''
                     ELSE enabled
                   END,
         config_json = NVL(JSON_QUERY(v_body, ''$.config''), config_json),
         last_test_at       = COALESCE(TO_TIMESTAMP_TZ(JSON_VALUE(v_body,''$.last_test_at''),
                                       ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''), last_test_at),
         last_test_status   = NVL(JSON_VALUE(v_body,''$.last_test_status''),   last_test_status),
         last_test_message  = NVL(JSON_VALUE(v_body,''$.last_test_message''),  last_test_message),
         last_' || 'test_details  = NVL(JSON_QUERY(v_body,''$.last_test_details''),  last_test_details),
         last_sync_at       = COALESCE(TO_TIMESTAMP_TZ(JSON_VALUE(v_body,''$.last_sync_at''),
                                       ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''), last_sync_at),
         last_sync_status   = NVL(JSON_VALUE(v_body,''$.last_sync_status''),   last_sync_status),
         last_sync_message  = NVL(JSON_VALUE(v_body,''$.last_sync_message''),  last_sync_message),
         last_sync_stats    = NVL(JSON_QUERY(v_body,''$.last_sync_stats''),    last_sync_stats),
         updated_at = SYSTIMESTAMP
   WHERE connector_name = :name;
  v_rows := SQL%ROWCOUNT;
  COMMIT;
  IF v_rows = 0 THEN
    OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
    HTP.P(''{"error":"connector not found"}'');
  ELSE
    HTP.P(JSON_OBJECT(''ok'' VALUE 1, ''connector_name'' VALUE :name));
  END IF;
END;
');

