  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'connectors/juicebox/csv-import',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'scout-hooks',
      p_pattern        => 'connectors/juicebox/csv-import',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  v_body         CLOB;
  v_role_id      NUMBER;
  v_count_queued NUMBER := 0;
  v_count_skipped NUMBER := 0;
BEGIN
  IF NOT iteria_ai.scout_check_api_key(:api_key) THEN
    OWA_UTIL.STATUS_LINE(401,''Unauthorized'',FALSE);
    HTP.P(''{"error":"bad api_key"}'');
    RETURN;
  END IF;
  v_body := iteria_ai.blob_to_clob_utf8(:body);
  v_role_id := JSON_VALUE(v_body, ''$.role_id'' RETURNING NUMBER);
  IF v_role_id IS NULL THEN
    OWA_UTIL.STATUS_LINE(400,''Bad Request'',FALSE);
    HTP.P(''{"error":"role_id is required"}'');
    RETURN;
  END IF;

  FOR row IN (
    SELECT jt.candidate_name, jt.email, jt.profile_url, jt.resume_text
      FROM JSON_TABLE(v_body, ''$.rows[*]''
             COLUMNS (
               candidate_name VARCHAR2(255) PATH ''$.candidate_name'',
               email          VARCHAR2(255) PATH ''$.email'',
               profile_url    VARCHAR2(500) PATH ''$.profile_url'',
               resume_text    CLOB          PATH ''$.resume_text''
             )) jt
  ) LOOP
    IF row' || '.candidate_name IS NULL OR row.email IS NULL OR row.resume_text IS NULL THEN
      v_count_skipped := v_count_skipped + 1;
      CONTINUE;
    END IF;

    DECLARE
      v_staging_id   NUMBER;
      v_candidate_id NUMBER;
    BEGIN
      -- 1) stash the synthetic resume text
      INSERT INTO iteria_ai.scout_csv_staging (source_system, resume_text)
      VALUES (''juicebox'', row.resume_text)
      RETURNING staging_id INTO v_staging_id;

      -- 2) write a PROCESSING placeholder candidate (so HR sees them immediately)
      INSERT INTO iteria_ai.scout_candidates
        (role_id, intake_mode, candidate_name, inferred_gender,
         years_experience, current_role, education,
         skills_matched, skills_missing, rubric_scores,
         strengths, gaps_to_probe, red_flags,
         overall_score, summary,
         resume_object_key, ats_candidate_id, status, created_at)
      VALUES
        (v_role_id, ''JUICEBOX_CSV'', row.candidate_name, ''UNKNOWN'',
         0, NULL, NULL,
         ''' || '[]'', ''[]'', ''{}'',
         ''[]'', ''[]'', ''[]'',
         0, NULL,
         NULL, row.email, ''PROCESSING'', SYSTIMESTAMP)
      RETURNING candidate_id INTO v_candidate_id;

      -- 3) link to the Juicebox source (use email as external_id since
      --    Juicebox CSV rows don''t carry a stable internal id)
      MERGE INTO iteria_ai.scout_external_candidates t
      USING (SELECT v_candidate_id AS cid, ''juicebox'' AS src,
                    row.email AS eid, row.profile_url AS url FROM dual) s
         ON (t.candidate_id = s.cid AND t.source_system = s.src)
       WHEN NOT MATCHED THEN
         INSERT (candidate_id, source_system, external_id, external_url)
         VALUES (s.cid, s.src, s.eid, s.url);

      -- 4) queue the INGEST job
      INSERT INTO iteria_ai.scout_jobs (job_type, status, payload_json,
                                        role_id, candidate_id, created_at)
      VALUES (
        ''INGEST'', ''PENDING'',
        JSON_OBJECT(
          ''intake_mode''  VALUE ''JUICEBOX_CSV'',
' || '          ''role_id''      VALUE v_role_id,
          ''candidate_id'' VALUE v_candidate_id,
          ''staging_id''   VALUE v_staging_id
        ),
        v_role_id, v_candidate_id, SYSTIMESTAMP
      );

      v_count_queued := v_count_queued + 1;
    END;
  END LOOP;
  COMMIT;
  HTP.P(JSON_OBJECT(
    ''ok'' VALUE 1,
    ''queued''  VALUE v_count_queued,
    ''skipped'' VALUE v_count_skipped,
    ''role_id'' VALUE v_role_id
  ));
END;
');

