      p_items_per_page => 25,
      p_status         => 'PUBLISHED',
      p_comments       => 'VALIDATE: complete endpoint set for agent and dashboard');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'tokens',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'Upsert bearer token for tenant+context');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'tokens',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Upsert bearer token for tenant+context',
      p_source         => 
'
DECLARE
    v_body          CLOB;
    v_json          JSON_OBJECT_T;
    v_tenant_id     NUMBER;
    v_cx_context    VARCHAR2(20);
    v_access_token  CLOB;
    v_issued_at     TIMESTAMP;
    v_expires_at    TIMESTAMP;
    v_app_key_hash  VARCHAR2(64);
BEGIN
    v_body         := :body;
    v_json         := JSON_OBJECT_T.parse(v_body);
    v_tenant_id    := v_json.get_number(''tenant_id'');
    v_cx_context   := v_json.get_string(''cx_context'');
    v_access_token := v_json.get_string(''access_token'');
    v_issued_at    := TO_TIMESTAMP(v_json.get_string(''issued_at''), ''YYYY-MM-DD"T"HH24:MI:SS.FF"Z"'');
    v_expires_at   := TO_TIMESTAMP(v_json.get_string(''expires_at''), ''YYYY-MM-DD"T"HH24:MI:SS.FF"Z"'');
    v_app_key_hash := v_json.get_string(''app_key_hash'');

    MERGE INTO ITERIA_AI.VALIDATE_CX_TOKENS t
    USING (SELECT v_tenant_id AS tenant_id, v_cx_context AS cx_context FROM DUAL) s
    ON (t.tenant_id = s.tenant_id AND t.cx_context = s.cx_context)
    WHEN MATCHED THEN UPDATE SET
   ' || '     t.access_token = v_access_token, t.issued_at = v_issued_at,
        t.expires_at   = v_expires_at,   t.app_key_hash = v_app_key_hash,
        t.updated_at   = SYSTIMESTAMP
    WHEN NOT MATCHED THEN INSERT (tenant_id, cx_context, access_token, issued_at, expires_at, app_key_hash)
        VALUES (v_tenant_id, v_cx_context, v_access_token, v_issued_at, v_expires_at, v_app_key_hash);
    COMMIT;
    :status := 200;
    HTP.p(''{"status":"ok","cx_context":"'' || v_cx_context || ''"}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

