      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => NULL,
      p_source         => 
'DECLARE v_body CLOB; v_agent_id VARCHAR2(100); v_status VARCHAR2(20); v_version VARCHAR2(50); v_tenant_id NUMBER; v_cpu NUMBER; v_mem NUMBER; v_pending NUMBER; v_running NUMBER; BEGIN v_body:=:body_text; APEX_JSON.parse(v_body); v_agent_id:=APEX_JSON.get_varchar2(''agent_id''); v_status:=LOWER(NVL(APEX_JSON.get_varchar2(''status''),''idle'')); v_version:=APEX_JSON.get_varchar2(''version''); v_tenant_id:=APEX_JSON.get_number(''tenant_id''); v_cpu:=COALESCE(APEX_JSON.get_number(''cpu_usage''),APEX_JSON.get_number(''cpu_pct'')); v_mem:=COALESCE(APEX_JSON.get_number(''mem_usage''),APEX_JSON.get_number(''mem_pct'')); v_pending:=APEX_JSON.get_number(''pending_jobs''); v_running:=APEX_JSON.get_number(''running_jobs''); IF v_status NOT IN (''idle'',''busy'',''offline'',''error'',''active'') THEN v_status:=''active''; END IF; IF v_agent_id IS NULL THEN :status:=400; HTP.p(''{"error":"agent_id required"}''); RETURN; END IF; MERGE INTO ITERIA_AI.VALIDATE_AGENTS a USING (SELECT v_agent_id AS agent_id FROM DUAL) s ON (a.agent_id=s.ag' || 'ent_id) WHEN MATCHED THEN UPDATE SET a.status=v_status, a.version=v_version, a.last_seen=SYSTIMESTAMP, a.health_json=v_body WHEN NOT MATCHED THEN INSERT (agent_id,tenant_id,status,version,health_json,last_seen,created_at) VALUES (v_agent_id,NVL(v_tenant_id,1),v_status,v_version,v_body,SYSTIMESTAMP,SYSTIMESTAMP); DELETE FROM ITERIA_AI.VALIDATE_AGENT_HEARTBEATS WHERE last_seen < SYSTIMESTAMP - INTERVAL ''1'' DAY; INSERT INTO ITERIA_AI.VALIDATE_AGENT_HEARTBEATS (status,last_seen,cpu_pct,mem_pct,pending_jobs,running_jobs) VALUES (v_status,SYSTIMESTAMP,v_cpu,v_mem,NVL(v_pending,0),NVL(v_running,0)); COMMIT; :status:=200; HTP.p(''{"status":"ok","agent_id":"'' || v_agent_id || ''"}''); EXCEPTION WHEN OTHERS THEN ROLLBACK; :status:=500; HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''\"'') || ''"}''); END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'agent/heartbeat',
      p_method             => 'POST',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'agent/heartbeat',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_mimes_allowed  => NULL,
      p_comments       => 'List agent health records (dashboard probe)',
      p_source         => 
'
SELECT a.agent_id,
       a.status,
       a.version,
       TO_CHAR(a.last_seen, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS last_seen,
       h.cpu_pct,
       h.mem_pct,
       h.pending_jobs,
       h.running_jobs
  FROM ITERIA_AI.VALIDATE_AGENTS a
  LEFT JOIN (
        SELECT cpu_pct, mem_pct, pending_jobs, running_jobs
          FROM ITERIA_AI.VALIDATE_AGENT_HEARTBEATS
         ORDER BY last_seen DESC
         FETCH FIRST 1 ROW ONLY
       ) h ON 1 = 1
 ORDER BY a.last_seen DESC
 FETCH FIRST :limit ROWS ONLY');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'agent/heartbeat',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
