  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'jobs',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_mimes_allowed  => NULL,
      p_comments       => 'fix_flow_run_visibility — list jobs incl payload_json',
      p_source         => 
'SELECT j.job_id, j.tenant_id, j.job_type, j.doc_id, j.run_id, j.batch_id,
        j.status, j.agent_id, j.priority, j.error_msg,
        d.doc_name,
        j.payload_json,
        TO_CHAR(j.created_at,   ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS created_at,
        TO_CHAR(j.updated_at,   ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS updated_at,
        TO_CHAR(j.claimed_at,   ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS claimed_at,
        TO_CHAR(j.completed_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS completed_at
   FROM ITERIA_AI.VALIDATE_JOBS j
   LEFT JOIN ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS d ON d.id = j.doc_id
  WHERE (:status IS NULL OR j.status = :status)
  ORDER BY j.priority, j.created_at DESC
  FETCH FIRST NVL(:limit, 500) ROWS ONLY');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'jobs',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'fix_flow_run_visibility — enqueue + script_runs queued row',
      p_source         => 
'DECLARE
  v_body       CLOB := :body_text;
  v_job_type   VARCHAR2(100);
  v_tenant_id  NUMBER;
  v_priority   NUMBER;
  v_target     VARCHAR2(100);
  v_cred_set   VARCHAR2(100);
  v_doc_id     NUMBER;
  v_new_id     NUMBER;
  v_inner      CLOB;
  v_flow_id    NUMBER;
BEGIN
  IF v_body IS NULL OR DBMS_LOB.GETLENGTH(v_body) = 0 THEN
    :status := 400;
    HTP.P(''{"err":"empty body"}'');
    RETURN;
  END IF;

  APEX_JSON.parse(v_body);

  BEGIN v_job_type  := APEX_JSON.get_varchar2(p_path => ''job_type'');   EXCEPTION WHEN OTHERS THEN v_job_type  := NULL; END;
  BEGIN v_tenant_id := APEX_JSON.get_number(p_path => ''tenant_id'');    EXCEPTION WHEN OTHERS THEN v_tenant_id := NULL; END;
  BEGIN v_priority  := APEX_JSON.get_number(p_path => ''priority'');     EXCEPTION WHEN OTHERS THEN v_priority  := NULL; END;
  BEGIN v_target    := APEX_JSON.get_varchar2(p_path => ''target_agent_id''); EXCEPTION WHEN OTHERS THEN v_target := NULL; END;
  BEGIN v_cred_set  := APEX_JSON.get_varchar2(p_path => ''crede' || 'ntial_set'');  EXCEPTION WHEN OTHERS THEN v_cred_set := NULL; END;
  BEGIN v_doc_id    := APEX_JSON.get_number(p_path => ''doc_id'');       EXCEPTION WHEN OTHERS THEN v_doc_id := NULL; END;

  IF v_job_type IS NULL THEN
    :status := 400;
    HTP.P(''{"err":"missing job_type"}'');
    RETURN;
  END IF;

  INSERT INTO ITERIA_AI.VALIDATE_JOBS (
    job_type, status, payload_json, tenant_id, priority,
    agent_id, credential_set, doc_id, created_at, updated_at
  )
  VALUES (
    v_job_type, ''pending'', v_body, NVL(v_tenant_id,1), NVL(v_priority,5),
    v_target, v_cred_set, v_doc_id, SYSTIMESTAMP, SYSTIMESTAMP
  )
  RETURNING job_id INTO v_new_id;

  -- Parse nested payload_json string for process-flow runs
  BEGIN
    v_inner := APEX_JSON.get_varchar2(p_path => ''payload_json'');
  EXCEPTION WHEN OTHERS THEN v_inner := NULL;
  END;

  v_flow_id := NULL;
  IF v_inner IS NOT NULL AND LENGTH(TRIM(v_inner)) > 2 THEN
    BEGIN
      v_flow_id := JSON_VALUE(v_inner, ''$.linked_flow_id'' RETURNING NUMB' || 'ER NULL ON ERROR);
      IF v_flow_id IS NULL THEN
        v_flow_id := JSON_VALUE(v_inner, ''$.flow_id'' RETURNING NUMBER NULL ON ERROR);
      END IF;
    EXCEPTION WHEN OTHERS THEN v_flow_id := NULL;
    END;
  END IF;
  IF v_flow_id IS NULL THEN
    BEGIN
      v_flow_id := APEX_JSON.get_number(p_path => ''linked_flow_id'');
    EXCEPTION WHEN OTHERS THEN
      BEGIN v_flow_id := APEX_JSON.get_number(p_path => ''flow_id''); EXCEPTION WHEN OTHERS THEN v_flow_id := NULL; END;
    END;
  END IF;

  IF v_doc_id IS NULL AND v_inner IS NOT NULL AND LENGTH(TRIM(v_inner)) > 2 THEN
    BEGIN
      v_doc_id := JSON_VALUE(v_inner, ''$.document_id'' RETURNING NUMBER NULL ON ERROR);
      IF v_doc_id IS NULL THEN
        v_doc_id := JSON_VALUE(v_inner, ''$.doc_id'' RETURNING NUMBER NULL ON ERROR);
      END IF;
    EXCEPTION WHEN OTHERS THEN v_doc_id := NULL;
    END;
    IF v_doc_id IS NOT NULL THEN
      UPDATE ITERIA_AI.VALIDATE_JOBS
         SET doc_id = v_doc_id
       WHERE job_id = v_new_id;
    E' || 'ND IF;
  END IF;

  IF LOWER(v_job_type) = ''parse_document'' THEN
    UPDATE ITERIA_AI.VALIDATE_JOBS
       SET run_id = v_new_id
     WHERE job_id = v_new_id;
    IF v_doc_id IS NOT NULL THEN
      UPDATE ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
         SET parse_status = ''parse_pending'',
             updated_at   = SYSTIMESTAMP
       WHERE id = v_doc_id;
    END IF;
  END IF;

  IF v_job_type = ''validate_script'' THEN
    UPDATE ITERIA_AI.VALIDATE_JOBS
       SET run_id = v_new_id
     WHERE job_id = v_new_id;

    MERGE INTO ITERIA_AI.VALIDATE_SCRIPT_RUNS s
    USING (SELECT v_new_id AS run_id FROM DUAL) src
    ON (s.run_id = src.run_id)
    WHEN MATCHED THEN UPDATE SET
         s.status          = ''queued'',
         s.tenant_id       = NVL(v_tenant_id, NVL(s.tenant_id, 1)),
         s.doc_id          = NVL(v_doc_id, s.doc_id),
         s.linked_flow_id  = NVL(v_flow_id, s.linked_flow_id),
         s.created_at      = COALESCE(s.created_at, SYSTIMESTAMP)
    WHEN NOT MATCHED THEN INSE' || 'RT (
         run_id, doc_id, tenant_id, status, linked_flow_id, created_at)
    VALUES (
         v_new_id, v_doc_id, NVL(v_tenant_id, 1), ''queued'', v_flow_id, SYSTIMESTAMP);
  END IF;

  COMMIT;

  :status := 200;
  HTP.P(''{"job_id":'' || v_new_id || '',"run_id":'' || v_new_id || '',"status":"pending"}'');
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.P(''{"err":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;');

