  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/clear-stuck',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Fail stuck VALIDATE_JOBS + script runs (honors minutes/hours/all)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/clear-stuck',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Operator: fail pending/claimed/running jobs (not re-queue)',
      p_source         => 
'
DECLARE
    v_json    JSON_OBJECT_T;
    v_mins    NUMBER;
    v_hours   NUMBER;
    v_all     VARCHAR2(10);
    v_cutoff  TIMESTAMP;
    v_count   NUMBER := 0;
    v_runs    NUMBER := 0;
BEGIN
    BEGIN
        v_json := JSON_OBJECT_T.parse(NVL(:body_text, ''{}''));
    EXCEPTION WHEN OTHERS THEN
        v_json := JSON_OBJECT_T();
    END;
    v_all := LOWER(NVL(v_json.get_string(''all''), ''false''));
    BEGIN v_mins := v_json.get_number(''minutes''); EXCEPTION WHEN OTHERS THEN v_mins := NULL; END;
    BEGIN v_hours := v_json.get_number(''hours''); EXCEPTION WHEN OTHERS THEN v_hours := NULL; END;

    IF v_all IN (''true'', ''1'', ''y'') OR NVL(v_mins, -1) = 0 OR NVL(v_hours, -1) = 0 THEN
        v_cutoff := NULL;
    ELSIF v_mins IS NOT NULL AND v_mins > 0 THEN
        v_cutoff := SYSTIMESTAMP - NUMTODSINTERVAL(v_mins, ''MINUTE'');
    ELSIF v_hours IS NOT NULL AND v_hours > 0 THEN
        v_cutoff := SYSTIMESTAMP - NUMTODSINTERVAL(v_hours * 60, ''MINUTE'');
    ELSE
        v_cutoff := NULL;
    END' || ' IF;

    UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS sr
       SET status       = ''failed'',
           completed_at = NVL(sr.completed_at, SYSTIMESTAMP)
     WHERE LOWER(NVL(sr.status, ''x'')) IN (
               ''queued'', ''running'', ''pending'', ''claimed''
           )
       AND (v_cutoff IS NULL OR sr.created_at < v_cutoff)
       AND EXISTS (
               SELECT 1
                 FROM ITERIA_AI.VALIDATE_JOBS j
                 JOIN ITERIA_AI.VALIDATE_TENANTS t ON t.tenant_id = j.tenant_id
                WHERE (j.job_id = sr.run_id OR j.run_id = sr.run_id)
                  AND j.tenant_id = sr.tenant_id
                  AND t.is_active = ''Y''
                  AND LOWER(t.api_key_hash) = LOWER(
                        STANDARD_HASH(NVL(:x_tenant_key, ''__none__''), ''SHA256'')
                      )
                  AND LOWER(NVL(j.status, ''x'')) IN (
                        ''pending'', ''claimed'', ''running'', ''queued'', ''analyzing''
                      )
                  AND (v_cutoff IS NUL' || 'L OR NVL(j.claimed_at, j.created_at) < v_cutoff)
           );
    v_runs := SQL%ROWCOUNT;

    UPDATE ITERIA_AI.VALIDATE_JOBS j
       SET status     = ''failed'',
           error_msg  = NVL(j.error_msg, ''Cleared stuck (operator)''),
           agent_id   = NULL,
           claimed_at = NULL,
           updated_at = SYSTIMESTAMP
     WHERE LOWER(NVL(j.status, ''x'')) IN (
               ''pending'', ''claimed'', ''running'', ''queued'', ''analyzing''
           )
       AND (v_cutoff IS NULL OR NVL(j.claimed_at, j.created_at) < v_cutoff)
       AND EXISTS (
               SELECT 1
                 FROM ITERIA_AI.VALIDATE_TENANTS t
                WHERE t.tenant_id = j.tenant_id
                  AND t.is_active = ''Y''
                  AND LOWER(t.api_key_hash) = LOWER(
                        STANDARD_HASH(NVL(:x_tenant_key, ''__none__''), ''SHA256'')
                      )
           );
    v_count := SQL%ROWCOUNT;

    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"failed_count":'' || v_count ||
' || '          '',"runs_failed":'' || v_runs ||
          '',"cleared":'' || v_count || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'' );
END;');

