  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/:job_id/fail',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Mark job failed with error');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/:job_id/fail',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Mark job failed and update doc parse status',
      p_source         => 
'DECLARE
    v_error    VARCHAR2(4000) := JSON_VALUE(:body_text, ''$.error'');
    v_doc_id   NUMBER;
    v_job_type VARCHAR2(100);
BEGIN
    SELECT doc_id, job_type
      INTO v_doc_id, v_job_type
      FROM ITERIA_AI.VALIDATE_JOBS
     WHERE job_id = :job_id;

    UPDATE ITERIA_AI.VALIDATE_JOBS
    SET    status       = ''failed'',
           error_msg    = v_error,
           completed_at = SYSTIMESTAMP,
           updated_at   = SYSTIMESTAMP
    WHERE  job_id = :job_id;

    -- Only parse jobs own parse_status on the document row. A failed test run
    -- must not mark the uploaded script as "failed to parse".
    IF v_doc_id IS NOT NULL AND LOWER(v_job_type) = ''parse_document'' THEN
        UPDATE ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
        SET    parse_status = ''failed'',
               updated_at   = SYSTIMESTAMP
        WHERE  id = v_doc_id;
    END IF;

    COMMIT;
    :status := 200;
    HTP.p(''{"status":"failed","job_id":'' || :job_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBA' || 'CK;
    :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'');
END;');

