      p_module_name    => 'validate',
      p_pattern        => 'scripts/ingest',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Ingest an uploaded test script file');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'scripts/ingest',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => '008 — upsert document + full parse payload (auto_run, credentials)',
      p_source         => 
'DECLARE
    v_body           CLOB;
    v_doc_id         NUMBER;
    v_job_id         NUMBER;
    v_tenant_id      NUMBER;
    v_doc_name       VARCHAR2(500);
    v_doc_type       VARCHAR2(20);
    v_triggered_by   VARCHAR2(50);
    v_cred_set       VARCHAR2(100);
    v_batch_id       VARCHAR2(100);
    v_site_profile   VARCHAR2(100);
    v_content_b64    CLOB;
    v_auto_run       VARCHAR2(10);
    v_parse_payload  CLOB;
BEGIN
    v_body := iteria_ai.blob_to_clob_utf8(:body);
    IF v_body IS NULL OR LENGTH(v_body) = 0 THEN
        :status := 400;
        HTP.P(''{"error":"empty body"}'');
        RETURN;
    END IF;

    v_tenant_id    := NVL(JSON_VALUE(v_body, ''$.tenant_id'' RETURNING NUMBER), 1);
    v_doc_name     := JSON_VALUE(v_body, ''$.doc_name'');
    v_doc_type     := NVL(JSON_VALUE(v_body, ''$.doc_type''), ''txt'');
    v_triggered_by := NVL(JSON_VALUE(v_body, ''$.triggered_by''), ''ui_upload'');
    v_cred_set     := JSON_VALUE(v_body, ''$.credential_set'');
    v_batch_id     := JSON_VAL' || 'UE(v_body, ''$.batch_id'');
    v_site_profile := JSON_VALUE(v_body, ''$.site_profile_name'');
    v_content_b64  := JSON_VALUE(v_body, ''$.content_b64'' RETURNING CLOB);
    v_auto_run     := LOWER(NVL(JSON_VALUE(v_body, ''$.auto_run''), ''false''));

    IF v_doc_name IS NULL OR LENGTH(TRIM(v_doc_name)) = 0 THEN
        :status := 400;
        HTP.P(''{"error":"doc_name required"}'');
        RETURN;
    END IF;

    BEGIN
        SELECT id INTO v_doc_id
          FROM ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
         WHERE tenant_id = v_tenant_id
           AND doc_name  = v_doc_name;

        UPDATE ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
           SET doc_type       = v_doc_type,
               content_b64    = v_content_b64,
               file_size      = DBMS_LOB.GETLENGTH(v_content_b64),
               triggered_by   = v_triggered_by,
               credential_set = v_cred_set,
               parse_status   = ''parse_pending'',
               step_count     = NULL,
               path_count    ' || ' = NULL,
               uploaded_at    = SYSTIMESTAMP,
               updated_at     = SYSTIMESTAMP
         WHERE id = v_doc_id;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            INSERT INTO ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
                (tenant_id, doc_name, doc_type, content_b64, file_size,
                 triggered_by, credential_set, parse_status)
            VALUES
                (v_tenant_id, v_doc_name, v_doc_type,
                 v_content_b64, DBMS_LOB.GETLENGTH(v_content_b64),
                 v_triggered_by, v_cred_set, ''parse_pending'')
            RETURNING id INTO v_doc_id;
    END;

    v_parse_payload :=
        ''{"document_id":'' || v_doc_id
        || '',"doc_id":'' || v_doc_id
        || '',"document_type":"'' || REPLACE(v_doc_type, ''"'', ''\"'') || ''"''
        || '',"tenant_id":'' || v_tenant_id
        || '',"doc_name":"'' || REPLACE(v_doc_name, ''"'', ''\"'') || ''"''
        || CASE WHEN v_auto_run IN (''true'',''1'',''yes'') THEN '',"auto_run":true'' ELSE '',"auto_run":f' || 'alse'' END
        || CASE WHEN v_cred_set IS NOT NULL
                THEN '',"credential_set":"'' || REPLACE(v_cred_set, ''"'', ''\"'') || ''"'' ELSE '''' END
        || CASE WHEN v_site_profile IS NOT NULL
                THEN '',"site_profile_name":"'' || REPLACE(v_site_profile, ''"'', ''\"'') || ''"'' ELSE '''' END
        || CASE WHEN v_batch_id IS NOT NULL
                THEN '',"batch_id":"'' || REPLACE(v_batch_id, ''"'', ''\"'') || ''"'' ELSE '''' END
        || ''}'';

    INSERT INTO ITERIA_AI.VALIDATE_JOBS (tenant_id, job_type, doc_id, batch_id, payload_json)
    VALUES (v_tenant_id, ''parse_document'', v_doc_id, v_batch_id, v_parse_payload)
    RETURNING job_id INTO v_job_id;

    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"doc_id":'' || v_doc_id
       || '',"id":'' || v_doc_id
       || '',"job_id":'' || v_job_id
       || '',"status":"parse_queued"}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

