  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'documents/:doc_id/complete',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Update document parse status and step count',
      p_source         => 
'
DECLARE
    v_json       JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_parse_status VARCHAR2(30) := NVL(v_json.get_string(''parse_status''), ''parsed'');
    v_step_count NUMBER          := NVL(v_json.get_number(''step_count''), 0);
    v_path_count NUMBER          := NVL(v_json.get_number(''path_count''), 0);
BEGIN
