    SET parse_status = v_parse_status,
        step_count   = v_step_count,
        path_count   = v_path_count,
        updated_at   = SYSTIMESTAMP
    WHERE id = :doc_id;
    COMMIT;
    :status := 200;
    HTP.p(''{"status":"'' || v_parse_status || ''","doc_id":'' || :doc_id || ''}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

