  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'documents/:doc_id/archive',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => '013 — soft-delete uploaded document',
      p_source         => 
'DECLARE
  l_doc_id   NUMBER := TO_NUMBER(:doc_id);
  l_rows     NUMBER := 0;
BEGIN
  UPDATE ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
     SET parse_status = ''archived'',
         updated_at   = SYSTIMESTAMP
   WHERE id = l_doc_id
     AND NVL(parse_status, ''x'') <> ''archived'';
  l_rows := SQL%ROWCOUNT;

  UPDATE ITERIA_AI.VALIDATE_JOBS
     SET status     = ''failed'',
         error_msg  = NVL(error_msg, ''Archived from dashboard''),
         updated_at = SYSTIMESTAMP
   WHERE doc_id = l_doc_id
     AND LOWER(NVL(status, ''x'')) IN (
           ''pending'', ''claimed'', ''running'', ''queued'', ''analyzing''
         );

  COMMIT;
  :status := 200;
  HTP.p(''{"ok":true,"doc_id":'' || l_doc_id || '',"updated":'' || l_rows || ''}'');
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' ||
          REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'documents/:doc_id/archive',
      p_method             => 'POST',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'documents/:doc_id/steps',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Persist extracted steps for a document');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'documents/:doc_id/steps',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Store parsed steps JSON against a document',
      p_source         => 
'DECLARE
    l_body       CLOB;
    l_json       JSON_OBJECT_T;
    l_steps      JSON_ARRAY_T;
    l_step_count NUMBER := 0;
    l_path_count NUMBER := 0;
    l_i          NUMBER;
    l_step       JSON_OBJECT_T;
    l_pk         VARCHAR2(500);
BEGIN
    l_body := :body_text;
    IF l_body IS NULL OR DBMS_LOB.GETLENGTH(l_body) = 0 THEN
        l_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;

    IF l_body IS NOT NULL AND DBMS_LOB.GETLENGTH(l_body) > 0 THEN
        l_json := JSON_OBJECT_T.parse(l_body);
        IF l_json.has(''step_count'') THEN
            l_step_count := NVL(l_json.get_number(''step_count''), 0);
        END IF;
        IF l_json.has(''path_count'') THEN
            l_path_count := NVL(l_json.get_number(''path_count''), 0);
        END IF;
        IF l_json.has(''steps'') THEN
            l_steps := l_json.get_array(''steps'');
            IF l_step_count = 0 THEN
                l_step_count := l_steps.get_size;
            END IF;
            IF l_path_count = 0 AND l_s' || 'tep_count > 0 THEN
                FOR l_i IN 0 .. l_steps.get_size - 1 LOOP
                    l_step := TREAT(l_steps.get(l_i) AS JSON_OBJECT_T);
                    l_pk   := l_step.get_string(''path_key'');
                    IF l_pk IS NOT NULL AND LENGTH(TRIM(l_pk)) > 0 THEN
                        l_path_count := l_path_count + 1;
                    END IF;
                END LOOP;
            END IF;
        END IF;
    END IF;

    UPDATE ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
    SET parse_status = ''parsed'',
        step_count   = l_step_count,
        path_count   = l_path_count,
        updated_at   = SYSTIMESTAMP
    WHERE id = :doc_id;

    COMMIT;
    :status := 200;
    HTP.p(''{"doc_id":'' || :doc_id
       || '',"status":"ok","step_count":'' || l_step_count
       || '',"path_count":'' || l_path_count || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'' );
END;');

