      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Persist summary JSON and update counters',
      p_source         => 
'
DECLARE
    v_json    JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_summary VARCHAR2(4000);
BEGIN
    BEGIN v_summary := SUBSTR(v_json.get_string(''run_summary''), 1, 4000); EXCEPTION WHEN OTHERS THEN NULL; END;
    IF v_summary IS NULL THEN
      BEGIN v_summary := SUBSTR(v_json.get_string(''summary''), 1, 4000); EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
    IF v_summary IS NULL THEN
      BEGIN v_summary := SUBSTR(v_json.get_string(''ai_narrative''), 1, 4000); EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
    UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS
    SET summary_json = :body,
        run_summary  = NVL(v_summary, run_summary),
        ai_narrative = NVL(v_summary, ai_narrative),
        pass_count   = NVL(v_json.get_number(''pass_count''), pass_count),
        fail_count   = NVL(v_json.get_number(''fail_count''), fail_count),
        heal_count   = NVL(v_json.get_number(''heal_count''), heal_count),
        status       = NVL(v_json.get_string(''status''), status),
        comple' || 'ted_at = SYSTIMESTAMP,
        updated_at   = SYSTIMESTAMP
    WHERE run_id = :run_id;
    COMMIT;
    :status := 200;
    HTP.p(''{"run_id":'' || :run_id || '',  "status":"ok"}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

