  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'catalog',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Bulk upsert page library entries from crawl (body_text + blob fallback)',
      p_source         => 
'
DECLARE
    l_body     CLOB;
    v_json     JSON_OBJECT_T;
    v_items    JSON_ARRAY_T;
    v_item     JSON_OBJECT_T;
    v_count    NUMBER := 0;
    -- JSON_OBJECT_T member calls are NOT allowed inside a SQL statement
    -- (ORA-00932 at compile -> raw 555). Extract every value into plain
    -- locals first, then MERGE with the locals only.
    l_tenant   NUMBER;
    l_path_key VARCHAR2(500);
    l_srctype  VARCHAR2(50);
    l_module   VARCHAR2(200);
    l_label    VARCHAR2(1000);
    l_workarea VARCHAR2(500);
    l_deep_url VARCHAR2(2000);
    l_methods  VARCHAR2(1000);
    l_menu     CLOB;
    l_tasks    CLOB;
    l_buttons  CLOB;
    l_tabs     CLOB;
    l_inputs   CLOB;
    l_uiact    CLOB;
    l_exp_kw   VARCHAR2(2000);
    l_heading  VARCHAR2(1000);
    l_signals  NUMBER;
    l_status   VARCHAR2(50);
    l_cx       VARCHAR2(100);
    l_itemcnt  NUMBER;
    l_capby    VARCHAR2(500);
BEGIN
    l_body := :body_text;
    IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
  ' || '      l_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
        :status := 400;
        HTP.p(''{"error":"empty body"}'');
        RETURN;
    END IF;
    v_json  := JSON_OBJECT_T.parse(l_body);
    v_items := v_json.get_array(''items'');
    IF v_items IS NULL OR v_items.get_size = 0 THEN
        :status := 400;
        HTP.p(''{"error":"items[] required"}'');
        RETURN;
    END IF;
    FOR i IN 0 .. v_items.get_size - 1 LOOP
        v_item := TREAT(v_items.get(i) AS JSON_OBJECT_T);
        l_tenant   := v_item.get_number(''tenant_id'');
        l_path_key := SUBSTR(v_item.get_string(''path_key''), 1, 500);
        l_srctype  := SUBSTR(NVL(v_item.get_string(''source_type''), ''PAGE''), 1, 50);
        l_module   := SUBSTR(v_item.get_string(''module''), 1, 200);
        l_label    := SUBSTR(v_item.get_string(''label''), 1, 1000);
        l_workarea := SUBSTR(v_item.get_string(''work_area''), 1, 500);
        l_deep_url := SUBSTR(v_i' || 'tem.get_string(''deep_url''), 1, 2000);
        l_methods  := SUBSTR(v_item.get_string(''methods''), 1, 1000);
        l_menu     := TO_CLOB(v_item.get_string(''menu_path_json''));
        l_tasks    := TO_CLOB(v_item.get_string(''tasks_json''));
        l_buttons  := TO_CLOB(v_item.get_string(''action_buttons_json''));
        l_tabs     := TO_CLOB(v_item.get_string(''tabs_json''));
        l_inputs   := TO_CLOB(v_item.get_string(''form_inputs_json''));
        l_uiact    := TO_CLOB(v_item.get_string(''ui_actions_json''));
        l_exp_kw   := SUBSTR(v_item.get_string(''expected_keywords''), 1, 2000);
        l_heading  := SUBSTR(v_item.get_string(''heading''), 1, 1000);
        l_signals  := v_item.get_number(''signals_found'');
        l_status   := SUBSTR(v_item.get_string(''status''), 1, 50);
        l_cx       := SUBSTR(v_item.get_string(''cx_context''), 1, 100);
        l_itemcnt  := v_item.get_number(''item_count'');
        l_capby    := SUBSTR(v_item.get_string(''captured_by''), 1, 500);

        MERGE I' || 'NTO ITERIA_AI.VALIDATE_PAGE_LIBRARY t
        USING (SELECT l_tenant   AS tenant_id,
                      l_path_key AS path_key,
                      l_srctype  AS source_type
        FROM DUAL) s
        ON (t.tenant_id = s.tenant_id AND t.path_key = s.path_key AND t.source_type = s.source_type)
        WHEN MATCHED THEN UPDATE SET
            t.module              = NVL(l_module, t.module),
            t.label               = NVL(l_label, t.label),
            t.work_area           = NVL(l_workarea, t.work_area),
            t.deep_url            = NVL(l_deep_url, t.deep_url),
            t.methods             = NVL(l_methods, t.methods),
            t.menu_path_json      = NVL(l_menu, t.menu_path_json),
            t.tasks_json          = NVL(l_tasks, t.tasks_json),
            t.action_buttons_json = NVL(l_buttons, t.action_buttons_json),
            t.tabs_json           = NVL(l_tabs, t.tabs_json),
            t.form_inputs_json    = NVL(l_inputs, t.form_inputs_json),
         ' || '   t.ui_actions_json     = NVL(l_uiact, t.ui_actions_json),
            t.expected_keywords   = NVL(l_exp_kw, t.expected_keywords),
            t.heading             = NVL(l_heading, t.heading),
            t.signals_found       = GREATEST(NVL(t.signals_found, 0), NVL(l_signals, 0)),
            t.status              = NVL(l_status, t.status),
            t.captured_by         = NVL(t.captured_by, '''') ||
                                    CASE WHEN l_capby IS NOT NULL
                                         THEN '';'' || l_capby ELSE '''' END,
            t.item_count          = NVL(l_itemcnt, t.item_count),
            t.last_verified       = SYSTIMESTAMP
        WHEN NOT MATCHED THEN INSERT
            (tenant_id, path_key, module, label, work_area, deep_url, methods,
             menu_path_json, tasks_json, action_buttons_json, tabs_json, form_inputs_json,
             ui_actions_json, expected_keywords, heading, signals_found, status,
             source_type, cx_context, item_count,' || ' captured_by, crawled_at, last_verified)
        VALUES (
            l_tenant,
            l_path_key,
            l_module,
            l_label,
            l_workarea,
            l_deep_url,
            l_methods,
            l_menu,
            l_tasks,
            l_buttons,
            l_tabs,
            l_inputs,
            l_uiact,
            l_exp_kw,
            l_heading,
            NVL(l_signals, 0),
            NVL(l_status, ''ok''),
            l_srctype,
            NVL(l_cx, ''admin''),
            NVL(l_itemcnt, 0),
            l_capby,
            SYSTIMESTAMP,
            SYSTIMESTAMP
        );
        v_count := v_count + 1;
    END LOOP;
    COMMIT;
    :status := 200;
    HTP.p(''{"upserted":'' || v_count || ''}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;');

