'DECLARE v_total NUMBER:=0; BEGIN SELECT (SELECT COUNT(*) FROM ITERIA_AI.VALIDATE_API_CATALOG WHERE is_active=''Y'') + (SELECT COUNT(*) FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY) INTO v_total FROM dual; APEX_JSON.initialize_output; APEX_JSON.open_object; APEX_JSON.write(''total'', v_total); APEX_JSON.open_array(''items''); FOR r IN (SELECT path_key, module, label, deep_url, methods, source_type, times_seen FROM (SELECT path_key, module, COALESCE(business_name, path_label, path_key) AS label, NULL AS deep_url, http_methods AS methods, ''REST'' AS source_type, times_seen FROM ITERIA_AI.VALIDATE_API_CATALOG WHERE is_active=''Y'' UNION ALL SELECT path_key, module, COALESCE(label, INITCAP(REGEXP_REPLACE(REGEXP_REPLACE(path_key, ''^itemNode_'', ''''), ''_'', '' ''))) AS label, deep_url, methods, COALESCE(source_type, ''PAGE'') AS source_type, item_count AS times_seen FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY) ORDER BY module, label) LOOP APEX_JSON.open_object; APEX_JSON.write(''path_key'', r.path_key); APEX_JSON.write(''modu' || 'le'', r.module); APEX_JSON.write(''label'', r.label); APEX_JSON.write(''deep_url'', r.deep_url); APEX_JSON.write(''methods'', r.methods); APEX_JSON.write(''source_type'', r.source_type); APEX_JSON.write(''times_seen'', r.times_seen); APEX_JSON.close_object; END LOOP; APEX_JSON.close_array; APEX_JSON.close_object; END;');

