'
DECLARE
    v_json   JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_run_id NUMBER        := v_json.get_number(''run_id'');
    v_items  JSON_ARRAY_T  := v_json.get_array(''items'');
    v_item   JSON_OBJECT_T;
    v_count  NUMBER := 0;
BEGIN
    FOR i IN 0 .. v_items.get_size - 1 LOOP
        v_item := TREAT(v_items.get(i) AS JSON_OBJECT_T);
        -- Verified columns; PATH_ID + CAPTURED_AT auto-populate via defaults.
        INSERT INTO ITERIA_AI.VALIDATE_CRAWL_PATHS
            (run_id, path_key, path_label, module, path_type)
        VALUES (
            v_run_id,
            v_item.get_string(''path_key''),
            v_item.get_string(''path_label''),
            v_item.get_string(''module''),
            v_item.get_string(''path_type'')
        );
        v_count := v_count + 1;
    END LOOP;
    COMMIT;
    :status := 200;
    HTP.p(''{"inserted":'' || v_count || ''}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

