      p_comments       => 'Insert per-run module summaries from crawl',
      p_source         => 
'
DECLARE
    v_json   JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_run_id NUMBER        := v_json.get_number(''run_id'');
    v_cred   VARCHAR2(100) := v_json.get_string(''credential_set'');
    v_by     VARCHAR2(200) := v_json.get_string(''crawled_by'');
    v_items  JSON_ARRAY_T  := v_json.get_array(''items'');
    v_item   JSON_OBJECT_T;
    v_count  NUMBER := 0;
BEGIN
    FOR i IN 0 .. v_items.get_size - 1 LOOP
        v_item := TREAT(v_items.get(i) AS JSON_OBJECT_T);
        -- Verified columns; MODULE_RUN_ID auto-populates via sequence default.
        -- NVL guards the NOT NULL columns (MODULE_NAME, STATUS, PATH_COUNT);
        -- RAW_PBM_JSON keeps the complete item so business_* enrichment is kept.
        INSERT INTO ITERIA_AI.VALIDATE_CRAWL_RUN_MODULES
            (run_id, module_name, module_label, status, path_count,
             version_used, error_message, duration_ms,
             credential_set, crawled_by, raw_pbm_json)
        VALUES (
            v_run_id,
           ' || ' NVL(v_item.get_string(''module_name''), ''unknown''),
            v_item.get_string(''module_label''),
            NVL(v_item.get_string(''status''), ''pending''),
            NVL(v_item.get_number(''path_count''), 0),
            v_item.get_string(''version_used''),
            v_item.get_string(''error_message''),
            v_item.get_number(''duration_ms''),
            v_cred,
            v_by,
            v_item.to_string()
        );
        v_count := v_count + 1;
    END LOOP;
    COMMIT;
    :status := 200;
    HTP.p(''{"inserted":'' || v_count || ''}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

