  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'healed-labels',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Record a successful healing pair',
      p_source         => 
'
DECLARE
    -- Two compile-killers fixed here: JSON_OBJECT_T method calls inside the
    -- USING subquery (ORA-00932), and RETURNING INTO on a MERGE (illegal).
    -- Values are extracted to plain locals first; the id is selected after.
    v_json     JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_id       NUMBER;
    l_tenant   NUMBER;
    l_original VARCHAR2(1000);
    l_healed   VARCHAR2(1000);
    l_run      NUMBER;
    l_score    NUMBER;
BEGIN
    l_tenant   := v_json.get_number(''tenant_id'');
    l_original := SUBSTR(v_json.get_string(''original''), 1, 1000);
    l_healed   := SUBSTR(v_json.get_string(''healed_to''), 1, 1000);
    l_run      := v_json.get_number(''run_id'');
    l_score    := v_json.get_number(''score'');

    MERGE INTO ITERIA_AI.VALIDATE_HEALED_LABELS t
    USING (SELECT l_tenant AS tenant_id, l_original AS original FROM DUAL) s
    ON (t.tenant_id = s.tenant_id AND t.original = s.original)
    WHEN MATCHED THEN UPDATE SET
        t.healed_to  = l_healed,
        ' || 't.run_id     = l_run,
        t.score      = l_score,
        t.use_count  = t.use_count + 1,
        t.last_used  = SYSTIMESTAMP,
        t.updated_at = SYSTIMESTAMP
    WHEN NOT MATCHED THEN INSERT
        (tenant_id, original, healed_to, run_id, score)
    VALUES (l_tenant, l_original, l_healed, l_run, l_score);

    BEGIN
        SELECT id INTO v_id
          FROM ITERIA_AI.VALIDATE_HEALED_LABELS
         WHERE tenant_id = l_tenant AND original = l_original
           AND ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_id := NULL;
    END;
    COMMIT;
    :status := 201;
    HTP.p(''{"id":'' || NVL(v_id,0) || '',  "status":"ok"}'' );
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

