  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'step-mappings',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'step-mappings POST — JSON_OBJECT_T, no APEX_JSON',
      p_source         => 
'DECLARE
    v_json   JSON_OBJECT_T;
    v_label  VARCHAR2(500);
    v_path   VARCHAR2(500);
    v_conf   NUMBER;
BEGIN
    v_json  := JSON_OBJECT_T.parse(:body_text);
    v_label := NVL(v_json.get_string(''step_hash''), v_json.get_string(''step_label''));
    v_path  := v_json.get_string(''path_key'');
    v_conf  := NVL(v_json.get_number(''confidence''), 0.85);

    IF v_label IS NULL OR v_path IS NULL THEN
        :status := 400;
        HTP.P(''{"err":"step_label/step_hash and path_key required"}'');
        RETURN;
    END IF;

    MERGE INTO ITERIA_AI.VALIDATE_STEP_MAPPINGS t
    USING (SELECT v_label AS lbl FROM DUAL) s
       ON (t.step_label = s.lbl AND t.tenant_id = 1)
    WHEN MATCHED THEN UPDATE SET
        path_key   = v_path,
        confidence = v_conf,
        use_count  = NVL(t.use_count, 0) + 1,
        updated_at = SYSTIMESTAMP
    WHEN NOT MATCHED THEN INSERT
        (tenant_id, step_label, path_key, confidence, use_count, created_at)
    VALUES
        (1, v_label, v_path, v_' || 'conf, 1, SYSTIMESTAMP);

    COMMIT;
    :status := 200;
    HTP.P(''{"ok":true}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.P(''{"err":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

