      p_source         => 
'
DECLARE
    -- v_body CLOB := :body assigned a BLOB bind to a CLOB in DECLARE — a
    -- compile error no exception handler can catch (raw 555 on every call).
    -- Read the body inside BEGIN via the proven text/blob fallback instead.
    v_body CLOB;
    v_json JSON_OBJECT_T;
    v_id   NUMBER;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    v_json := JSON_OBJECT_T.parse(v_body);
    INSERT INTO ITERIA_AI.VALIDATE_CX_WEBHOOK_TESTS (
        job_id, tenant_id, webhook_name, webhook_url, trigger_event,
        payload_hash, response_code, response_body, status, error_message)
    VALUES (
        v_json.get_number(''job_id''),   v_json.get_number(''tenant_id''),
        v_json.get_string(''webhook_name''), v_json.get_string(''webhook_url''),
        v_json.get_string(''trigger_event''), v_json.get_string(''payload_hash''),
        v_json.get_number(''response_code''), v_json.get_string' || '(''response_body''),
        v_json.get_string(''status''),   v_json.get_string(''error_message''))
    RETURNING id INTO v_id;
    COMMIT; :status := 201;
    HTP.p(''{"id":''||v_id||'',  "status":"created"}'' );
EXCEPTION WHEN OTHERS THEN ROLLBACK; :status:=500;
    HTP.p(''{"error":"''||SQLERRM||''"}'' );
END;');

