      p_source         => 
'DECLARE
    -- Parsing :body_text in DECLARE dies uncatchably (raw 555) whenever the
    -- client posts application/json (:body_text is NULL then). Body is now
    -- read and parsed inside BEGIN with the proven text/blob fallback.
    v_body CLOB;
    v_json JSON_OBJECT_T;
    v_key  VARCHAR2(100);
    v_user VARCHAR2(200);
    v_pwd  VARCHAR2(500);
    v_lbl  VARCHAR2(200);
    v_url  VARCHAR2(500);
    v_sort NUMBER;
    v_tid  NUMBER;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    v_json := JSON_OBJECT_T.parse(v_body);
    v_key  := v_json.get_string(''credential_set'');
    v_user := v_json.get_string(''oracle_username'');
    v_pwd  := v_json.get_string(''oracle_password'');
    v_lbl  := v_json.get_string(''display_label'');
    v_url  := v_json.get_string(''oracle_url'');
    v_sort := v_json.get_number(''sort_order'');
    v_tid  := NVL(v_json.get_number(''tenant_id''), 1);
 ' || '   MERGE INTO ITERIA_AI.VALIDATE_SCRIPT_RUN_CREDENTIALS t
    USING (SELECT v_key AS credential_set, v_tid AS tenant_id FROM DUAL) s
    ON (t.credential_set = s.credential_set AND t.tenant_id = s.tenant_id)
    WHEN MATCHED THEN UPDATE SET
        t.oracle_username = NVL(v_user, t.oracle_username),
        t.oracle_password = NVL(v_pwd, t.oracle_password),
        t.display_label   = NVL(v_lbl, t.display_label),
        t.oracle_url      = NVL(v_url, t.oracle_url),
        t.sort_order      = NVL(v_sort, t.sort_order),
        t.updated_at      = SYSTIMESTAMP
    WHEN NOT MATCHED THEN INSERT
        (tenant_id, credential_set, oracle_username, oracle_password,
         display_label, oracle_url, sort_order, is_active, created_at)
    VALUES
        (v_tid, v_key, v_user, v_pwd, NVL(v_lbl, v_key), v_url,
         NVL(v_sort, 1), ''Y'', SYSTIMESTAMP);

    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"credential_set":"'' || v_key || ''"}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    ' || ':status := 500;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

