      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'patches',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Register a patch release row',
      p_source         => 
'DECLARE
    -- Same fix as credentials: parse of :body_text in DECLARE is uncatchable
    -- (raw 555) for application/json posts. Read + parse inside BEGIN.
    v_body   CLOB;
    v_json   JSON_OBJECT_T;
    v_tid    NUMBER;
    v_code   VARCHAR2(200);
    v_name   VARCHAR2(500);
    v_ver    VARCHAR2(100);
    v_mod    VARCHAR2(200);
    v_date   DATE;
    v_id     NUMBER;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    v_json := JSON_OBJECT_T.parse(v_body);
    v_tid  := NVL(v_json.get_number(''tenant_id''), NVL(TO_NUMBER(:tenant_id DEFAULT NULL ON CONVERSION ERROR), 1));
    v_code := NVL(v_json.get_string(''patch_code''), v_json.get_string(''patch_name''));
    v_name := NVL(v_json.get_string(''name''), v_code);
    v_ver  := v_json.get_string(''version'');
    v_mod  := v_json.get_string(''module'');
    BEGIN
        v_date := TO_DATE(v_json.get_string(''release_date''), ''YYYY-MM' || '-DD'');
    EXCEPTION WHEN OTHERS THEN v_date := TRUNC(SYSDATE);
    END;

    INSERT INTO ITERIA_AI.VALIDATE_PATCH_RELEASES
        (tenant_id, patch_name, patch_version, release_date, status, notes)
    VALUES
        (v_tid, v_code, v_ver, v_date, ''planned'',
         TRIM(v_name || CASE WHEN v_mod IS NOT NULL THEN '' · module='' || v_mod ELSE '''' END))
    RETURNING id INTO v_id;

    COMMIT;
    :status := 201;
    HTP.p(''{"ok":true,"patch_id":'' || v_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'process-flows/:flow_id/steps',
      p_priority       => 0,
