  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'process-flows/:flow_id/steps',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_items_per_page => 500,
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'SELECT step_id, flow_id, step_num, label AS step_details, expected_result, navigation_text, narration, path_key, method, status_code, card_json, TO_CHAR(created_at, ''YYYY-MM-DD HH24:MI:SS'') AS created_at FROM ITERIA_AI.VALIDATE_PROCESS_FLOW_STEPS WHERE flow_id = :flow_id ORDER BY step_num');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'process-flows/:flow_id/steps',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'process-flows/:flow_id/steps',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
  v_body       CLOB;
  v_json       JSON_OBJECT_T;
  v_steps      JSON_ARRAY_T;
  v_step       JSON_OBJECT_T;
  v_inserted   PLS_INTEGER := 0;
  v_flow_id    NUMBER := TO_NUMBER(:flow_id);
  v_exists     NUMBER;
  v_tenant     NUMBER := 1;
  v_actor      VARCHAR2(200);
  v_label      VARCHAR2(500);
  v_card_clob  CLOB;
  v_card_el    JSON_ELEMENT_T;
BEGIN
  SELECT COUNT(*), NVL(MAX(tenant_id), 1) INTO v_exists, v_tenant
    FROM ITERIA_AI.VALIDATE_PROCESS_FLOWS WHERE flow_id = v_flow_id;
  IF v_exists = 0 THEN
    OWA_UTIL.STATUS_LINE(404, ''Not Found'', FALSE);
    HTP.P(''{"error":"flow_id not found"}'');
    RETURN;
  END IF;

  v_body := iteria_ai.blob_to_clob_utf8(:body);
  IF v_body IS NULL OR LENGTH(v_body) = 0 THEN
    OWA_UTIL.STATUS_LINE(400, ''Bad Request'', FALSE);
    HTP.P(''{"error":"empty body"}'');
    RETURN;
  END IF;

  v_json  := JSON_OBJECT_T.parse(v_body);
  v_steps := v_json.get_Array(''steps'');
  IF v_steps IS NULL THEN
    OWA_UTIL.STATUS_LINE(400, ''Bad Reques' || 't'', FALSE);
    HTP.P(''{"error":"steps array required"}'');
    RETURN;
  END IF;

  IF v_json.has(''tenant_id'') THEN
    v_tenant := NVL(v_json.get_Number(''tenant_id''), v_tenant);
  END IF;
  v_actor := SUBSTR(NVL(v_json.get_String(''edited_by''), ''dashboard''), 1, 200);

  DELETE FROM ITERIA_AI.VALIDATE_PROCESS_FLOW_STEPS WHERE flow_id = v_flow_id;

  FOR i IN 0 .. v_steps.get_Size - 1 LOOP
    v_step := TREAT(v_steps.get(i) AS JSON_OBJECT_T);
    v_label := SUBSTR(
      NVL(v_step.get_String(''step_label''),
          NVL(v_step.get_String(''label''),
              NVL(v_step.get_String(''step_details''), ''''))),
      1, 500);
    v_card_clob := NULL;
    IF v_step.has(''card_json'') THEN
      v_card_el := v_step.get(''card_json'');
      IF v_card_el.is_Object OR v_card_el.is_Array THEN
        v_card_clob := JSON_SERIALIZE(v_card_el RETURNING CLOB);
      ELSE
        v_card_clob := v_step.get_String(''card_json'');
      END IF;
    END IF;
    INSERT INTO ITERIA_AI.VALIDATE_PROCESS_FLOW_STEPS
' || '        (flow_id, step_num, label, path_key, navigation_text, expected_result,
         narration, method, status_code, card_json, ui_actions, created_at)
    VALUES
        (v_flow_id,
         NVL(v_step.get_Number(''step_num''), i + 1),
         v_label,
         SUBSTR(v_step.get_String(''path_key''), 1, 200),
         SUBSTR(NVL(v_step.get_String(''navigation_text''), ''''), 1, 4000),
         SUBSTR(NVL(v_step.get_String(''expected_result''), ''''), 1, 4000),
         SUBSTR(NVL(v_step.get_String(''narration''), ''''), 1, 4000),
         SUBSTR(NVL(v_step.get_String(''method''), ''GET''), 1, 20),
         v_step.get_Number(''status_code''),
         v_card_clob,
         CASE WHEN v_step.has(''ui_actions'')
              THEN v_step.get_Array(''ui_actions'').to_Clob()
              ELSE NULL
         END,
         SYSTIMESTAMP);
    v_inserted := v_inserted + 1;
  END LOOP;

  UPDATE ITERIA_AI.VALIDATE_PROCESS_FLOWS
     SET updated_at = SYSTIMESTAMP
   WHERE flow_id = v_flow_id;

  INSERT INTO ITERIA_AI.' || 'VALIDATE_PROCESS_FLOW_HISTORY
      (tenant_id, flow_id, event_type, summary, detail_json, actor, created_at)
  VALUES
      (v_tenant, v_flow_id, ''human_edit'',
       ''Human updated '' || v_inserted || '' step(s) in Process Flow Library'',
       v_body, v_actor, SYSTIMESTAMP);

  COMMIT;

  HTP.P(''{"ok":true,"flow_id":'' || v_flow_id || '',"steps_inserted":'' || v_inserted || ''}'');

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    OWA_UTIL.STATUS_LINE(500, ''Server Error'', FALSE);
    HTP.P(''{"error":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;
');

