  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'scripts',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_mimes_allowed  => NULL,
      p_comments       => 'List uploaded scripts',
      p_source         => 
'SELECT id,
        doc_name,
        doc_type,
        ROUND(file_size / 1024, 1) AS file_size_kb,
        NVL(parse_status, ''parse_pending'') AS parse_status,
        step_count,
        TO_CHAR(uploaded_at, ''YYYY-MM-DD'') AS uploaded_at
FROM   ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
WHERE  (:tenant_id IS NULL OR tenant_id = :tenant_id)
ORDER  BY uploaded_at DESC
FETCH FIRST 500 ROWS ONLY');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'scripts',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v_script_coverage/',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'Uploaded scripts with parse status, step counts, and catalog coverage');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v_script_coverage/',
      p_method         => 'GET',
      p_source_type    => 'json/collection',
      p_items_per_page => 500,
      p_mimes_allowed  => NULL,
      p_comments       => 'My Test Scripts table source',
      p_source         => 
'SELECT d.id AS doc_id,
        d.doc_name,
        d.doc_type,
        ROUND(NVL(d.file_size, 0) / 1024, 1) AS file_size_kb,
        NVL(d.step_count, 0) AS steps_extracted,
        CASE WHEN NVL(d.step_count, 0) > 0
             THEN ROUND(100 * NVL(d.path_count, 0) / d.step_count)
             ELSE NULL END AS match_pct,
        CASE
          WHEN NVL(d.parse_status, ''parse_pending'') IN (''parse_pending'', ''parsing'', ''pending'')
            THEN ''PENDING''
          WHEN NVL(d.step_count, 0) = 0 AND LOWER(NVL(d.parse_status, ''x'')) = ''failed''
            THEN ''RED''
          WHEN NVL(d.step_count, 0) = 0
            THEN ''PENDING''
          WHEN NVL(d.path_count, 0) >= d.step_count
            THEN ''GREEN''
          WHEN NVL(d.path_count, 0) * 2 >= d.step_count
            THEN ''YELLOW''
          ELSE ''RED''
        END AS coverage_grade,
        NVL(d.parse_status, ''parse_pending'') AS parse_status,
        pj.error_msg AS parse_error,
        lr.run_id AS matched_against,
        TO_CHAR' || '(d.uploaded_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS uploaded_at
   FROM ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS d
   LEFT JOIN (
        SELECT doc_id, error_msg,
               ROW_NUMBER() OVER (
                   PARTITION BY doc_id
                   ORDER BY CASE WHEN status = ''failed'' THEN 0 ELSE 1 END,
                            completed_at DESC NULLS LAST,
                            job_id DESC
               ) AS rn
          FROM ITERIA_AI.VALIDATE_JOBS
         WHERE job_type = ''parse_document''
   ) pj ON pj.doc_id = d.id AND pj.rn = 1
   LEFT JOIN (
        SELECT doc_id, run_id,
               ROW_NUMBER() OVER (
                   PARTITION BY doc_id
                   ORDER BY created_at DESC NULLS LAST, run_id DESC
               ) AS rn
          FROM ITERIA_AI.VALIDATE_SCRIPT_RUNS
         WHERE status IN (''complete'', ''failed'', ''running'', ''queued'')
   ) lr ON lr.doc_id = d.id AND lr.rn = 1
  WHERE d.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-' || 'Key") FROM dual)
    AND LOWER(NVL(d.parse_status, ''x'')) <> ''archived''
  ORDER BY d.uploaded_at DESC');

