       r.created_at,
       r.linked_flow_id,
       r.source_flow_name,
       r.run_type,
       r.pipeline_phase,
       r.triggered_by,
       r.ai_score,
       r.playwright_score,
       r.combined_score,
       SUBSTR(r.run_summary, 1, 4000) AS run_summary,
       SUBSTR(r.ai_narrative, 1, 4000) AS ai_narrative,
       NVL(r.has_html_report, 0) AS has_html_report,
       NVL(r.has_html_report, 0) AS html_report,
       COALESCE(s.step_count, r.step_count, r.total_steps, 0) AS step_count,
       COALESCE(s.pass_count, r.pass_count, 0) AS pass_count,
       COALESCE(s.fail_count, r.fail_count, 0) AS fail_count,
       COALESCE(s.ui_match_count, r.ui_match_count, 0) AS ui_match_count,
       COALESCE(s.ui_mismatch_count, r.ui_mismatch_count, 0) AS ui_mismatch_count,
       NVL(r.healed_count, NVL(r.heal_count, ' || '0)) AS healed_count,
       CASE
         WHEN COALESCE(s.pass_count, r.pass_count, 0) + COALESCE(s.fail_count, r.fail_count, 0) > 0
         THEN ROUND(
           100 * COALESCE(s.pass_count, r.pass_count, 0)
           / (COALESCE(s.pass_count, r.pass_count, 0) + COALESCE(s.fail_count, r.fail_count, 0))
         )
         ELSE NULL
       END AS pass_pct,
       CASE
         WHEN r.completed_at IS NOT NULL AND r.started_at IS NOT NULL
         THEN ROUND((CAST(r.completed_at AS DATE) - CAST(r.started_at AS DATE)) * 86400)
         ELSE NULL
       END AS duration_seconds,
       CASE
         WHEN r.completed_at IS NOT NULL AND r.started_at IS NOT NULL
         THEN ROUND((CAST(r.completed_at AS DATE) - CAST(r.started_at AS DATE)) * 1440, 1)
         ELSE NULL
       END AS duration_min
  FROM ITERIA_AI.VALIDATE_SCRIPT_RUNS r
  LEFT JOIN (
       SELECT run_id,
              COUNT(*) AS step_count,
              COUNT(CASE WHEN UPPER(pass_fail) IN (''PASS'',''GREEN'',''HEALED'') THEN 1 ' || 'END) AS pass_count,
              COUNT(CASE WHEN UPPER(pass_fail) IN (''FAIL'',''RED'',''BLOCKED'',''ERROR'') THEN 1 END) AS fail_count,
              COUNT(CASE
                      WHEN UPPER(ui_result) IN (''MATCH'',''HEALED'',''NEEDS_REVIEW'')
                        OR (UPPER(ui_result) = ''UI_ACTION'' AND ui_action_detail IS NOT NULL)
                        OR screenshot_url IS NOT NULL
                      THEN 1
                    END) AS ui_match_count,
              COUNT(CASE
                      WHEN UPPER(ui_result) IN (''MISMATCH'',''UNVERIFIED_PAGE'',''DUPLICATE_SCREENSHOT'',''NOT_FOUND'',''URL_UNKNOWN'',''FAIL'')
                      THEN 1
                    END) AS ui_mismatch_count
         FROM ITERIA_AI.VALIDATE_SCRIPT_STEP_RESULTS
        GROUP BY run_id
  ) s ON s.run_id = r.run_id
 WHERE r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
   AND LOWER(NVL(r.status, ''x'')) NOT IN (''dismissed'',''archived'',''hidden'')
 ORDER BY r.started_at DESC NULLS LA' || 'ST, r.created_at DESC NULLS LAST
');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'runs/',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'x_tenant_key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'HTTP header X-Tenant-Key mapped to x_tenant_key');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'feedback/discovered-binding',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'VU-isolation: discovered selector bindings');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'feedback/discovered-binding',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Record a discovered selector — writes ITERIA_AI.VALIDATE_DISCOVERED_BINDINGS',
      p_source         => 
'DECLARE
    l_body  CLOB := iteria_ai.blob_to_clob_utf8(:body);
    l_json  JSON_OBJECT_T;
    l_path  VARCHAR2(500);
    l_label VARCHAR2(500);
    l_sel   VARCHAR2(1000);
    l_src   VARCHAR2(50);
    l_run   NUMBER;
BEGIN
    l_json := JSON_OBJECT_T.parse(l_body);
    l_path  := SUBSTR(l_json.get_String(''path_key''),         1, 500);
    l_label := SUBSTR(l_json.get_String(''target_label''),     1, 500);
    l_sel   := SUBSTR(l_json.get_String(''working_selector''), 1, 1000);
    BEGIN l_src := SUBSTR(l_json.get_String(''source''), 1, 50); EXCEPTION WHEN OTHERS THEN l_src := ''discovered''; END;
    BEGIN l_run := l_json.get_Number(''run_id'');                EXCEPTION WHEN OTHERS THEN l_run := NULL; END;

    MERGE INTO ITERIA_AI.VALIDATE_DISCOVERED_BINDINGS t
    USING (SELECT 1 AS tenant_id, l_path AS path_key, l_label AS element_label FROM dual) s
    ON (t.tenant_id = s.tenant_id AND t.path_key = s.path_key AND t.element_label = s.element_label)
    WHEN MATCHED THEN UPDATE SET
        t.' || 'selector     = l_sel,
        t.binding_type = l_src,
        t.confidence   = NVL(t.confidence, 0) + 1,
        t.updated_at   = SYSTIMESTAMP
    WHEN NOT MATCHED THEN INSERT
        (tenant_id, path_key, element_label, selector, binding_type, confidence, run_id, created_at, updated_at)
    VALUES
        (1, l_path, l_label, l_sel, l_src, 1, l_run, SYSTIMESTAMP, SYSTIMESTAMP);
    COMMIT;
    :status := 200;
    HTP.P(''{"ok":true}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''`'') || ''"}'');
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'feedback/discovered-binding',
      p_method             => 'POST',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'feedback/discovered-binding',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => 'List learned bindings for hydration',
      p_source         => 
'BEGIN
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.open_array(''items'');
    FOR rec IN (
        SELECT path_key, element_label, selector, binding_type, confidence, updated_at
          FROM ITERIA_AI.VALIDATE_DISCOVERED_BINDINGS
         WHERE tenant_id = 1
         ORDER BY updated_at DESC
    ) LOOP
        APEX_JSON.open_object;
        APEX_JSON.write(''path_key'',         rec.path_key);
        APEX_JSON.write(''target_label'',     rec.element_label);
        APEX_JSON.write(''working_selector'', rec.selector);
        APEX_JSON.write(''source'',           rec.binding_type);
        APEX_JSON.write(''success_count'',    rec.confidence);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.close_array;
    APEX_JSON.close_object;
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'feedback/discovered-binding',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'feedback/discovered-binding',
      p_method         => 'DELETE',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => 'Delete one stale binding',
      p_source         => 
'DECLARE
  l_api_key  VARCHAR2(200);
  l_req_key  VARCHAR2(200) := :api_key;
  l_path_key VARCHAR2(500) := :path_key;
  l_label    VARCHAR2(500) := :target_label;
  l_rows     NUMBER := 0;
BEGIN
  BEGIN
    SELECT api_key INTO l_api_key
      FROM iteria_ai.api_configuration
     WHERE is_active = ''Y'' AND ROWNUM = 1;
  EXCEPTION WHEN NO_DATA_FOUND THEN l_api_key := NULL;
  END;
  IF l_api_key IS NOT NULL AND NVL(l_req_key, ''__none__'') != l_api_key THEN
    :status := 403;
    HTP.P(''{"ok":false,"error":"unauthorized"}'');
    RETURN;
  END IF;

  IF l_path_key IS NULL OR l_label IS NULL THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"path_key and target_label query params required"}'');
    RETURN;
  END IF;

  DELETE FROM ITERIA_AI.VALIDATE_DISCOVERED_BINDINGS
   WHERE tenant_id = 1
     AND path_key  = l_path_key
     AND LOWER(element_label) = LOWER(l_label);
  l_rows := SQL%ROWCOUNT;

  COMMIT;
  :status := 200;
  HTP.P(''{"ok":true,"deleted":'' || l_rows || ''}'');
EXCEPTION WHE' || 'N OTHERS THEN
  ROLLBACK;
  :status := 500;
  HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''`'') || ''"}'');
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'feedback/discovered-binding',
      p_method             => 'DELETE',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/observe',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'VU-isolation: observe a discovered UI element');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/observe',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Observe UI/REST — tenant_id from JSON (not hardcoded 1)',
      p_source         => 
'DECLARE
  l_body         CLOB;
  l_api_key      VARCHAR2(200);
  l_req_key      VARCHAR2(200) := :api_key;
  l_root         JSON_OBJECT_T;
  l_item         JSON_OBJECT_T;
  l_path_key     VARCHAR2(500);
  l_kind         VARCHAR2(40);
  l_tenant_id    NUMBER := 1;
  l_col          VARCHAR2(40);
  l_existing     CLOB;
  l_new_id       VARCHAR2(500);
  l_new_label    VARCHAR2(500);
  l_new_label_lc VARCHAR2(500);
  l_new_method   VARCHAR2(20);
  l_new_url      VARCHAR2(2000);
  l_arr          JSON_ARRAY_T;
  l_elem         JSON_OBJECT_T;
  l_found        BOOLEAN := FALSE;
  l_found_idx    NUMBER  := -1;
  l_cur_id       VARCHAR2(500);
  l_cur_lbl_lc   VARCHAR2(500);
  l_cur_method   VARCHAR2(20);
  l_cur_url      VARCHAR2(2000);
  l_action       VARCHAR2(40);
  l_rows         NUMBER;
  l_ua_jel       JSON_ELEMENT_T;
  l_ua_new_arr   JSON_ARRAY_T;
  l_ua_old_clob  CLOB;
  l_ua_old_arr   JSON_ARRAY_T;
  l_ua_old_n     PLS_INTEGER;
  l_ua_new_n     PLS_INTEGER;
  l_ua_new_clob  CLOB;
  l_ua_' || 'do_upd    BOOLEAN;
  l_ua_cmp       PLS_INTEGER;
BEGIN
  BEGIN
    SELECT api_key INTO l_api_key
    FROM iteria_ai.api_configuration
    WHERE is_active = ''Y'' AND ROWNUM = 1;
  EXCEPTION WHEN NO_DATA_FOUND THEN l_api_key := NULL;
  END;
  IF l_api_key IS NOT NULL AND NVL(l_req_key, ''__none__'') != l_api_key THEN
    :status := 403;
    HTP.P(''{"ok":false,"error":"unauthorized"}'');
    RETURN;
  END IF;

  l_body := :body_text;
  IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
    l_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"empty body"}'');
    RETURN;
  END IF;

  BEGIN
    l_root := JSON_OBJECT_T.parse(l_body);
  EXCEPTION WHEN OTHERS THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"invalid JSON"}'');
    RETURN;
  END;

  l_path_key  := l_root.get_string(''path_key'');
  l_kind      := LOWER(l_root.get_string(''kind''));
  l_tenant_id := NVL(l_root.get' || '_number(''tenant_id''), 1);

  IF l_kind = ''ui_actions'' THEN
    IF l_path_key IS NULL OR TRIM(l_path_key) IS NULL THEN
      :status := 400;
      HTP.P(''{"ok":false,"error":"path_key required"}'');
      RETURN;
    END IF;
    l_ua_jel := l_root.get(''chain'');
    IF l_ua_jel IS NULL THEN
      :status := 400;
      HTP.P(''{"ok":false,"error":"ui_actions requires chain JSON array"}'');
      RETURN;
    END IF;
    BEGIN
      l_ua_new_arr := TREAT(l_ua_jel AS JSON_ARRAY_T);
    EXCEPTION WHEN OTHERS THEN
      :status := 400;
      HTP.P(''{"ok":false,"error":"chain must be a JSON array"}'');
      RETURN;
    END;
    l_ua_new_n := l_ua_new_arr.get_size;
    IF l_ua_new_n IS NULL OR l_ua_new_n < 1 THEN
      :status := 400;
      HTP.P(''{"ok":false,"error":"chain must be non-empty"}'');
      RETURN;
    END IF;
    l_ua_new_clob := l_ua_new_arr.to_clob;
    l_ua_old_clob := NULL;
    l_ua_old_n := 0;
    BEGIN
      SELECT ui_actions_json INTO l_ua_old_clob
        FROM ITERIA_AI.VALIDAT' || 'E_PAGE_LIBRARY
       WHERE tenant_id = l_tenant_id AND path_key = l_path_key;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      l_ua_old_clob := NULL;
    END;
    IF l_ua_old_clob IS NOT NULL AND DBMS_LOB.getlength(l_ua_old_clob) > 0 THEN
      BEGIN
        l_ua_old_arr := JSON_ARRAY_T.parse(l_ua_old_clob);
        l_ua_old_n := l_ua_old_arr.get_size;
      EXCEPTION WHEN OTHERS THEN
        l_ua_old_n := 0;
      END;
    END IF;
    l_ua_do_upd := FALSE;
    IF l_ua_old_n = 0 THEN
      l_ua_do_upd := TRUE;
    ELSIF l_ua_new_n > l_ua_old_n THEN
      l_ua_do_upd := TRUE;
    ELSIF l_ua_new_n = l_ua_old_n THEN
      l_ua_cmp := DBMS_LOB.COMPARE(NVL(l_ua_old_clob, EMPTY_CLOB()), l_ua_new_clob);
      IF l_ua_cmp != 0 THEN
        l_ua_do_upd := TRUE;
      END IF;
    END IF;
    IF l_ua_do_upd THEN
      UPDATE ITERIA_AI.VALIDATE_PAGE_LIBRARY
         SET ui_actions_json = l_ua_new_clob,
             updated_at      = SYSTIMESTAMP
       WHERE tenant_id = l_tenant_id AND path_key = l_pa' || 'th_key;
      l_rows := SQL%ROWCOUNT;
      IF l_rows = 0 THEN
        l_action := ''row_missing'';
      ELSE
        l_action := ''updated'';
      END IF;
    ELSIF l_ua_new_n < l_ua_old_n THEN
      l_action := ''skipped_shorter'';
    ELSE
      l_action := ''skipped_identical'';
    END IF;
    COMMIT;
    :status := 200;
    HTP.P(''{"ok":true,"action":"'' || l_action ||
          ''","kind":"ui_actions","tenant_id":'' || l_tenant_id ||
          '',"old_len":'' || l_ua_old_n || '',"new_len":'' || l_ua_new_n || ''}'');
    RETURN;
  END IF;

  l_item := TREAT(l_root.get(''item'') AS JSON_OBJECT_T);

  IF l_path_key IS NULL OR l_kind IS NULL OR l_item IS NULL THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"path_key, kind, item required"}'');
    RETURN;
  END IF;

  l_col := CASE l_kind
    WHEN ''action_button'' THEN ''ACTION_BUTTONS_JSON''
    WHEN ''task''          THEN ''TASKS_JSON''
    WHEN ''tab''           THEN ''TABS_JSON''
    WHEN ''form_input''    THEN ''FORM_INPUTS_JSON''
    WHEN ''rest_path''  ' || '   THEN ''OBSERVED_REST_PATHS''
    ELSE NULL
  END;

  IF l_col IS NULL THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"kind must be one of action_button|task|tab|form_input|rest_path|ui_actions"}'');
    RETURN;
  END IF;

  IF l_item.get_string(''source'') IS NULL THEN
    l_item.put(''source'', ''runtime'');
  END IF;

  EXECUTE IMMEDIATE
    ''SELECT '' || l_col || '' FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY '' ||
    ''WHERE tenant_id = :tid AND path_key = :p''
    INTO l_existing
    USING l_tenant_id, l_path_key;

  IF l_existing IS NULL OR DBMS_LOB.getlength(l_existing) = 0 THEN
    l_arr := JSON_ARRAY_T();
  ELSE
    BEGIN
      l_arr := JSON_ARRAY_T.parse(l_existing);
    EXCEPTION WHEN OTHERS THEN
      l_arr := JSON_ARRAY_T();
    END;
  END IF;

  IF l_kind = ''rest_path'' THEN
    l_new_method := UPPER(NVL(l_item.get_string(''method''), ''''));
    l_new_url    := l_item.get_string(''url'');
    IF l_new_method IS NULL OR l_new_url IS NULL THEN
      :status := 400;
      HTP.P(''{"ok":fal' || 'se,"error":"rest_path requires item.method and item.url"}'');
      RETURN;
    END IF;
    FOR i IN 0 .. l_arr.get_size - 1 LOOP
      BEGIN
        l_elem       := TREAT(l_arr.get(i) AS JSON_OBJECT_T);
        l_cur_method := UPPER(NVL(l_elem.get_string(''method''), ''''));
        l_cur_url    := l_elem.get_string(''url'');
        IF l_cur_method = l_new_method AND l_cur_url = l_new_url THEN
          l_found     := TRUE;
          l_found_idx := i;
          EXIT;
        END IF;
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END LOOP;
    IF l_found THEN
      l_elem := TREAT(l_arr.get(l_found_idx) AS JSON_OBJECT_T);
      l_elem.put(''last_seen'', TO_CHAR(SYSTIMESTAMP, ''YYYY-MM-DD"T"HH24:MI:SS''));
      l_elem.put(''status'',    l_item.get_number(''status''));
      l_elem.put(''duration_ms'',  l_item.get_number(''duration_ms''));
      l_elem.put(''observation_count'',
        NVL(l_elem.get_number(''observation_count''), 1) + 1);
      l_action := ''updated'';
    ELSE
      l_item.put(''first' || '_seen'', TO_CHAR(SYSTIMESTAMP, ''YYYY-MM-DD"T"HH24:MI:SS''));
      l_item.put(''last_seen'',  TO_CHAR(SYSTIMESTAMP, ''YYYY-MM-DD"T"HH24:MI:SS''));
      l_item.put(''observation_count'', 1);
      l_arr.append(l_item);
      l_action := ''appended'';
    END IF;
  ELSE
    l_item.put(''discovered_at'', TO_CHAR(SYSTIMESTAMP, ''YYYY-MM-DD"T"HH24:MI:SS''));
    l_new_id       := l_item.get_string(''id'');
    l_new_label    := NVL(l_item.get_string(''label''), l_item.get_string(''text''));
    l_new_label_lc := LOWER(l_new_label);
    FOR i IN 0 .. l_arr.get_size - 1 LOOP
      BEGIN
        l_elem       := TREAT(l_arr.get(i) AS JSON_OBJECT_T);
        l_cur_id     := l_elem.get_string(''id'');
        l_cur_lbl_lc := LOWER(NVL(l_elem.get_string(''label''), l_elem.get_string(''text'')));
        IF (l_new_id IS NOT NULL AND l_cur_id = l_new_id)
        OR (l_new_label_lc IS NOT NULL AND l_cur_lbl_lc = l_new_label_lc)
        THEN
          l_found := TRUE;
          EXIT;
        END IF;
      EXCEPTION WHEN OTHER' || 'S THEN NULL;
      END;
    END LOOP;
    IF l_found THEN
      l_action := ''existing'';
    ELSE
      l_arr.append(l_item);
      l_action := ''appended'';
    END IF;
  END IF;

  IF l_action IN (''appended'', ''updated'') THEN
    EXECUTE IMMEDIATE
      ''UPDATE ITERIA_AI.VALIDATE_PAGE_LIBRARY '' ||
      ''SET '' || l_col || '' = :j, updated_at = SYSTIMESTAMP '' ||
      ''WHERE tenant_id = :tid AND path_key = :p''
      USING l_arr.to_clob(), l_tenant_id, l_path_key;
    l_rows := SQL%ROWCOUNT;
    IF l_rows = 0 THEN
      l_action := ''row_missing'';
    END IF;
  END IF;

  COMMIT;
  :status := 200;
  HTP.P(''{"ok":true,"action":"'' || l_action || ''","kind":"'' || l_kind ||
        ''","tenant_id":'' || l_tenant_id || ''}'');

EXCEPTION WHEN OTHERS THEN
  ROLLBACK;
  :status := 500;
  HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''`'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/url-observe',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'VU-isolation: learn a deep_url for a path_key');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/url-observe',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Persist recovered deep_url — writes ITERIA_AI.VALIDATE_PAGE_LIBRARY.deep_url',
      p_source         => 
'DECLARE
  l_body       CLOB := iteria_ai.blob_to_clob_utf8(:body);
  l_api_key    VARCHAR2(200);
  l_req_key    VARCHAR2(200) := :api_key;
  l_root       JSON_OBJECT_T;
  l_path_key      VARCHAR2(500);
  l_new_url       VARCHAR2(2000);
  l_new_url_lc    VARCHAR2(2000);
  l_existing      VARCHAR2(2000);
  l_existing_lc   VARCHAR2(2000);
  l_menu_json     VARCHAR2(4000);
  l_tenant_id     NUMBER := 1;
  l_action        VARCHAR2(40);
  l_should_update BOOLEAN := FALSE;
  l_rows          NUMBER;
  l_menu_rows     NUMBER := 0;

  FUNCTION is_home_url(p_url VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    IF p_url IS NULL THEN RETURN FALSE; END IF;
    RETURN
      INSTR(p_url, ''FuseWelcome'')         > 0 OR
      INSTR(p_url, ''fusewelcome'')         > 0 OR
      INSTR(p_url, ''AtkHomePageWelcome'')  > 0 OR
      INSTR(p_url, ''atkhomepagewelcome'')  > 0 OR
      INSTR(p_url, ''HomePageWelcome'')     > 0 OR
      INSTR(p_url, ''homepagewelcome'')     > 0 OR
      INSTR(p_url, ''/faces/Home'')         > 0 OR
    ' || '  INSTR(p_url, ''/faces/home'')         > 0;
  END;

  FUNCTION is_login_url(p_url VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    IF p_url IS NULL THEN RETURN FALSE; END IF;
    RETURN
      INSTR(p_url, ''/login'')         > 0 OR
      INSTR(p_url, ''/signin'')        > 0 OR
      INSTR(p_url, ''/sso'')           > 0 OR
      INSTR(p_url, ''/idcs'')          > 0 OR
      INSTR(p_url, ''/oam'')           > 0 OR
      INSTR(p_url, ''/authenticate'')  > 0 OR
      INSTR(p_url, ''fa_login'')       > 0;
  END;

BEGIN
  BEGIN
    SELECT api_key INTO l_api_key
      FROM iteria_ai.api_configuration
     WHERE is_active = ''Y'' AND ROWNUM = 1;
  EXCEPTION WHEN NO_DATA_FOUND THEN l_api_key := NULL;
  END;
  IF l_api_key IS NOT NULL AND NVL(l_req_key, ''__none__'') != l_api_key THEN
    :status := 403;
    HTP.P(''{"ok":false,"error":"unauthorized"}'');
    RETURN;
  END IF;

  IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"empty body"}'');
    RETURN;
  END IF;
' || '
  BEGIN
    l_root := JSON_OBJECT_T.parse(l_body);
  EXCEPTION WHEN OTHERS THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"invalid JSON"}'');
    RETURN;
  END;

  l_path_key  := l_root.get_string(''path_key'');
  l_new_url   := l_root.get_string(''deep_url'');
  BEGIN l_tenant_id := NVL(l_root.get_number(''tenant_id''), 1); EXCEPTION WHEN OTHERS THEN l_tenant_id := 1; END;
  BEGIN l_menu_json := l_root.get_string(''menu_path_json''); EXCEPTION WHEN OTHERS THEN l_menu_json := NULL; END;

  IF l_path_key IS NULL OR l_new_url IS NULL THEN
    :status := 400;
    HTP.P(''{"ok":false,"error":"path_key and deep_url required"}'');
    RETURN;
  END IF;

  l_new_url_lc := LOWER(l_new_url);

  IF is_login_url(l_new_url_lc) THEN
    :status := 200;
    HTP.P(''{"ok":true,"action":"rejected_login_url","path_key":"'' ||
          REPLACE(l_path_key,''"'',''`'') || ''"}'');
    RETURN;
  END IF;

  IF is_home_url(l_new_url_lc) THEN
    :status := 200;
    HTP.P(''{"ok":true,"action":"rejected_home_url","pat' || 'h_key":"'' ||
          REPLACE(l_path_key,''"'',''`'') || ''"}'');
    RETURN;
  END IF;

  BEGIN
    SELECT deep_url INTO l_existing
      FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY
     WHERE tenant_id = l_tenant_id AND path_key = l_path_key;
  EXCEPTION WHEN NO_DATA_FOUND THEN
    :status := 200;
    HTP.P(''{"ok":true,"action":"row_missing","path_key":"'' ||
          REPLACE(l_path_key,''"'',''`'') || ''"}'');
    RETURN;
  END;

  l_existing_lc := LOWER(l_existing);

  IF l_existing IS NULL OR LENGTH(l_existing) = 0 THEN
    l_should_update := TRUE;
    l_action := ''updated'';
  ELSIF l_existing = l_new_url THEN
    l_should_update := FALSE;
    l_action := ''unchanged'';
  ELSIF is_home_url(l_existing_lc) THEN
    l_should_update := TRUE;
    l_action := ''updated'';
  ELSE
    l_should_update := FALSE;
    l_action := ''kept'';
  END IF;

  IF l_should_update THEN
    UPDATE ITERIA_AI.VALIDATE_PAGE_LIBRARY
       SET deep_url   = l_new_url,
           updated_at = SYSTIMESTAMP
     WHERE tenant_id = l_te' || 'nant_id AND path_key = l_path_key;
    l_rows := SQL%ROWCOUNT;
    IF l_rows = 0 THEN
      l_action := ''row_missing'';
    END IF;
  END IF;

  IF l_menu_json IS NOT NULL AND LENGTH(TRIM(l_menu_json)) > 2 THEN
    UPDATE ITERIA_AI.VALIDATE_PAGE_LIBRARY
       SET menu_path_json = l_menu_json,
           updated_at     = SYSTIMESTAMP
     WHERE tenant_id = l_tenant_id
       AND path_key = l_path_key
       AND (menu_path_json IS NULL OR LENGTH(TRIM(menu_path_json)) < 3);
    l_menu_rows := SQL%ROWCOUNT;
  END IF;

  COMMIT;
  :status := 200;
  HTP.P(''{"ok":true,"action":"'' || l_action ||
        ''","menu_updated":'' || l_menu_rows ||
        ''","path_key":"'' || REPLACE(l_path_key,''"'',''`'') ||
        ''","deep_url":"'' || REPLACE(SUBSTR(l_new_url,1,500),''"'',''`'') || ''"}'');

EXCEPTION WHEN OTHERS THEN
  ROLLBACK;
  :status := 500;
  HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''`'') || ''"}'');
END;');

