'
DECLARE
  v_body       CLOB;
  v_json       JSON_OBJECT_T;
  v_flow_key   VARCHAR2(200);
  v_name       VARCHAR2(500);
  v_desc       CLOB;
  v_src_fmt    VARCHAR2(50);
  v_src_doc    NUMBER;
  v_tenant     NUMBER;
  v_module     VARCHAR2(50);
  v_flow_id    NUMBER;
  v_existing   NUMBER;
BEGIN
  v_body := iteria_ai.blob_to_clob_utf8(:body);
  IF v_body IS NULL OR LENGTH(v_body) = 0 THEN
    OWA_UTIL.STATUS_LINE(400, ''Bad Request'', FALSE);
    HTP.P(''{"error":"empty body"}'');
    RETURN;
  END IF;

  v_json     := JSON_OBJECT_T.parse(v_body);
  v_flow_key := v_json.get_String(''flow_key'');
  v_name     := SUBSTR(NVL(v_json.get_String(''name''), v_flow_key), 1, 500);
  v_desc     := v_json.get_Clob(''description'');
  v_src_fmt  := SUBSTR(NVL(v_json.get_String(''source_format''), ''recording''), 1, 50);
  IF v_json.has(''source_doc_id'') THEN
    v_src_doc := v_json.get_Number(''source_doc_id'');
  END IF;
  v_tenant   := NVL(v_json.get_Number(''tenant_id''), 1);
  IF v_json.has(''module'') THEN
    v_' || 'module := SUBSTR(LOWER(TRIM(v_json.get_String(''module''))), 1, 50);
  END IF;
  v_module   := NVL(NULLIF(v_module, ''''), ''fscm'');

  IF v_flow_key IS NULL THEN
    OWA_UTIL.STATUS_LINE(400, ''Bad Request'', FALSE);
    HTP.P(''{"error":"flow_key required"}'');
    RETURN;
  END IF;

  -- Upsert by flow_key
  SELECT COUNT(*) INTO v_existing
    FROM ITERIA_AI.VALIDATE_PROCESS_FLOWS
   WHERE flow_key = v_flow_key;

  IF v_existing > 0 THEN
    UPDATE ITERIA_AI.VALIDATE_PROCESS_FLOWS
       SET name          = v_name,
           description   = v_desc,
           source_format = v_src_fmt,
           source_doc_id = v_src_doc,
           tenant_id     = v_tenant,
           module        = v_module,
           updated_at    = SYSTIMESTAMP
     WHERE flow_key = v_flow_key
    RETURNING flow_id INTO v_flow_id;
  ELSE
    INSERT INTO ITERIA_AI.VALIDATE_PROCESS_FLOWS
        (flow_key, name, description, source_format, source_doc_id, tenant_id, module,
         created_at, updated_at)
    VALUES
  ' || '      (v_flow_key, v_name, v_desc, v_src_fmt, v_src_doc, v_tenant, v_module,
         SYSTIMESTAMP, SYSTIMESTAMP)
    RETURNING flow_id INTO v_flow_id;
  END IF;

  COMMIT;

  HTP.P(''{"flow_id":'' || v_flow_id
       || '',"flow_key":"'' || REPLACE(v_flow_key, ''"'', ''\"'') || ''"''
       || '',"module":"'' || REPLACE(v_module, ''"'', ''\"'') || ''"''
       || '',"upserted":'' || CASE WHEN v_existing > 0 THEN ''true'' ELSE ''false'' END
       || ''}'');

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    OWA_UTIL.STATUS_LINE(500, ''Server Error'', FALSE);
    HTP.P(''{"error":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;
');

