    FROM ITERIA_AI.VALIDATE_SCRIPT_FLOW_LINKS
   WHERE doc_id = v_doc_id AND flow_id = v_flow_id;

  IF v_exists = 0 THEN
    INSERT INTO ITE' || 'RIA_AI.VALIDATE_SCRIPT_FLOW_LINKS
        (doc_id, flow_id, tenant_id, created_at)
