  v_body CLOB; v_json JSON_OBJECT_T; v_assess CLOB; v_at TIMESTAMP; v_flow_id NUMBER := TO_NUMBER(:flow_id);
BEGIN
  v_body := iteria_ai.blob_to_clob_utf8(:body);
  IF v_body IS NULL OR LENGTH(v_body)=0 THEN
    OWA_UTIL.STATUS_LINE(400,''Bad Request'',FALSE);
    HTP.P(''{"error":"empty body"}''); RETURN;
  END IF;
  v_json := JSON_OBJECT_T.parse(v_body);
  IF v_json.has(''flow_assessment_json'') THEN v_assess := v_json.get_Clob(''flow_assessment_json''); END IF;
  IF v_json.has(''assessment_at'') THEN
    v_at := TO_TIMESTAMP_TZ(REPLACE(v_json.get_String(''assessment_at''),''Z'',''+00:00''),
                            ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM'');
  ELSE
    v_at := SYSTIMESTAMP;
  END IF;
  UPDATE ITERIA_AI.VALIDATE_PROCESS_FLOWS
     SET flow_assessment_json = NVL(v_assess, flow_assessment_json),
         assessment_at        = v_at,
         updated_at           = SYSTIMESTAMP
   WHERE flow_id = v_flow_id;
  IF SQL%ROWCOUNT = 0 THEN
    OWA_UTIL.STATUS_LINE(404,''Not Found'',FALSE);
' || '    HTP.P(''{"error":"flow_id not found"}''); RETURN;
  END IF;
  COMMIT;
  HTP.P(''{"flow_id":''||v_flow_id||'',"updated":true}'');
EXCEPTION WHEN OTHERS THEN
  ROLLBACK; OWA_UTIL.STATUS_LINE(500,''Server Error'',FALSE);
  HTP.P(''{"error":"''||REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'')||''"}'');
