    v_ords_base   VARCHAR2(4000);
    v_agent_base  VARCHAR2(4000);
    v_oracle_url  VARCHAR2(4000);
BEGIN
    v_tid := (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual);

    IF v_tid IS NULL THEN
        :status := 401;
        HTP.p(''{"error":"unauthorized"}'');
        RETURN;
    END IF;

    BEGIN
      ADMIN.VALIDATE_CTX_PKG.set_tenant(v_tid);
    EXCEPTION
      WHEN OTHERS THEN NULL;
    END;

    BEGIN
        SELECT c.api_key,
               NVL(c.ords_base_url, c.ords_url),
               c.api_base_url,
               c.oracle_url
          INTO v_api_key, v_ords_base, v_agent_base, v_oracle_url
          FROM iteria_ai.api_configuration c
         WHERE c.is_active = ''Y''
           AND ROWNUM = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        :status := 404;
        HTP.p(''{"error":"api_configuration not found"}'');
        RETURN;
    END;

    :status := 200;

    HTP.p(''{"i' || 'tems":[{"tenant_id":'' || v_tid
      || '',"DASHBOARD_TENANT_ID":'' || v_tid
      || '',"ORDS_API_KEY":"'' || REPLACE(REPLACE(NVL(v_api_key,''''), ''\'', ''\\''), ''"'', ''\"'')
      || ''","ORDS_BASE_URL":"'' || REPLACE(REPLACE(NVL(v_ords_base,''''), ''\'', ''\\''), ''"'', ''\"'')
      || ''","AGENT_BASE_URL":"'' || REPLACE(REPLACE(NVL(v_agent_base,''''), ''\'', ''\\''), ''"'', ''\"'')
      || ''","ORACLE_BASE_URL":"'' || REPLACE(REPLACE(NVL(v_oracle_url,''''), ''\'', ''\\''), ''"'', ''\"'')
      || ''","ORACLE_FUSION_URL":"'' || REPLACE(REPLACE(NVL(v_oracle_url,''''), ''\'', ''\\''), ''"'', ''\"'')
      || ''"}]}'');
END;
');

  ORDS.DEFINE_PARAMETER(
