'DECLARE
    v_vg_tenant_id NUMBER;
    v_json         JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_role         VARCHAR2(200) := v_json.get_string(''role_name'');
    v_user         VARCHAR2(200) := v_json.get_string(''username'');
    v_pwd          VARCHAR2(500) := v_json.get_string(''password'');
    v_modules      VARCHAR2(500) := v_json.get_string(''modules'');
    v_notes        VARCHAR2(2000):= v_json.get_string(''notes'');
    v_id           NUMBER;
BEGIN
    v_vg_tenant_id := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
    IF v_vg_tenant_id IS NULL THEN
        :status := 401; HTP.p(''{"error":"unauthorized"}''); RETURN;
    END IF;
    INSERT INTO iteria_ai.login_aliases
        (tenant_id, role_name, role_name_norm, username,
         password_plaintext, modules, notes, is_active, created_at)
    VALUES
        (v_vg_tenant_id, v_role, LOWER(v_role), v_user,
         v_pwd, v_modules, v_notes, ''Y'', SYSTIMESTAMP)
    RETURNING alias_id INTO v_id;
    COMMIT;
    :statu' || 's_code := 201;
    HTP.p(''{"alias_id":'' || v_id || '',  "ok":true}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''`'') || ''"}'' );
END;');

