  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v1/login-aliases/resolve',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'FIX 2026-05-25: collapsed broken inner DECLARE (was PLS-00103 at compile time)',
      p_source         => 
'DECLARE
    v_vg_tenant_id NUMBER;
    v_role         VARCHAR2(200) := :role_name;
    v_sql          CLOB;
BEGIN
    v_vg_tenant_id := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
    IF v_vg_tenant_id IS NULL THEN
        :status := 401;
        HTP.p(''{"error":"unauthorized"}'');
        RETURN;
    END IF;
    BEGIN ADMIN.VALIDATE_CTX_PKG.set_tenant(v_vg_tenant_id); EXCEPTION WHEN OTHERS THEN NULL; END;

    v_sql := q''[WITH candidates AS (
        SELECT a.alias_id, a.role_name, a.role_name_norm, a.username,
               a.password_plaintext, a.tenant_id, a.notes,
               CASE WHEN LOWER(a.role_name_norm) = LOWER(''#ROLE#'') THEN 0
                    WHEN INSTR(LOWER(a.role_name_norm), LOWER(''#ROLE#'')) > 0 THEN 1
                    WHEN INSTR(LOWER(''#ROLE#''), LOWER(a.role_name_norm)) > 0 THEN 2
                    ELSE 9 END AS match_rank,
               CASE WHEN a.tenant_id = ]'' || TO_CHAR(ADMIN.VALIDATE_CTX_PKG.get_tenant()) || q''[ THEN 0 ELSE 1 END AS tenan' || 't_rank
          FROM iteria_ai.login_aliases a
         WHERE a.is_active = ''Y''
           AND a.tenant_id IN (0, ]'' || TO_CHAR(ADMIN.VALIDATE_CTX_PKG.get_tenant()) || q''[))
        SELECT alias_id, role_name, role_name_norm, username, password_plaintext,
               tenant_id, notes
          FROM candidates WHERE match_rank < 9
         ORDER BY match_rank, tenant_rank, alias_id
         FETCH FIRST 5 ROWS ONLY]'';

    v_sql := REPLACE(v_sql, ''#ROLE#'', REPLACE(v_role, '''''''', ''''''''''''''''));
    VU_QUERY_PKG.run_as_json(v_sql, 0, 5);
EXCEPTION WHEN OTHERS THEN
    :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300), ''"'', ''\"'') || ''"}'');
END;');

