'DECLARE v_limit NUMBER:=NVL(TO_NUMBER(:limit DEFAULT NULL ON CONVERSION ERROR),50); v_tenant NUMBER:=NVL(TO_NUMBER(:tenant_id DEFAULT NULL ON CONVERSION ERROR),1); v_total NUMBER:=0; BEGIN APEX_JSON.initialize_output; APEX_JSON.open_object; APEX_JSON.open_array(''items''); FOR r IN (SELECT id, SUBSTR(original,1,2000) AS original, SUBSTR(healed_to,1,2000) AS healed_to, run_id, score, use_count, TO_CHAR(last_used,''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS last_used FROM ITERIA_AI.VALIDATE_HEALED_LABELS WHERE tenant_id=v_tenant AND ROWNUM<=v_limit ORDER BY use_count DESC) LOOP APEX_JSON.open_object; APEX_JSON.write(''id'',r.id); APEX_JSON.write(''original'',r.original); APEX_JSON.write(''healed_to'',r.healed_to); APEX_JSON.write(''run_id'',r.run_id); APEX_JSON.write(''score'',r.score); APEX_JSON.write(''use_count'',r.use_count); APEX_JSON.write(''last_used'',r.last_used); APEX_JSON.close_object; END LOOP; APEX_JSON.close_array; SELECT COUNT(*) INTO v_total FROM ITERIA_AI.VALIDATE_HEALED_LABELS WHERE tenant_id=v_te' || 'nant; APEX_JSON.write(''total'',v_total); APEX_JSON.close_object; EXCEPTION WHEN OTHERS THEN APEX_JSON.initialize_output; APEX_JSON.open_object; APEX_JSON.open_array(''items''); APEX_JSON.close_array; APEX_JSON.write(''total'',0); APEX_JSON.write(''error'',SQLERRM); APEX_JSON.close_object; END;');

