      p_mimes_allowed  => NULL,
      p_comments       => 'Alias of /step-mappings — returns items + total',
      p_source         => 
'DECLARE
    v_limit  NUMBER := NVL(:limit, 50);
    v_tenant NUMBER := NVL(:tenant_id, 1);
    v_total  NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_total FROM ITERIA_AI.VALIDATE_STEP_MAPPINGS WHERE tenant_id = v_tenant;
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.open_array(''items'');
    FOR r IN (
        SELECT id, step_label, path_key, confidence, use_count
          FROM ITERIA_AI.VALIDATE_STEP_MAPPINGS
         WHERE tenant_id = v_tenant
         ORDER BY use_count DESC, confidence DESC
         FETCH FIRST v_limit ROWS ONLY
    ) LOOP
        APEX_JSON.open_object;
        APEX_JSON.write(''id'',         r.id);
        APEX_JSON.write(''step_label'', r.step_label);
        APEX_JSON.write(''path_key'',   r.path_key);
        APEX_JSON.write(''confidence'', r.confidence);
        APEX_JSON.write(''use_count'',  r.use_count);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.close_array;
    APEX_JSON.write(''total'', v_total);
    APEX_JSON.close_object;
E' || 'XCEPTION WHEN OTHERS THEN
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.open_array(''items''); APEX_JSON.close_array;
    APEX_JSON.write(''total'', 0);
    APEX_JSON.close_object;
END;');

