      p_items_per_page => 1000,
      p_mimes_allowed  => NULL,
      p_comments       => 'Returns ITERIA_AI.VALIDATE_BAD_NODES with outcome=home_fallback so dashboard filter works',
      p_source         => 
'DECLARE
    v_limit  NUMBER := NVL(:limit, 500);
    v_tenant NUMBER := NVL(:tenant_id, 1);
BEGIN
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.open_array(''items'');
    FOR r IN (
        SELECT id, selector, path_key, fail_count,
               ''home_fallback'' AS outcome
          FROM ITERIA_AI.VALIDATE_BAD_NODES
         WHERE tenant_id = v_tenant
