        APEX_JSON.write(''seen_count'',   r.seen_count);
        APEX_JSON.write(''stat' || 'us'',       r.status);
        APEX_JSON.write(''last_seen_at'', r.last_seen_at);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.close_array;
    APEX_JSON.close_object;
EXCEPTION WHEN OTHERS THEN
