      p_source         => 
'DECLARE
    v_id     NUMBER := :id;
    v_status VARCHAR2(50) := ''crawled'';
    v_json   JSON_OBJECT_T;
BEGIN
    BEGIN
        v_json   := JSON_OBJECT_T.parse(:body);
        v_status := NVL(v_json.get_string(''status''), ''crawled'');
    EXCEPTION WHEN OTHERS THEN NULL; END;
    UPDATE ITERIA_AI.VALIDATE_PAGE_CANDIDATES
       SET status = v_status, updated_at = SYSTIMESTAMP
     WHERE id = v_id;
    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"id":'' || v_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    :status := 200; HTP.p(''{"ok":true}'');
END;');

