  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'flow-baselines',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'fix_flow_regression — create baseline session (COALESCE body)',
      p_source         => 
'DECLARE
    v_body       CLOB;
    v_json       JSON_OBJECT_T;
    v_patch_id   NUMBER;
    v_flow_id    NUMBER;
    v_tenant_id  NUMBER;
    v_created_by VARCHAR2(100);
    v_rel_code   VARCHAR2(100);
    v_flow_title VARCHAR2(500);
    v_session_id NUMBER;
    v_job_id     NUMBER;
BEGIN
    v_body := :body_text;
    v_json := JSON_OBJECT_T.parse(v_body);
    v_patch_id   := v_json.get_number(''patch_id'');
    v_flow_id    := v_json.get_number(''flow_id'');
    v_tenant_id  := NVL(v_json.get_number(''tenant_id''), 1);
    v_created_by := NVL(v_json.get_string(''created_by''), ''operator'');

    BEGIN
        SELECT patch_name INTO v_rel_code FROM ITERIA_AI.VALIDATE_PATCH_RELEASES WHERE id = v_patch_id;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_rel_code := TO_CHAR(v_patch_id); END;
    BEGIN
        SELECT NVL(name, flow_key) INTO v_flow_title
          FROM ITERIA_AI.VALIDATE_PROCESS_FLOWS WHERE flow_id = v_flow_id;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_flow_title := TO_CHAR(v_flow_id); END;
' || '
    INSERT INTO ITERIA_AI.VALIDATE_FLOW_BASELINES
        (tenant_id, patch_id, flow_id, release_code, flow_title, status, created_by)
    VALUES
        (v_tenant_id, v_patch_id, v_flow_id, v_rel_code, v_flow_title, ''pending'', v_created_by)
    RETURNING session_id INTO v_session_id;

    INSERT INTO ITERIA_AI.VALIDATE_JOBS (tenant_id, job_type, batch_id, payload_json)
    VALUES (v_tenant_id, ''flow_baseline'', ''baseline-'' || v_session_id, v_body)
    RETURNING job_id INTO v_job_id;

    UPDATE ITERIA_AI.VALIDATE_FLOW_BASELINES SET job_id = v_job_id WHERE session_id = v_session_id;
    COMMIT;
    :status := 201;
    HTP.p(''{"ok":true,"session_id":'' || v_session_id || '',"job_id":'' || v_job_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''`'') || ''"}'' );
END;');

