    SELECT COUNT(*) INTO v_count
      FROM ITERIA_AI.VALIDATE_FLOW_BASELINES
     WHERE flow_id = v_flow_id AND status = ''complete'';

    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''has_baseline'', v_count > 0);
    APEX_JSON.open_array(''snapshots'');
    FOR r IN (
        SELECT session_id,
               TO_CHAR(captured_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS captured_at,
               paths_captured, status
          FROM ITERIA_AI.VALIDATE_FLOW_BASELINES
         WHERE flow_id = v_flow_id
         ORDER BY captured_at DESC
         FETCH FIRST 20 ROWS ONLY
    ) LOOP
        APEX_JSON.open_object;
        APEX_JSON.write(''session_id'',     r.session_id);
        APEX_JSON.write(''captured_at'',    r.captured_at);
        APEX_JSON.write(''paths_captured'', r.paths_captured);
        APEX_JSON.write(''status'',         r.status);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.' || 'close_array;
    APEX_JSON.close_object;
EXCEPTION WHEN OTHERS THEN
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''has_baseline'', FALSE);
    APEX_JSON.open_array(''snapshots''); APEX_JSON.close_array;
    APEX_JSON.close_object;
END;');

