    IF v_check_id IS NOT NULL THEN
        FOR r IN (
            SELECT check_id, release_code, flow_title, overall_verdict,
                   readiness_score, status, ai_summary,
                   TO_CHAR(created_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS created_at
