            APEX_JSON.write(''readiness_score'',r.readiness_score);
            APEX_JSON.write(''status'',         r.status);
            APEX_JS' || 'ON.write(''ai_summary'',     r.ai_summary);
            APEX_JSON.write(''created_at'',     r.created_at);
        END LOOP;
    ELSE
        -- Full list for readiness table render
        APEX_JSON.open_array(''items'');
        FOR r IN (
            SELECT check_id, patch_id, flow_id, release_code, flow_title,
                   overall_verdict, readiness_score, status, ai_summary,
                   TO_CHAR(created_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS created_at
              FROM ITERIA_AI.VALIDATE_FLOW_READINESS
             WHERE tenant_id = v_tenant
             ORDER BY created_at DESC
             FETCH FIRST 50 ROWS ONLY
        ) LOOP
            APEX_JSON.open_object;
            APEX_JSON.write(''check_id'',        r.check_id);
            APEX_JSON.write(''patch_id'',        r.patch_id);
            APEX_JSON.write(''flow_id'',         r.flow_id);
            APEX_JSON.write(''release_code'',    r.release_code);
            APEX_JSON.write(''flow_title'',      r.flow_title);
          ' || '  APEX_JSON.write(''overall_verdict'', r.overall_verdict);
            APEX_JSON.write(''readiness_score'', r.readiness_score);
            APEX_JSON.write(''status'',          r.status);
            APEX_JSON.write(''ai_summary'',      r.ai_summary);
            APEX_JSON.write(''created_at'',      r.created_at);
            APEX_JSON.close_object;
        END LOOP;
        APEX_JSON.close_array;
    END IF;
    APEX_JSON.close_object;
EXCEPTION WHEN OTHERS THEN
