      p_source         => 
'DECLARE
   l_body   CLOB := :body_text;
   l_obj    JSON_OBJECT_T;
   l_rows   JSON_ARRAY_T;
   l_row    JSON_OBJECT_T;
   l_cid    NUMBER := TO_NUMBER(:check_id);
   l_n      PLS_INTEGER := 0;
BEGIN
   l_obj  := JSON_OBJECT_T.PARSE(l_body);
   l_rows := l_obj.get_array(''results'');
   IF l_rows IS NULL THEN
      :status := 200;
      HTP.P(''{"ok":true,"persisted":0}'');
      RETURN;
   END IF;
   DELETE FROM ITERIA_AI.VALIDATE_FLOW_READINESS_RESULTS WHERE check_id = l_cid;
   FOR i IN 0 .. l_rows.get_size - 1 LOOP
      l_row := TREAT(l_rows.get(i) AS JSON_OBJECT_T);
      INSERT INTO ITERIA_AI.VALIDATE_FLOW_READINESS_RESULTS (
         check_id, path_key, verdict, baseline_status, current_status,
         fields_added, fields_removed, field_match_score, plain_english, captured_at)
      VALUES (
         l_cid,
         SUBSTR(l_row.get_string(''path_key''), 1, 500),
         SUBSTR(l_row.get_string(''verdict''), 1, 50),
         l_row.get_number(''baseline_status''),
         l_row.get_nu' || 'mber(''current_status''),
         SUBSTR(l_row.get_string(''fields_added''), 1, 2000),
         SUBSTR(l_row.get_string(''fields_removed''), 1, 2000),
         l_row.get_number(''field_match_score''),
         SUBSTR(l_row.get_string(''plain_english''), 1, 3500),
         SYSTIMESTAMP);
      l_n := l_n + 1;
   END LOOP;
   COMMIT;
   :status := 200;
   HTP.P(''{"ok":true,"persisted":'' || l_n || '',"check_id":'' || l_cid || ''}'');
EXCEPTION WHEN OTHERS THEN
   ROLLBACK;
   :status := 500;
   HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

