  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'flow-regression/by-flow/:flow_id',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Return regression history and readiness score for a flow');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'flow-regression/by-flow/:flow_id',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_items_per_page => 50,
      p_mimes_allowed  => NULL,
      p_comments       => 'Dashboard reads: has_results, readiness_score, results[].captured_at',
      p_source         => 
'DECLARE
    v_flow_id NUMBER := :flow_id;
    v_count   NUMBER;
    v_score   NUMBER;
BEGIN
    SELECT COUNT(*), AVG(readiness_score)
      INTO v_count, v_score
      FROM ITERIA_AI.VALIDATE_FLOW_READINESS
     WHERE flow_id = v_flow_id AND status = ''complete'';

    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''has_results'',    v_count > 0);
    APEX_JSON.write(''readiness_score'',ROUND(NVL(v_score, 0)));
    APEX_JSON.open_array(''results'');
    FOR r IN (
        SELECT check_id, overall_verdict, readiness_score,
               TO_CHAR(created_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS captured_at
          FROM ITERIA_AI.VALIDATE_FLOW_READINESS
         WHERE flow_id = v_flow_id
         ORDER BY created_at DESC
         FETCH FIRST 20 ROWS ONLY
    ) LOOP
        APEX_JSON.open_object;
        APEX_JSON.write(''check_id'',       r.check_id);
        APEX_JSON.write(''overall_verdict'',r.overall_verdict);
        APEX_JSON.write(''readiness_score'',r.readiness_score' || ');
        APEX_JSON.write(''captured_at'',    r.captured_at);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.close_array;
    APEX_JSON.close_object;
EXCEPTION WHEN OTHERS THEN
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''has_results'', FALSE);
    APEX_JSON.write(''readiness_score'', 0);
    APEX_JSON.open_array(''results''); APEX_JSON.close_array;
    APEX_JSON.close_object;
END;');

