'DECLARE v_tenant NUMBER:=NVL(:tenant_id,1); v_limit NUMBER:=NVL(:limit,50); BEGIN APEX_JSON.initialize_output; APEX_JSON.open_object; APEX_JSON.open_array(''items''); FOR r IN (SELECT comp_id, baseline_run_id, current_run_id, paths_added, paths_removed, paths_unchanged, impact_summary, ai_analysis, status, TO_CHAR(created_at,''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS created_at FROM ITERIA_AI.VALIDATE_PATH_COMPARISONS WHERE tenant_id=v_tenant ORDER BY created_at DESC FETCH FIRST v_limit ROWS ONLY) LOOP APEX_JSON.open_object; APEX_JSON.write(''comp_id'',r.comp_id); APEX_JSON.write(''base_run_id'',r.baseline_run_id); APEX_JSON.write(''curr_run_id'',r.current_run_id); APEX_JSON.write(''added_count'',r.paths_added); APEX_JSON.write(''removed_count'',r.paths_removed); APEX_JSON.write(''paths_unchanged'',r.paths_unchanged); APEX_JSON.write(''impact_summary'',r.impact_summary); APEX_JSON.write(''ai_summary'',r.ai_analysis); APEX_JSON.write(''status'',r.status); APEX_JSON.write(''created_at'',r.created_at); APEX_JSON.close_o' || 'bject; END LOOP; APEX_JSON.close_array; APEX_JSON.close_object; EXCEPTION WHEN OTHERS THEN APEX_JSON.initialize_output; APEX_JSON.open_object; APEX_JSON.write(''error'',SQLERRM); APEX_JSON.close_object; END;');

