'SELECT comp_id,
        baseline_run_id  AS base_run_id,
        current_run_id   AS curr_run_id,
        paths_added      AS added_count,
        paths_removed    AS removed_count,
        paths_unchanged,
        impact_summary,
        ai_analysis      AS ai_summary,
        status,
