  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'path-comparisons/:id/ai-context',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Structured AI change context for a comparison');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'path-comparisons/:id/ai-context',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => 'fix_consistency — paths_added/paths_removed in fallback SELECT',
      p_source         => 
'DECLARE
    v_id   NUMBER := :id;
    v_ctx  CLOB;
BEGIN
    SELECT ai_context_json INTO v_ctx
      FROM ITERIA_AI.VALIDATE_PATH_COMPARISONS WHERE comp_id = v_id;

    IF v_ctx IS NOT NULL AND DBMS_LOB.getlength(v_ctx) > 2 THEN
        HTP.p(v_ctx);
    ELSE
        DECLARE
            v_added   NUMBER;
            v_removed NUMBER;
        BEGIN
            SELECT paths_added, paths_removed
              INTO v_added, v_removed
              FROM ITERIA_AI.VALIDATE_PATH_COMPARISONS WHERE comp_id = v_id;
            APEX_JSON.initialize_output;
            APEX_JSON.open_object;
            APEX_JSON.open_array(''changes'');
            IF v_added > 0 THEN
                APEX_JSON.open_object;
                APEX_JSON.write(''type'', ''ADDED'');
                APEX_JSON.write(''module'', ''general'');
                APEX_JSON.write(''label'', v_added || '' paths added'');
                APEX_JSON.close_object;
            END IF;
            IF v_removed > 0 THEN
                APEX_JSON.open' || '_object;
                APEX_JSON.write(''type'', ''REMOVED'');
                APEX_JSON.write(''module'', ''general'');
                APEX_JSON.write(''label'', v_removed || '' paths removed'');
                APEX_JSON.close_object;
            END IF;
            APEX_JSON.close_array;
            APEX_JSON.close_object;
        END;
    END IF;
    :status := 200;
EXCEPTION WHEN NO_DATA_FOUND THEN
    :status := 404;
    HTP.p(''{"error":"comparison not found"}'');
EXCEPTION WHEN OTHERS THEN
    :status := 200;
    HTP.p(''{"changes":[]}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v1/login-aliases/:id',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Update or remove a login alias by alias_id');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v1/login-aliases/:id',
      p_method         => 'PATCH',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Partial update — supports role_name, username, password, modules, notes, is_active',
      p_source         => 
'DECLARE
    -- v_json.has() returns a PL/SQL BOOLEAN, which is illegal inside a SQL
    -- statement — the whole handler failed to compile (raw 555). The
    -- has-checks are now evaluated in PL/SQL into 0/1 flags, preserving the
    -- partial-update semantics (absent key = keep existing value).
    v_vg_tenant_id NUMBER;
    v_json         JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_id           NUMBER        := TO_NUMBER(:id);
    l_has_role     NUMBER := 0;  l_role  VARCHAR2(500);
    l_has_user     NUMBER := 0;  l_user  VARCHAR2(500);
    l_has_pw       NUMBER := 0;  l_pw    VARCHAR2(500);
    l_has_mod      NUMBER := 0;  l_mod   VARCHAR2(2000);
    l_has_notes    NUMBER := 0;  l_notes VARCHAR2(2000);
    l_has_active   NUMBER := 0;  l_activ VARCHAR2(10);
BEGIN
    v_vg_tenant_id := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
    IF v_vg_tenant_id IS NULL THEN
        :status := 401; HTP.p(''{"error":"unauthorized"}''); RETURN;
    END IF;
    IF v_json.has(''rol' || 'e_name'') THEN l_has_role   := 1; l_role  := SUBSTR(v_json.get_string(''role_name''), 1, 500); END IF;
    IF v_json.has(''username'')  THEN l_has_user   := 1; l_user  := SUBSTR(v_json.get_string(''username''), 1, 500); END IF;
    IF v_json.has(''password'')  THEN l_has_pw     := 1; l_pw    := SUBSTR(v_json.get_string(''password''), 1, 500); END IF;
    IF v_json.has(''modules'')   THEN l_has_mod    := 1; l_mod   := SUBSTR(v_json.get_string(''modules''), 1, 2000); END IF;
    IF v_json.has(''notes'')     THEN l_has_notes  := 1; l_notes := SUBSTR(v_json.get_string(''notes''), 1, 2000); END IF;
    IF v_json.has(''is_active'') THEN l_has_active := 1; l_activ := SUBSTR(v_json.get_string(''is_active''), 1, 10); END IF;
    UPDATE iteria_ai.login_aliases
       SET role_name      = CASE WHEN l_has_role = 1   THEN l_role        ELSE role_name  END,
           role_name_norm = CASE WHEN l_has_role = 1   THEN LOWER(l_role) ELSE role_name_norm END,
           username       = CASE WHEN l_has_user = 1   THEN l_user  ' || '      ELSE username   END,
           password_plaintext = CASE WHEN l_has_pw = 1 THEN l_pw          ELSE password_plaintext END,
           modules        = CASE WHEN l_has_mod = 1    THEN l_mod         ELSE modules    END,
           notes          = CASE WHEN l_has_notes = 1  THEN l_notes       ELSE notes      END,
           is_active      = CASE WHEN l_has_active = 1 THEN l_activ       ELSE is_active  END,
           updated_at     = SYSTIMESTAMP
     WHERE alias_id = v_id AND tenant_id = v_vg_tenant_id;
    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"alias_id":'' || v_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''`'') || ''"}'' );
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'v1/login-aliases/:id',
      p_method             => 'PATCH',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
