      p_comments       => 'Hard delete a login alias by alias_id',
      p_source         => 
'DECLARE
    v_vg_tenant_id NUMBER;
    v_id           NUMBER := TO_NUMBER(:id);
BEGIN
    v_vg_tenant_id := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
    IF v_vg_tenant_id IS NULL THEN
        :status := 401; HTP.p(''{"error":"unauthorized"}''); RETURN;
    END IF;
    DELETE FROM iteria_ai.login_aliases
     WHERE alias_id = v_id AND tenant_id = v_vg_tenant_id;
