      p_source         => 
'DECLARE v_tenant NUMBER:=NVL(TO_NUMBER(:tenant_id DEFAULT NULL ON CONVERSION ERROR),1);
 BEGIN
   APEX_JSON.initialize_output;
   APEX_JSON.open_object;
   APEX_JSON.open_array(''items'');
   FOR r IN (
     SELECT alias_id, role_name, role_name_norm, username, tenant_id,
            is_active, notes, modules
       FROM iteria_ai.login_aliases
      WHERE is_active = ''Y''
        AND tenant_id IN (0, v_tenant)
      ORDER BY CASE WHEN tenant_id = v_tenant THEN 0 ELSE 1 END, role_name_norm
   ) LOOP
     APEX_JSON.open_object;
     APEX_JSON.write(''alias_id'', r.alias_id);
     APEX_JSON.write(''role_name'', r.role_name);
     APEX_JSON.write(''role_name_norm'', r.role_name_norm);
     APEX_JSON.write(''username'', r.username);
     APEX_JSON.write(''tenant_id'', r.tenant_id);
     APEX_JSON.write(''is_active'', r.is_active);
     APEX_JSON.write(''notes'', r.notes);
     APEX_JSON.write(''modules'', r.modules);
     APEX_JSON.close_object;
   END LOOP;
   APEX_JSON.close_array;
   APEX_JSON.close_objec' || 't;
 EXCEPTION WHEN OTHERS THEN
   APEX_JSON.initialize_output;
   APEX_JSON.open_object;
   APEX_JSON.open_array(''items'');
   APEX_JSON.close_array;
   APEX_JSON.write(''error'', SQLERRM);
   APEX_JSON.close_object;
 END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v_script_runs_summary',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Dashboard script runs summary no-slash - fixed X-Tenant-Key header bind');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v_script_runs_summary',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_items_per_page => 500,
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Dashboard script runs summary no-slash - tenant scoped',
      p_source         => 
'
SELECT r.run_id,
       r.doc_id,
       r.job_id,
       r.tenant_id,
       r.status,
       r.grade,
       r.oracle_version,
       r.started_at,
       r.completed_at,
       r.created_at,
       r.linked_flow_id,
       r.source_flow_name,
       r.run_type,
       r.pipeline_phase,
       r.triggered_by,
       r.ai_score,
       r.playwright_score,
       r.combined_score,
       SUBSTR(r.run_summary, 1, 4000) AS run_summary,
       SUBSTR(r.ai_narrative, 1, 4000) AS ai_narrative,
       NVL(r.has_html_report, 0) AS has_html_report,
       NVL(r.has_html_report, 0) AS html_report,
       COALESCE(s.step_count, r.step_count, r.total_steps, 0) AS step_count,
       COALESCE(s.pass_count, r.pass_count, 0) AS pass_count,
       COALESCE(s.fail_count, r.fail_count, 0) AS fail_count,
       COALESCE(s.ui_match_count, r.ui_match_count, 0) AS ui_match_count,
       COALESCE(s.ui_mismatch_count, r.ui_mismatch_count, 0) AS ui_mismatch_count,
       NVL(r.healed_count, NVL(r.heal_count, ' || '0)) AS healed_count,
       CASE
         WHEN COALESCE(s.pass_count, r.pass_count, 0) + COALESCE(s.fail_count, r.fail_count, 0) > 0
         THEN ROUND(
           100 * COALESCE(s.pass_count, r.pass_count, 0)
           / (COALESCE(s.pass_count, r.pass_count, 0) + COALESCE(s.fail_count, r.fail_count, 0))
         )
         ELSE NULL
       END AS pass_pct,
       CASE
         WHEN r.completed_at IS NOT NULL AND r.started_at IS NOT NULL
         THEN ROUND((CAST(r.completed_at AS DATE) - CAST(r.started_at AS DATE)) * 86400)
         ELSE NULL
       END AS duration_seconds,
       CASE
         WHEN r.completed_at IS NOT NULL AND r.started_at IS NOT NULL
         THEN ROUND((CAST(r.completed_at AS DATE) - CAST(r.started_at AS DATE)) * 1440, 1)
         ELSE NULL
       END AS duration_min
  FROM ITERIA_AI.VALIDATE_SCRIPT_RUNS r
  LEFT JOIN (
       SELECT run_id,
              COUNT(*) AS step_count,
              COUNT(CASE WHEN UPPER(pass_fail) IN (''PASS'',''GREEN'',''HEALED'') THEN 1 ' || 'END) AS pass_count,
              COUNT(CASE WHEN UPPER(pass_fail) IN (''FAIL'',''RED'',''BLOCKED'',''ERROR'') THEN 1 END) AS fail_count,
              COUNT(CASE
                      WHEN UPPER(ui_result) IN (''MATCH'',''HEALED'',''NEEDS_REVIEW'')
                        OR (UPPER(ui_result) = ''UI_ACTION'' AND ui_action_detail IS NOT NULL)
                        OR screenshot_url IS NOT NULL
                      THEN 1
                    END) AS ui_match_count,
              COUNT(CASE
                      WHEN UPPER(ui_result) IN (''MISMATCH'',''UNVERIFIED_PAGE'',''DUPLICATE_SCREENSHOT'',''NOT_FOUND'',''URL_UNKNOWN'',''FAIL'')
                      THEN 1
                    END) AS ui_mismatch_count
         FROM ITERIA_AI.VALIDATE_SCRIPT_STEP_RESULTS
        GROUP BY run_id
  ) s ON s.run_id = r.run_id
 WHERE r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
   AND LOWER(NVL(r.status, ''x'')) NOT IN (''dismissed'',''archived'',''hidden'')
 ORDER BY r.started_at DESC NULLS LA' || 'ST, r.created_at DESC NULLS LAST
');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'v_script_runs_summary',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'x_tenant_key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'HTTP header X-Tenant-Key mapped to x_tenant_key');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'flow-baselines/:session_id/snapshots',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'fix_flow_regression — agent baseline capture');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'flow-baselines/:session_id/snapshots',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'MERGE path snapshots for a baseline session',
      p_source         => 
'DECLARE
   l_body      CLOB;
   l_obj       JSON_OBJECT_T;
   l_snaps     JSON_ARRAY_T;
   l_snap      JSON_OBJECT_T;
   l_sid       NUMBER := TO_NUMBER(:session_id);
   l_n         PLS_INTEGER := 0;
   -- path_key is hoisted to a local: JSON_OBJECT_T method calls inside the
   -- USING subquery raise ORA-00932 at compile and kill the whole handler.
   l_pk        VARCHAR2(500);
BEGIN
   l_body := :body_text;
   IF l_body IS NULL THEN
      :status := 400;
      HTP.P(''{"ok":false,"error":"empty body"}'');
      RETURN;
   END IF;
   l_obj   := JSON_OBJECT_T.PARSE(l_body);
   l_snaps := l_obj.get_array(''snapshots'');
   IF l_snaps IS NULL THEN
      :status := 200;
      HTP.P(''{"ok":true,"persisted":0}'');
      RETURN;
   END IF;

   FOR i IN 0 .. l_snaps.get_size - 1 LOOP
      l_snap := TREAT(l_snaps.get(i) AS JSON_OBJECT_T);
      l_pk   := SUBSTR(l_snap.get_string(''path_key''), 1, 500);
      MERGE INTO ITERIA_AI.VALIDATE_FLOW_BASELINE_SNAPSHOTS s
      USING (
         SELECT l_sid ' || 'AS session_id,
                l_pk  AS path_key
           FROM DUAL
      ) src
      ON (s.session_id = src.session_id AND s.path_key = src.path_key)
      WHEN MATCHED THEN UPDATE SET
           s.http_method     = SUBSTR(l_snap.get_string(''http_method''), 1, 20),
           s.http_status     = l_snap.get_number(''http_status''),
           s.response_hash   = SUBSTR(l_snap.get_string(''response_hash''), 1, 64),
           s.response_json   = SUBSTR(l_snap.get_string(''response_json''), 1, 3500),
           s.field_keys_json = SUBSTR(l_snap.get_string(''field_keys_json''), 1, 2000),
           s.page_heading    = SUBSTR(l_snap.get_string(''page_heading''), 1, 500),
           s.captured_at     = SYSTIMESTAMP
      WHEN NOT MATCHED THEN INSERT (
           session_id, path_key, http_method, http_status,
           response_hash, response_json, field_keys_json, page_heading, captured_at)
      VALUES (
           l_sid,
           l_pk,
           SUBSTR(l_snap.get_string(''http_method''), 1, 20)' || ',
           l_snap.get_number(''http_status''),
           SUBSTR(l_snap.get_string(''response_hash''), 1, 64),
           SUBSTR(l_snap.get_string(''response_json''), 1, 3500),
           SUBSTR(l_snap.get_string(''field_keys_json''), 1, 2000),
           SUBSTR(l_snap.get_string(''page_heading''), 1, 500),
           SYSTIMESTAMP);
      l_n := l_n + 1;
   END LOOP;
   COMMIT;
   :status := 200;
   HTP.P(''{"ok":true,"persisted":'' || l_n || '',"session_id":'' || l_sid || ''}'');
EXCEPTION WHEN OTHERS THEN
   ROLLBACK;
   :status := 500;
   HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'flow-baselines/:session_id/snapshots',
      p_method             => 'POST',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
