  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'flow-baselines/:session_id/snapshots',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_items_per_page => 2000,
      p_mimes_allowed  => NULL,
      p_comments       => 'Load captured baseline paths for readiness job',
      p_source         => 
'DECLARE
   l_sid NUMBER := TO_NUMBER(:session_id);
BEGIN
   APEX_JSON.initialize_output;
   APEX_JSON.open_object;
   APEX_JSON.open_array(''items'');
   FOR r IN (
      SELECT path_key, http_method, http_status, response_hash,
             response_json, field_keys_json, page_heading
        FROM ITERIA_AI.VALIDATE_FLOW_BASELINE_SNAPSHOTS
       WHERE session_id = l_sid
       ORDER BY path_key
   ) LOOP
      APEX_JSON.open_object;
      APEX_JSON.write(''path_key'',         r.path_key);
      APEX_JSON.write(''http_method'',      r.http_method);
      APEX_JSON.write(''http_status'',      r.http_status);
      APEX_JSON.write(''response_hash'',    r.response_hash);
      APEX_JSON.write(''response_json'',    r.response_json);
      APEX_JSON.write(''field_keys_json'',  r.field_keys_json);
      APEX_JSON.write(''page_heading'',     r.page_heading);
      APEX_JSON.close_object;
   END LOOP;
   APEX_JSON.close_array;
   APEX_JSON.close_object;
END;');

