  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'documents',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Agent bulk upload — stores VALIDATE_UPLOADED_DOCUMENTS row',
      p_source         => 
'DECLARE
    v_body      CLOB := :body_text;
    v_json      JSON_OBJECT_T;
    v_doc_id    NUMBER;
    v_tenant_id NUMBER := 1;
    v_name      VARCHAR2(500);
    v_type      VARCHAR2(20);
    v_content   CLOB;
    v_b64       CLOB;
    v_batch_id  VARCHAR2(100);
BEGIN
    v_json      := JSON_OBJECT_T.parse(v_body);
    v_tenant_id := NVL(v_json.get_number(''tenant_id''), 1);
    v_name      := NVL(v_json.get_string(''filename''), v_json.get_string(''doc_name''));
    v_type      := NVL(v_json.get_string(''file_type''), NVL(v_json.get_string(''doc_type''), ''txt''));
    v_content   := v_json.get_string(''content'');
    v_batch_id  := v_json.get_string(''batch_id'');

    IF v_json.has(''content_b64'') THEN
        v_b64 := v_json.get_string(''content_b64'');
    ELSE
        v_b64 := UTL_RAW.CAST_TO_VARCHAR2(UTL_ENCODE.BASE64_ENCODE(UTL_RAW.CAST_TO_RAW(v_content)));
    END IF;

    INSERT INTO ITERIA_AI.VALIDATE_UPLOADED_DOCUMENTS
        (tenant_id, doc_name, doc_type, content_b64, file_size, triggere' || 'd_by)
    VALUES
        (v_tenant_id, v_name, v_type, v_b64, DBMS_LOB.GETLENGTH(v_b64),
         ''agent_bulk_upload'')
    RETURNING id INTO v_doc_id;

    COMMIT;
    :status := 201;
    HTP.p(''{"id":'' || v_doc_id || '',"document_id":'' || v_doc_id || '',"status":"created"}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

