  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'path-tests',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Persist path_test job results');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'path-tests',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Insert path test result (CX Commerce)',
      p_source         => 
'DECLARE
    -- Parsing :body_text in DECLARE dies uncatchably (raw 555) whenever the
    -- client posts application/json, because :body_text is NULL then. Read
    -- the body inside BEGIN with the proven text/blob fallback.
    v_body CLOB;
    v_json JSON_OBJECT_T;
    v_id   NUMBER;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    v_json := JSON_OBJECT_T.parse(v_body);
    INSERT INTO ITERIA_AI.VALIDATE_PATH_TEST_RESULTS (
        job_id, tenant_id, path_key, module, site_id,
        test_status, can_transact, duration_ms, error_message, result_json)
    VALUES (
        v_json.get_number(''job_id''),
        NVL(v_json.get_number(''tenant_id''), 1),
        v_json.get_string(''path_key''),
        v_json.get_string(''module''),
        v_json.get_string(''site_id''),
        v_json.get_string(''test_status''),
        v_json.get_string(''can_transact''),
        v_json.get_number(''d' || 'uration_ms''),
        SUBSTR(v_json.get_string(''error_message''), 1, 2000),
        v_body)
    RETURNING id INTO v_id;
    COMMIT;
    :status := 201;
    HTP.p(''{"id":'' || v_id || '',"status":"created"}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Audit row for library/catalog crawl runs');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Insert VALIDATE_PAGE_LIBRARY_RUNS — returns run_log_id',
      p_source         => 
'DECLARE
    v_body    CLOB;
    v_json    JSON_OBJECT_T;
    v_run_id  NUMBER;
    v_tid     NUMBER;
    v_started TIMESTAMP WITH TIME ZONE;
    v_ended   TIMESTAMP WITH TIME ZONE;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"empty body"}'');
        RETURN;
    END IF;
    v_json := JSON_OBJECT_T.parse(v_body);
    v_tid  := NVL(v_json.get_number(''tenant_id''), 1);
    BEGIN
        v_started := TO_TIMESTAMP_TZ(
            REPLACE(v_json.get_string(''started_at''), ''Z'', ''+00:00''),
            ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM'');
    EXCEPTION WHEN OTHERS THEN v_started := SYSTIMESTAMP; END;
    BEGIN
        v_ended := TO_TIMESTAMP_TZ(
            REPLACE(v_json.get_string(''ended_at''), ''Z'', ''+00:00''),
            ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM'');
    EXCEPTI' || 'ON WHEN OTHERS THEN v_ended := SYSTIMESTAMP; END;

    INSERT INTO ITERIA_AI.VALIDATE_PAGE_LIBRARY_RUNS (
        tenant_id, started_at, ended_at, completed_at, status,
        path_keys, entries_json, ok_count, partial_count, failed_count,
        error_msg, crawler_version, crawl_type, credential_set, crawled_by,
        created_at, updated_at)
    VALUES (
        v_tid,
        v_started,
        v_ended,
        v_ended,
        SUBSTR(NVL(v_json.get_string(''status''), ''ok''), 1, 30),
        v_json.get_clob(''path_keys''),
        v_json.get_clob(''entries''),
        NVL(v_json.get_number(''ok_count''), 0),
        NVL(v_json.get_number(''partial_count''), 0),
        NVL(v_json.get_number(''failed_count''), 0),
        SUBSTR(NVL(v_json.get_string(''error_msg''), ''''), 1, 2000),
        SUBSTR(NVL(v_json.get_string(''crawler_version''), ''''), 1, 100),
        SUBSTR(NVL(v_json.get_string(''crawl_type''), ''library_crawl''), 1, 50),
        SUBSTR(NVL(v_json.get_string(''credential_set''), ''''), 1, 100)' || ',
        SUBSTR(NVL(v_json.get_string(''crawled_by''), ''''), 1, 200),
        SYSTIMESTAMP,
        SYSTIMESTAMP)
    RETURNING run_id INTO v_run_id;

    COMMIT;
    :status := 201;
    HTP.p(''{"ok":true,"run_log_id":'' || v_run_id || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run-items',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Per-path library crawl forensic rows');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run-items',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Batch insert VALIDATE_PAGE_LIBRARY_RUN_ITEMS_V2',
      p_source         => 
'DECLARE
    v_body   CLOB;
    v_json   JSON_OBJECT_T;
    v_items  JSON_ARRAY_T;
    v_item   JSON_OBJECT_T;
    v_saved  NUMBER := 0;
    v_skip   NUMBER := 0;
    i        NUMBER;
    l_run    NUMBER;
    l_tid    NUMBER;
    l_pk     VARCHAR2(200);
    l_ev     CLOB;
BEGIN
    v_body := :body_text;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        v_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    IF v_body IS NULL OR DBMS_LOB.getlength(v_body) = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"empty body"}'');
        RETURN;
    END IF;
    v_json  := JSON_OBJECT_T.parse(v_body);
    v_items := v_json.get_array(''items'');
    IF v_items IS NULL OR v_items.get_size = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"items[] required"}'');
        RETURN;
    END IF;
    FOR i IN 0 .. v_items.get_size - 1 LOOP
        v_item := TREAT(v_items.get(i) AS JSON_OBJECT_T);
        l_run  := v_item.get_number(''run_log_id'');
   ' || '     l_tid  := NVL(v_item.get_number(''tenant_id''), 1);
        l_pk   := SUBSTR(NVL(v_item.get_string(''path_key''), ''''), 1, 200);
        IF l_run IS NULL OR l_pk IS NULL THEN
            v_skip := v_skip + 1;
            CONTINUE;
        END IF;
        BEGIN
            l_ev := v_item.get_clob(''evidence_json'');
        EXCEPTION WHEN OTHERS THEN
            l_ev := TO_CLOB(v_item.get_string(''evidence_json''));
        END;
        INSERT INTO ITERIA_AI.VALIDATE_PAGE_LIBRARY_RUN_ITEMS_V2 (
            run_log_id, tenant_id, path_key, status, nav_method_used,
            view_id_matched, ready_selector_hit, heading_matched, screenshot_zone_hit,
            signals_found, observed_view_ids, error_msg, evidence_json,
            screenshot_url, screenshot_element_url, credential_set, crawled_by,
            created_at)
        VALUES (
            l_run, l_tid, l_pk,
            SUBSTR(NVL(v_item.get_string(''status''), ''failed''), 1, 20),
            SUBSTR(NVL(v_item.get_string(''nav_method' || '_used''), ''failed''), 1, 20),
            SUBSTR(NVL(v_item.get_string(''view_id_matched''), ''N''), 1, 1),
            SUBSTR(NVL(v_item.get_string(''ready_selector_hit''), ''N''), 1, 1),
            SUBSTR(NVL(v_item.get_string(''heading_matched''), ''N''), 1, 1),
            SUBSTR(NVL(v_item.get_string(''screenshot_zone_hit''), ''N''), 1, 1),
            NVL(v_item.get_number(''signals_found''), 0),
            SUBSTR(NVL(v_item.get_string(''observed_view_ids''), ''''), 1, 2000),
            SUBSTR(NVL(v_item.get_string(''error_msg''), ''''), 1, 2000),
            l_ev,
            SUBSTR(NVL(v_item.get_string(''screenshot_url''), ''''), 1, 2000),
            SUBSTR(NVL(v_item.get_string(''screenshot_element_url''), ''''), 1, 2000),
            SUBSTR(NVL(v_item.get_string(''credential_set''), ''''), 1, 100),
            SUBSTR(NVL(v_item.get_string(''crawled_by''), ''''), 1, 200),
            SYSTIMESTAMP);
        v_saved := v_saved + 1;
    END LOOP;
    COMMIT;
    :status := 201;
    HTP.p(''{"ok":true,"saved":'' || v_sav' || 'ed || '',"skipped":'' || v_skip || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run/:run_id',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Catalog scan module breakdown JSON');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library/run/:run_id',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => 'Return {entries:[...]} from audit/module entries CLOB',
      p_source         => 
'DECLARE
    v_run_id NUMBER := TO_NUMBER(:run_id);
    v_clob   CLOB;
    v_arr    JSON_ARRAY_T;
BEGIN
    BEGIN
        SELECT COALESCE(entries_json, module_entries_json, audit_entries_json)
          INTO v_clob
          FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY_RUNS
         WHERE run_id = v_run_id;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        BEGIN
            SELECT COALESCE(entries_json, module_entries_json, audit_entries_json)
              INTO v_clob
              FROM ITERIA_AI.VALIDATE_CRAWL_RUNS
             WHERE run_id = v_run_id;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            :status := 404;
            HTP.p(''{"error":"run not found"}'');
            RETURN;
        END;
    END;

    IF v_clob IS NULL OR DBMS_LOB.getlength(v_clob) < 3 THEN
        :status := 200;
        HTP.p(''{"run_id":'' || v_run_id || '',"entries":[]}'');
        RETURN;
    END IF;

    v_arr := JSON_ARRAY_T.parse(v_clob);
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.w' || 'rite(''run_id'', v_run_id);
    APEX_JSON.write(''entries'', v_arr);
    APEX_JSON.close_object;
    :status := 200;
EXCEPTION WHEN OTHERS THEN
    :status := 200;
    HTP.p(''{"run_id":'' || v_run_id || '',"entries":[]}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/baseline',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Toggle is_baseline on crawl/script run');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/baseline',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Dashboard baseline workflow',
      p_source         => 
'DECLARE
    v_body CLOB := :body_text;
    v_flag VARCHAR2(1) := NVL(JSON_VALUE(v_body, ''$.is_baseline''), ''Y'');
    v_run  NUMBER := TO_NUMBER(:run_id);
    v_n    NUMBER := 0;
BEGIN
    UPDATE ITERIA_AI.VALIDATE_CRAWL_RUNS
       SET is_baseline = v_flag, updated_at = SYSTIMESTAMP
     WHERE run_id = v_run AND status = ''complete'';
    v_n := SQL%ROWCOUNT;

    IF v_n = 0 THEN
        UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS
           SET is_baseline = v_flag, updated_at = SYSTIMESTAMP
         WHERE run_id = v_run AND status IN (''complete'',''passed'',''failed'');
        v_n := SQL%ROWCOUNT;
    END IF;

    IF v_n = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"run not found or not complete"}'');
        RETURN;
    END IF;

    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"run_id":'' || v_run || '',"is_baseline":"'' || v_flag || ''"}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'',' || ' ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/:job_id/claim',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'fix_flow_run_visibility — claim + linked_flow_id');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'jobs/:job_id/claim',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'claim with linked_flow_id from payload_json',
      p_source         => 
'DECLARE
    v_agent_id   VARCHAR2(100) := NVL(JSON_VALUE(:body_text, ''$.agent_id''), ''unknown'');
    v_doc_id     NUMBER;
    v_tenant_id  NUMBER;
    v_job_type   VARCHAR2(100);
    v_payload    CLOB;
    v_inner      VARCHAR2(32767);
    v_flow_id    NUMBER;
    v_rows       NUMBER;
BEGIN
    UPDATE ITERIA_AI.VALIDATE_JOBS
       SET status=''claimed'', agent_id=v_agent_id, run_id=:job_id,
           claimed_at=SYSTIMESTAMP, updated_at=SYSTIMESTAMP
     WHERE job_id=:job_id AND status=''pending'';
    v_rows := SQL%ROWCOUNT;

    IF v_rows > 0 THEN
        BEGIN
            SELECT doc_id, NVL(tenant_id, 1), payload_json, job_type
              INTO v_doc_id, v_tenant_id, v_payload, v_job_type
              FROM ITERIA_AI.VALIDATE_JOBS
             WHERE job_id = :job_id;
        EXCEPTION WHEN OTHERS THEN
            v_doc_id := NULL; v_tenant_id := 1; v_payload := NULL; v_job_type := NULL;
        END;

        v_flow_id := NULL;
        IF v_payload IS NOT NULL THEN
          BEGIN
    ' || '        v_inner := JSON_VALUE(v_payload, ''$.payload_json'' RETURNING VARCHAR2(32767) NULL ON ERROR);
            IF v_inner IS NOT NULL AND LENGTH(TRIM(v_inner)) > 2 THEN
              v_flow_id := JSON_VALUE(v_inner, ''$.linked_flow_id'' RETURNING NUMBER NULL ON ERROR);
              IF v_flow_id IS NULL THEN
                v_flow_id := JSON_VALUE(v_inner, ''$.flow_id'' RETURNING NUMBER NULL ON ERROR);
              END IF;
            END IF;
            IF v_flow_id IS NULL THEN
              v_flow_id := JSON_VALUE(v_payload, ''$.linked_flow_id'' RETURNING NUMBER NULL ON ERROR);
            END IF;
          EXCEPTION WHEN OTHERS THEN v_flow_id := NULL;
          END;
        END IF;

        -- Parse-only jobs must not create phantom rows in Test Results.
        IF LOWER(NVL(v_job_type, ''x'')) IN (''validate_script'', ''process_flow_run'') THEN
        BEGIN
            MERGE INTO ITERIA_AI.VALIDATE_SCRIPT_RUNS s
            USING (SELECT TO_NUMBER(:job_id) AS run_id FROM DUAL) src
        ' || '    ON (s.run_id = src.run_id)
            WHEN MATCHED THEN UPDATE SET
                 s.status         = ''running'',
                 s.agent_id       = v_agent_id,
                 s.started_at     = COALESCE(s.started_at, SYSTIMESTAMP),
                 s.doc_id         = NVL(s.doc_id, v_doc_id),
                 s.tenant_id      = NVL(s.tenant_id, v_tenant_id),
                 s.linked_flow_id = NVL(v_flow_id, s.linked_flow_id)
            WHEN NOT MATCHED THEN INSERT (
                 run_id, doc_id, tenant_id, status, agent_id, started_at, linked_flow_id, created_at)
            VALUES (
                 TO_NUMBER(:job_id), v_doc_id, v_tenant_id, ''running'', v_agent_id,
                 SYSTIMESTAMP, v_flow_id, SYSTIMESTAMP);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        END IF;
    END IF;

    COMMIT;

    IF v_rows = 0 THEN
        :status := 409;
        HTP.p(''{"error":"already claimed or not pending"}'');
    ELSE
        :status := 200;
        HTP.p(''{"st' || 'atus":"claimed","job_id":'' || :job_id || '',"run_id":'' || :job_id || ''}'');
    END IF;
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/register',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Agent upsert in-flight script run (validate-hooks)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/register',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Agent upsert in-flight script run (validate-hooks)',
      p_source         => 
'DECLARE
   l_obj    JSON_OBJECT_T;
   l_run_id NUMBER := TO_NUMBER(:run_id);
   l_doc_id NUMBER;
   l_tid    NUMBER;
   l_agent  VARCHAR2(100);
   l_phase  VARCHAR2(50);
BEGIN
   l_obj    := JSON_OBJECT_T.parse(:body);
   l_doc_id := l_obj.get_number(''doc_id'');
   l_tid    := NVL(l_obj.get_number(''tenant_id''), 1);
   l_agent  := l_obj.get_string(''agent_id'');
   l_phase  := NVL(l_obj.get_string(''pipeline_phase''), ''queued'');

   MERGE INTO ITERIA_AI.VALIDATE_SCRIPT_RUNS s
   USING (SELECT l_run_id AS run_id FROM DUAL) src
   ON (s.run_id = src.run_id)
   WHEN MATCHED THEN UPDATE SET
        s.status         = NVL(s.status, ''running''),
        s.agent_id       = NVL(l_agent, s.agent_id),
        s.started_at     = COALESCE(s.started_at, SYSTIMESTAMP),
        s.doc_id         = NVL(s.doc_id, l_doc_id),
        s.tenant_id      = NVL(l_tid, s.tenant_id)
   WHEN NOT MATCHED THEN INSERT (
        run_id, doc_id, tenant_id, status, agent_id, started_at, created_at)
   VALUES (
        l_run_i' || 'd, l_doc_id, NVL(l_tid, 1), ''running'', l_agent,
        SYSTIMESTAMP, SYSTIMESTAMP);

   BEGIN
      EXECUTE IMMEDIATE
         ''UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS SET pipeline_phase = :1 WHERE run_id = :2''
         USING l_phase, l_run_id;
   EXCEPTION WHEN OTHERS THEN NULL;
   END;

   COMMIT;
   :status := 200;
   HTP.P(''{"ok":true,"run_id":'' || l_run_id || ''}'');
EXCEPTION WHEN OTHERS THEN
   ROLLBACK;
   :status := 500;
   HTP.P(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

