      p_source         => 
'BEGIN
  :status := 200;
  HTP.PRN(ITERIA_AI.VALIDATE_STORE_REPORT_JSON(TO_NUMBER(:run_id), :body_text));
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
