  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/report',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => 'GET stored HTML report for a run (fixes download 404)',
      p_source         => 
'DECLARE
  v_rep   CLOB;
  v_len   PLS_INTEGER;
  v_pos   PLS_INTEGER := 1;
  v_chunk PLS_INTEGER := 8000;
BEGIN
  BEGIN
    SELECT business_report INTO v_rep
      FROM ITERIA_AI.VALIDATE_SCRIPT_RUNS
     WHERE run_id = TO_NUMBER(:run_id);
  EXCEPTION WHEN NO_DATA_FOUND THEN v_rep := NULL;
  END;
  OWA_UTIL.mime_header(''text/html'', TRUE);
  IF v_rep IS NULL OR DBMS_LOB.GETLENGTH(v_rep) = 0 THEN
    HTP.PRN(''<html><body style="font-family:sans-serif;padding:24px">''
            || ''<h3>No report stored yet for run '' || :run_id || ''.</h3>''
            || ''</body></html>'');
  ELSE
    v_len := DBMS_LOB.GETLENGTH(v_rep);
    WHILE v_pos <= v_len LOOP
      HTP.PRN(DBMS_LOB.SUBSTR(v_rep, v_chunk, v_pos));
      v_pos := v_pos + v_chunk;
    END LOOP;
  END IF;
EXCEPTION WHEN OTHERS THEN
  HTP.PRN(''<pre>report error: ''
          || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''`'') || ''</pre>'');
END;');

