      p_comments       => NULL,
      p_source         => 
'DECLARE
  l_run_id   NUMBER := TO_NUMBER(:run_id);
  l_run_rows NUMBER := 0;
  l_job_rows NUMBER := 0;
BEGIN
  UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS
     SET status       = ''dismissed'',
         completed_at = NVL(completed_at, SYSTIMESTAMP)
   WHERE run_id = l_run_id
     AND NVL(status, ''x'') <> ''dismissed'';
  l_run_rows := SQL%ROWCOUNT;

  UPDATE ITERIA_AI.VALIDATE_JOBS
     SET status    = ''failed'',
         error_msg = NVL(error_msg, ''Dismissed from dashboard''),
         updated_at = SYSTIMESTAMP
   WHERE (run_id = l_run_id OR job_id = l_run_id)
     AND LOWER(NVL(status, ''x'')) IN (
           ''pending'', ''claimed'', ''running'', ''queued'', ''analyzing''
         );
  l_job_rows := SQL%ROWCOUNT;

  COMMIT;
  :status := 200;
  HTP.p(''{"ok":true,"run_id":'' || l_run_id ||
        '',"updated":'' || l_run_rows ||
        '',"jobs_updated":'' || l_job_rows || ''}'');
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    :status := 500;
    HTP.p(''{"ok":false,"error":"'' ||
          REPLACE(SUBSTR(SQLERRM, ' || '1, 400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
