  UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS
     SET status = ''complete''
   WHERE run_id = l_run_id
     AND LOWER(NVL(status, ''x'')) IN (''dismissed'', ''archived'', ''hidden'');
  l_rows := SQL%ROWCOUNT;
  IF l_rows = 0 THEN
    UPDATE ITERIA_AI.VALIDATE_SCRIPT_RUNS
       SET status = NVL(NULLIF(status, ''dismissed''), ''complete'')
     WHERE run_id = l_run_id;
    l_rows := SQL%ROWCOUNT;
  END IF;
  COMMIT;
  :status := 200;
  HTP.p(''{"ok":true,"run_id":'' || l_run_id || '',"updated":'' || l_rows || ''}'');
EXCEPTION
  WHEN OTHERS THEN
