  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v1/auth-state/events',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => '555 fix auth telemetry');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v1/auth-state/events',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => NULL,
      p_source         => 
'DECLARE
  l_body CLOB := :body_text;
  l_tid  NUMBER := 21;
  l_run  NUMBER;
  l_evt  VARCHAR2(64);
  l_prof VARCHAR2(100);
  l_user VARCHAR2(200);
  l_role VARCHAR2(200);
  l_url  VARCHAR2(500);
  l_note VARCHAR2(1900);
BEGIN
  IF l_body IS NOT NULL AND DBMS_LOB.GETLENGTH(l_body) > 0 THEN
    BEGIN APEX_JSON.parse(l_body); EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN l_run  := APEX_JSON.get_number(p_path=>''run_id''); EXCEPTION WHEN OTHERS THEN l_run := NULL; END;
    BEGIN l_evt  := APEX_JSON.get_varchar2(p_path=>''event_type''); EXCEPTION WHEN OTHERS THEN l_evt := ''INFO''; END;
    BEGIN l_prof := APEX_JSON.get_varchar2(p_path=>''profile_name''); EXCEPTION WHEN OTHERS THEN l_prof := NULL; END;
    BEGIN l_user := APEX_JSON.get_varchar2(p_path=>''username''); EXCEPTION WHEN OTHERS THEN l_user := NULL; END;
    BEGIN l_role := APEX_JSON.get_varchar2(p_path=>''role_name''); EXCEPTION WHEN OTHERS THEN l_role := NULL; END;
    BEGIN l_url  := APEX_JSON.get_varchar2(p_path=>''base_url''); EXCEPTION' || ' WHEN OTHERS THEN l_url := NULL; END;
    BEGIN l_note := SUBSTR(APEX_JSON.get_varchar2(p_path=>''notes''), 1, 1900); EXCEPTION WHEN OTHERS THEN l_note := NULL; END;
    BEGIN l_tid  := APEX_JSON.get_number(p_path=>''tenant_id''); EXCEPTION WHEN OTHERS THEN l_tid := 21; END;
    BEGIN
      INSERT INTO ITERIA_AI.VALIDATE_AUTH_STATE_LOG
        (tenant_id, event_type, profile_name, username, role_name, base_url, run_id, notes)
      VALUES (NVL(l_tid, 21), l_evt, l_prof, l_user, l_role, l_url, l_run, l_note);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  :status := 201;
  HTP.p(''{"ok":true,"accepted":true}'');
EXCEPTION WHEN OTHERS THEN
  :status := 201;
  HTP.p(''{"ok":true,"accepted":true,"note":"telemetry skipped"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'page-library',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'page-library GET — no items_per_page');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'page-library GET — STRICT tenant isolation (tenant_id required)',
      p_source         => 
'DECLARE
  v_total   NUMBER := 0;
  v_limit   NUMBER := NVL(TO_NUMBER(:pl_limit  DEFAULT NULL ON CONVERSION ERROR), 500);
  v_offset  NUMBER := NVL(TO_NUMBER(:pl_offset DEFAULT NULL ON CONVERSION ERROR), 0);
  v_tid     NUMBER := TO_NUMBER(:tenant_id DEFAULT NULL ON CONVERSION ERROR);
  v_cnt     NUMBER := 0;
BEGIN
  -- STRICT tenant isolation. A request MUST identify its tenant via :tenant_id
  -- and ONLY that tenant rows are ever returned. The prior handler returned
  -- NULL-tenant rows, aliased legacy 0/1/2 onto tenant 21, and had a relaxed
  -- fallback that returned EVERY tenant rows when a tenant had none. That
  -- leaked FDLC (tenant 21) pages into other clients (e.g. Winzer/tenant 1).
  IF v_tid IS NULL THEN
    :status := 400;
    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''error'', ''tenant_id is required'');
    APEX_JSON.close_object;
  ELSE
    SELECT COUNT(*) INTO v_total
      FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY p
     WHERE p.tenant_id =' || ' v_tid;

    APEX_JSON.initialize_output;
    APEX_JSON.open_object;
    APEX_JSON.write(''total'', v_total);
    APEX_JSON.write(''offset'', v_offset);
    APEX_JSON.write(''limit'', v_limit);
    APEX_JSON.write(''tenant_id'', v_tid);
    APEX_JSON.open_array(''items'');

    FOR r IN (
      SELECT p.id, p.tenant_id, p.path_key, p.module, p.label, p.work_area, p.deep_url,
             p.methods, p.source_type, p.cx_context, p.item_count, p.status,
             p.signals_found, p.success_rate, p.ready_selector, p.screenshot_zone,
             p.expected_view_ids,
             CASE WHEN p.component_tags IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.component_tags, 2000, 1) END AS component_tags,
             SUBSTR(ri.screenshot_url, 1, 2000) AS baseline_screenshot_url,
             SUBSTR(ri.screenshot_element_url, 1, 2000) AS baseline_screenshot_element_url,
             TO_CHAR(p.crawled_at, ''YYYY-MM-DD"T"HH24:MI:SS'') AS crawled_at,
             CASE WHEN p.menu_path_json IS NUL' || 'L THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.menu_path_json, 2000, 1) END AS menu_path_json,
             CASE WHEN p.ui_actions_json IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.ui_actions_json, 3000, 1) END AS ui_actions_json,
             CASE WHEN p.observed_rest_paths IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.observed_rest_paths, 3000, 1) END AS observed_rest_paths,
             CASE WHEN p.observed_http_methods IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.observed_http_methods, 3000, 1) END AS observed_http_methods,
             CASE WHEN p.action_buttons_json IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.action_buttons_json, 3000, 1) END AS action_buttons_json,
             CASE WHEN p.tasks_json IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.tasks_json, 3000, 1) END AS tasks_json,
             CASE WHEN p.tabs_json IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.tabs_json, 3000, 1) END AS t' || 'abs_json,
             CASE WHEN p.form_inputs_json IS NULL THEN NULL
                  ELSE DBMS_LOB.SUBSTR(p.form_inputs_json, 3000, 1) END AS form_inputs_json,
             p.captured_by,
             TO_CHAR(p.last_verified, ''YYYY-MM-DD"T"HH24:MI:SS'') AS last_verified
        FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY p
        LEFT JOIN (
          SELECT path_key, tenant_id,
                 screenshot_url, screenshot_element_url,
                 ROW_NUMBER() OVER (PARTITION BY tenant_id, path_key ORDER BY item_id DESC) rn
            FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY_RUN_ITEMS_V2
        ) ri ON ri.tenant_id = p.tenant_id AND ri.path_key = p.path_key AND ri.rn = 1
       WHERE p.tenant_id = v_tid
       ORDER BY p.module, p.path_key
       OFFSET v_offset ROWS FETCH NEXT v_limit ROWS ONLY
    ) LOOP
      APEX_JSON.open_object;
      APEX_JSON.write(''id'', r.id);
      APEX_JSON.write(''tenant_id'', r.tenant_id);
      APEX_JSON.write(''path_key'', r.path_key);
      APEX_JSON.write(''m' || 'odule'', r.module);
      APEX_JSON.write(''label'', r.label);
      APEX_JSON.write(''heading'', r.label);
      APEX_JSON.write(''work_area'', r.work_area);
      APEX_JSON.write(''deep_url'', r.deep_url);
      APEX_JSON.write(''methods'', r.methods);
      APEX_JSON.write(''source_type'', r.source_type);
      APEX_JSON.write(''cx_context'', r.cx_context);
      APEX_JSON.write(''item_count'', r.item_count);
      APEX_JSON.write(''status'', r.status);
      APEX_JSON.write(''signals_found'', r.signals_found);
      APEX_JSON.write(''success_rate'', r.success_rate);
      APEX_JSON.write(''crawled_at'', r.crawled_at);
      APEX_JSON.write(''ready_selector'', r.ready_selector);
      APEX_JSON.write(''screenshot_zone'', r.screenshot_zone);
      APEX_JSON.write(''expected_view_ids'', r.expected_view_ids);
      APEX_JSON.write(''component_tags'', r.component_tags);
      APEX_JSON.write(''baseline_screenshot_url'', r.baseline_screenshot_url);
      APEX_JSON.write(''baseline_screenshot_element_url'', r.baseline_screen' || 'shot_element_url);
      APEX_JSON.write(''menu_path_json'', r.menu_path_json);
      APEX_JSON.write(''ui_actions_json'', r.ui_actions_json);
      APEX_JSON.write(''observed_rest_paths'', r.observed_rest_paths);
      APEX_JSON.write(''observed_http_methods'', r.observed_http_methods);
      APEX_JSON.write(''action_buttons_json'', r.action_buttons_json);
      APEX_JSON.write(''tasks_json'', r.tasks_json);
      APEX_JSON.write(''tabs_json'', r.tabs_json);
      APEX_JSON.write(''form_inputs_json'', r.form_inputs_json);
      APEX_JSON.write(''captured_by'', r.captured_by);
      APEX_JSON.write(''last_verified'', r.last_verified);
      APEX_JSON.close_object;
      v_cnt := v_cnt + 1;
    END LOOP;

    APEX_JSON.close_array;
    APEX_JSON.write(''returned'', v_cnt);
    APEX_JSON.write(''hasMore'', CASE WHEN (v_offset + v_cnt) < v_total THEN ''true'' ELSE ''false'' END);
    APEX_JSON.close_object;
    :status := 200;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    :status := 500;
    APEX_JSON.initialize_output' || ';
    APEX_JSON.open_object;
    APEX_JSON.write(''error'', SUBSTR(SQLERRM, 1, 400));
    APEX_JSON.close_object;
END;');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'page-library',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Upsert page library entries from library crawl (entries[])',
      p_source         => 
'DECLARE
    l_body     CLOB;
    v_json     JSON_OBJECT_T;
    v_items    JSON_ARRAY_T;
    v_item     JSON_OBJECT_T;
    v_count    NUMBER := 0;
    l_tenant   NUMBER;
    l_path_key VARCHAR2(500);
    l_module   VARCHAR2(200);
    l_label    VARCHAR2(1000);
    l_workarea VARCHAR2(500);
    l_deep_url VARCHAR2(2000);
    l_methods  VARCHAR2(1000);
    l_menu     CLOB;
    l_uiact    CLOB;
    l_tags     CLOB;
    l_views    VARCHAR2(2000);
    l_heading  VARCHAR2(1000);
    l_ready    VARCHAR2(500);
    l_zone     VARCHAR2(500);
    l_signals  NUMBER;
    l_status   VARCHAR2(50);
    l_rate     NUMBER;
    l_err      VARCHAR2(2000);
BEGIN
    l_body := :body_text;
    IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
        l_body := iteria_ai.blob_to_clob_utf8(:body);
    END IF;
    IF l_body IS NULL OR DBMS_LOB.getlength(l_body) = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"empty body"}'');
        RETURN;
    END IF;
    v_json  := JSON_OBJECT_T.pars' || 'e(l_body);
    v_items := v_json.get_array(''entries'');
    IF v_items IS NULL THEN v_items := v_json.get_array(''items''); END IF;
    IF v_items IS NULL OR v_items.get_size = 0 THEN
        :status := 400;
        HTP.p(''{"ok":false,"error":"entries[] required"}'');
        RETURN;
    END IF;
    FOR i IN 0 .. v_items.get_size - 1 LOOP
        v_item     := TREAT(v_items.get(i) AS JSON_OBJECT_T);
        l_tenant   := NVL(v_item.get_number(''tenant_id''), 1);
        l_path_key := SUBSTR(v_item.get_string(''path_key''), 1, 500);
        IF l_path_key IS NULL THEN CONTINUE; END IF;
        l_module   := SUBSTR(v_item.get_string(''module''), 1, 200);
        l_label    := SUBSTR(NVL(v_item.get_string(''label''), v_item.get_string(''heading'')), 1, 1000);
        l_workarea := SUBSTR(v_item.get_string(''work_area''), 1, 500);
        l_deep_url := SUBSTR(v_item.get_string(''deep_url''), 1, 2000);
        l_methods  := SUBSTR(v_item.get_string(''methods''), 1, 1000);
        l_menu     := TO_CLOB(v_item.ge' || 't_string(''menu_path_json''));
        l_uiact    := TO_CLOB(v_item.get_string(''ui_actions_json''));
        l_tags     := TO_CLOB(v_item.get_string(''component_tags''));
        l_views    := SUBSTR(v_item.get_string(''expected_view_ids''), 1, 2000);
        l_heading  := SUBSTR(v_item.get_string(''heading''), 1, 1000);
        l_ready    := SUBSTR(v_item.get_string(''ready_selector''), 1, 500);
        l_zone     := SUBSTR(v_item.get_string(''screenshot_zone''), 1, 500);
        l_signals  := NVL(v_item.get_number(''signals_found''), 0);
        l_status   := SUBSTR(NVL(v_item.get_string(''status''), ''ok''), 1, 50);
        l_rate     := v_item.get_number(''success_rate'');
        l_err      := SUBSTR(NVL(v_item.get_string(''error''), v_item.get_string(''error_msg'')), 1, 2000);

        MERGE INTO ITERIA_AI.VALIDATE_PAGE_LIBRARY t
        USING (SELECT l_tenant AS tenant_id, l_path_key AS path_key, ''PAGE'' AS source_type FROM DUAL) s
        ON (t.tenant_id = s.tenant_id AND t.path_key = s.path_key AND t.s' || 'ource_type = s.source_type)
        WHEN MATCHED THEN UPDATE SET
            t.module            = NVL(l_module, t.module),
            t.label             = NVL(l_label, t.label),
            t.work_area         = NVL(l_workarea, t.work_area),
            t.deep_url          = NVL(l_deep_url, t.deep_url),
            t.methods           = NVL(l_methods, t.methods),
            t.menu_path_json    = NVL(l_menu, t.menu_path_json),
            t.ui_actions_json   = NVL(l_uiact, t.ui_actions_json),
            t.component_tags    = NVL(l_tags, t.component_tags),
            t.expected_view_ids = NVL(l_views, t.expected_view_ids),
            t.heading           = NVL(l_heading, t.heading),
            t.ready_selector    = NVL(l_ready, t.ready_selector),
            t.screenshot_zone   = NVL(l_zone, t.screenshot_zone),
            t.signals_found     = GREATEST(NVL(t.signals_found, 0), NVL(l_signals, 0)),
            t.status            = NVL(l_status, t.status),
            t.success_rat' || 'e      = NVL(l_rate, t.success_rate),
            t.error_msg         = NVL(l_err, t.error_msg),
            t.crawled_at        = SYSTIMESTAMP,
            t.last_verified     = SYSTIMESTAMP
        WHEN NOT MATCHED THEN INSERT
            (tenant_id, path_key, module, label, work_area, deep_url, methods,
             menu_path_json, ui_actions_json, component_tags, expected_view_ids,
             heading, ready_selector, screenshot_zone, signals_found, status,
             success_rate, error_msg, source_type, crawled_at, last_verified)
        VALUES (
            l_tenant, l_path_key, l_module, l_label, l_workarea, l_deep_url, l_methods,
            l_menu, l_uiact, l_tags, l_views, l_heading, l_ready, l_zone,
            l_signals, l_status, l_rate, l_err, ''PAGE'', SYSTIMESTAMP, SYSTIMESTAMP);
        v_count := v_count + 1;
    END LOOP;
    COMMIT;
    :status := 200;
    HTP.p(''{"ok":true,"upserted":'' || v_count || ''}'');
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    :status := 50' || '0;
    HTP.p(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400), ''"'', ''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v1/runs/:run_id/steps',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'thin handler → VALIDATE_PERSIST_PKG');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v1/runs/:run_id/steps',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'FIX 2026-05-29 single body bind blob_to_clob_utf8(body)',
      p_source         => 
'DECLARE
  l_body CLOB;
  l_n    NUMBER;
BEGIN
  -- Read the request body. :body_text (CLOB) is the proven-working bind on this
  -- ORDS instance -- the jobs/complete handler uses it and lands data, while a
  -- BLOB-only read (blob_to_clob_utf8(:body)) came back empty and was the real
  -- cause of rows stuck at PENDING. Fall back to the BLOB only if the CLOB bind
  -- is empty. Reading both does NOT drain the stream (register does the same).
  l_body := :body_text;
  IF l_body IS NULL OR DBMS_LOB.GETLENGTH(l_body) = 0 THEN
    l_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  :status := 200;
  -- VALIDATE_PERSIST_PKG.persist_steps_json throws ORA-40573/06502 on the live
  -- payload. The agent persists every step via the bulletproof singular
  -- runs/:id/step handler, so this batch endpoint is redundant — never let it
  -- return 500. Catch the package error and report 0 persisted.
  BEGIN
    l_n := ITERIA_AI.VALIDATE_PERSIST_PKG.persist_steps_json(TO_NUMBER(:run_id), l_bod' || 'y);
  EXCEPTION WHEN OTHERS THEN
    l_n := 0;
  END;
  HTP.PRN(''{"ok":true,"persisted":'' || l_n || '',"run_id":'' || TO_NUMBER(:run_id) || ''}'');
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/steps',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'hooks thin → VALIDATE_PERSIST_PKG');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/steps',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'FIX 2026-05-29 single body bind blob_to_clob_utf8(body)',
      p_source         => 
'DECLARE
  l_body CLOB;
  l_n    NUMBER;
BEGIN
  -- Read the request body. :body_text (CLOB) is the proven-working bind on this
  -- ORDS instance -- the jobs/complete handler uses it and lands data, while a
  -- BLOB-only read (blob_to_clob_utf8(:body)) came back empty and was the real
  -- cause of rows stuck at PENDING. Fall back to the BLOB only if the CLOB bind
  -- is empty. Reading both does NOT drain the stream (register does the same).
  l_body := :body_text;
  IF l_body IS NULL OR DBMS_LOB.GETLENGTH(l_body) = 0 THEN
    l_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  :status := 200;
  -- VALIDATE_PERSIST_PKG.persist_steps_json throws ORA-40573/06502 on the live
  -- payload. The agent persists every step via the bulletproof singular
  -- runs/:id/step handler, so this batch endpoint is redundant — never let it
  -- return 500. Catch the package error and report 0 persisted.
  BEGIN
    l_n := ITERIA_AI.VALIDATE_PERSIST_PKG.persist_steps_json(TO_NUMBER(:run_id), l_bod' || 'y);
  EXCEPTION WHEN OTHERS THEN
    l_n := 0;
  END;
  HTP.PRN(''{"ok":true,"persisted":'' || l_n || '',"run_id":'' || TO_NUMBER(:run_id) || ''}'');
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'v1/runs/:run_id/step',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Fusion v5 live step — flat JSON body');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'v1/runs/:run_id/step',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'FIX 2026-05-29 single body bind blob_to_clob_utf8(body)',
      p_source         => 
'DECLARE
  l_body CLOB;
  l_n    NUMBER;
BEGIN
  -- Read the request body. :body_text (CLOB) is the proven-working bind on this
  -- ORDS instance -- the jobs/complete handler uses it and lands data, while a
  -- BLOB-only read (blob_to_clob_utf8(:body)) came back empty and was the real
  -- cause of rows stuck at PENDING. Fall back to the BLOB only if the CLOB bind
  -- is empty. Reading both does NOT drain the stream (register does the same).
  l_body := :body_text;
  IF l_body IS NULL OR DBMS_LOB.GETLENGTH(l_body) = 0 THEN
    l_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  :status := 200;
  -- Persist the step directly. Does NOT call VALIDATE_PERSIST_PKG, which throws
  -- ORA-40573 on the live payload and left every row stuck at PENDING with null
  -- scores. SQL JSON_VALUE/JSON_QUERY default to NULL ON ERROR, so a missing or
  -- malformed field can never abort the write. MERGE keys on (run_id, step_num):
  -- it updates the pre-seeded PENDING row in place, or inserts if' || ' absent. NVL
  -- preserves an existing non-null value when a field is omitted from this post.
  MERGE INTO ITERIA_AI.VALIDATE_SCRIPT_STEP_RESULTS dst
  USING (SELECT
           TO_NUMBER(:run_id) AS run_id,
           NVL(JSON_VALUE(l_body, ''$.step_number'' RETURNING NUMBER),
               NVL(JSON_VALUE(l_body, ''$.step_num'' RETURNING NUMBER), 1)) AS step_num,
           SUBSTR(JSON_VALUE(l_body, ''$.step_label''),  1, 500)  AS step_label,
           SUBSTR(JSON_VALUE(l_body, ''$.path_key''),    1, 2000) AS path_key,
           SUBSTR(JSON_VALUE(l_body, ''$.http_method''), 1, 10)   AS http_method,
           JSON_VALUE(l_body, ''$.http_status'' RETURNING NUMBER) AS http_status,
           SUBSTR(JSON_VALUE(l_body, ''$.pass_fail''),   1, 10)   AS pass_fail,
           SUBSTR(JSON_VALUE(l_body, ''$.ui_result''),   1, 20)   AS ui_result,
           SUBSTR(JSON_VALUE(l_body, ''$.ui_status_label''),     1, 60)   AS ui_status_label,
           SUBSTR(JSON_VALUE(l_body, ''$.ui_action_detail''),    1, 4000) ' || 'AS ui_action_detail,
           SUBSTR(JSON_VALUE(l_body, ''$.ui_failure_category''), 1, 60)   AS ui_failure_category,
           SUBSTR(JSON_VALUE(l_body, ''$.nav_method''),  1, 20)   AS nav_method,
           SUBSTR(NVL(JSON_VALUE(l_body, ''$.step_divergence''),
                      JSON_VALUE(l_body, ''$.healed_to'')), 1, 2000) AS step_divergence,
           SUBSTR(JSON_VALUE(l_body, ''$.confidence_bucket''), 1, 30) AS confidence_bucket,
           JSON_VALUE(l_body, ''$.ai_step_score'' RETURNING NUMBER)   AS ai_step_score,
           SUBSTR(NVL(JSON_VALUE(l_body, ''$.ai_plain_english''),
                      JSON_VALUE(l_body, ''$.plain_english'')), 1, 2000) AS ai_plain_english,
           JSON_VALUE(l_body, ''$.step_score'' RETURNING NUMBER)      AS step_score,
           JSON_VALUE(l_body, ''$.ui_score'' RETURNING NUMBER)        AS ui_score,
           JSON_VALUE(l_body, ''$.explanation_score'' RETURNING NUMBER) AS explanation_score,
           JSON_VALUE(l_body, ''$.api_command_score'' RETURNING NUMB' || 'ER) AS api_command_score,
           JSON_VALUE(l_body, ''$.api_response_score'' RETURNING NUMBER) AS api_response_score,
           JSON_VALUE(l_body, ''$.api_data_score'' RETURNING NUMBER)    AS api_data_score,
           JSON_VALUE(l_body, ''$.api_flow_relation_score'' RETURNING NUMBER) AS api_flow_relation_score,
           JSON_VALUE(l_body, ''$.api_replay_report'' RETURNING CLOB) AS api_replay_report,
           JSON_QUERY(l_body, ''$.api_calls'' RETURNING CLOB)         AS api_calls,
           JSON_VALUE(l_body, ''$.playwright_score'' RETURNING NUMBER) AS playwright_score,
