         dst.ui_result               = NVL(src.ui_result, dst.ui_result),
         dst.ui_statu' || 's_label         = NVL(src.ui_status_label, dst.ui_status_label),
         dst.ui_action_detail        = NVL(src.ui_action_detail, dst.ui_action_detail),
         dst.ui_failure_category     = NVL(src.ui_failure_category, dst.ui_failure_category),
         dst.nav_method              = NVL(src.nav_method, dst.nav_method),
         dst.step_divergence         = NVL(src.step_divergence, dst.step_divergence),
         dst.confidence_bucket       = NVL(src.confidence_bucket, dst.confidence_bucket),
         dst.ai_step_score           = NVL(src.ai_step_score, dst.ai_step_score),
         dst.ai_plain_english        = NVL(src.ai_plain_english, dst.ai_plain_english),
         dst.step_score              = NVL(src.step_score, dst.step_score),
         dst.ui_score                = NVL(src.ui_score, dst.ui_score),
         dst.explanation_score       = NVL(src.explanation_score, dst.explanation_score),
         dst.api_command_score       = NVL(src.api_command_score, dst.api_command_score),
   ' || '      dst.api_response_score      = NVL(src.api_response_score, dst.api_response_score),
         dst.api_data_score          = NVL(src.api_data_score, dst.api_data_score),
         dst.api_flow_relation_score = NVL(src.api_flow_relation_score, dst.api_flow_relation_score),
         dst.api_replay_report       = NVL(src.api_replay_report, dst.api_replay_report),
         dst.api_calls               = NVL(src.api_calls, dst.api_calls),
         dst.playwright_score        = NVL(src.playwright_score, dst.playwright_score),
         dst.visual_severity         = NVL(src.visual_severity, dst.visual_severity),
         dst.change_reason           = NVL(src.change_reason, dst.change_reason),
         dst.action_required         = NVL(src.action_required, dst.action_required),
         dst.screenshot_url          = NVL(src.screenshot_url, dst.screenshot_url),
         dst.screenshot_element_url  = NVL(src.screenshot_element_url, dst.screenshot_element_url),
         dst.diff_url              ' || '  = NVL(src.diff_url, dst.diff_url),
         dst.duration_ms             = NVL(src.duration_ms, dst.duration_ms),
         dst.raw_error               = NVL(src.raw_error, dst.raw_error),
         dst.executed_at             = SYSTIMESTAMP
  WHEN NOT MATCHED THEN INSERT (
         run_id, step_num, step_label, path_key, http_method, http_status,
         pass_fail, ui_result, ui_status_label, ui_action_detail, ui_failure_category,
         nav_method, step_divergence, confidence_bucket, ai_step_score, ai_plain_english,
         step_score, ui_score, explanation_score,
         api_command_score, api_response_score, api_data_score, api_flow_relation_score,
         api_replay_report, api_calls, playwright_score, visual_severity,
         change_reason, action_required, screenshot_url, screenshot_element_url,
         diff_url, duration_ms, raw_error, executed_at
       ) VALUES (
         src.run_id, src.step_num, src.step_label, src.path_key, src.http_method, src.http_status,
        ' || ' NVL(src.pass_fail, ''PENDING''), NVL(src.ui_result, ''PENDING''), src.ui_status_label, src.ui_action_detail, src.ui_failure_category,
         src.nav_method, src.step_divergence, src.confidence_bucket, src.ai_step_score, src.ai_plain_english,
         src.step_score, src.ui_score, src.explanation_score,
         src.api_command_score, src.api_response_score, src.api_data_score, src.api_flow_relation_score,
         src.api_replay_report, src.api_calls, src.playwright_score, src.visual_severity,
         src.change_reason, src.action_required, src.screenshot_url, src.screenshot_element_url,
         src.diff_url, src.duration_ms, src.raw_error, SYSTIMESTAMP
       );
  l_n := SQL%ROWCOUNT;
  COMMIT;
  HTP.PRN(''{"ok":true,"persisted":'' || l_n || '',"run_id":'' || TO_NUMBER(:run_id) || ''}'');
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"ok":false,"error":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
END;');

