  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/log',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'log GET — function tail (BEGIN only)',
      p_source         => 
'BEGIN
  :status := 200;
  HTP.PRN(ITERIA_AI.VALIDATE_GET_RUN_LOG_JSON(
    TO_NUMBER(:run_id),
    NVL(TO_NUMBER(:after_seq DEFAULT NULL ON CONVERSION ERROR),
        NVL(TO_NUMBER(:after DEFAULT NULL ON CONVERSION ERROR), 0)),
    LEAST(NVL(TO_NUMBER(:row_limit DEFAULT NULL ON CONVERSION ERROR),
              NVL(TO_NUMBER(:limit DEFAULT NULL ON CONVERSION ERROR), 500)), 2000)
  ));
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"err":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
END;');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/log',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'FIX 2026-05-29 single body bind blob_to_clob_utf8(body)',
      p_source         => 
'DECLARE
  l_body CLOB;
  l_n    NUMBER;
BEGIN
  -- Read the request body. :body_text (CLOB) is the proven-working bind on this
  -- ORDS instance -- the jobs/complete handler uses it and lands data, while a
  -- BLOB-only read (blob_to_clob_utf8(:body)) came back empty and was the real
  -- cause of rows stuck at PENDING. Fall back to the BLOB only if the CLOB bind
  -- is empty. Reading both does NOT drain the stream (register does the same).
  l_body := :body_text;
  IF l_body IS NULL OR DBMS_LOB.GETLENGTH(l_body) = 0 THEN
    l_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  :status := 200;
  -- Insert the log entries directly with JSON_TABLE. Does NOT call
  -- VALIDATE_PERSIST_PKG.append_run_log_json, which raises ORA-40573 because it
  -- calls JSON_OBJECT_T member functions (get_number/get_string) inline inside
  -- its SQL INSERT. JSON_TABLE extracts scalars in pure SQL, so it cannot throw
  -- that error. Shipper body shape: {"entries":[{seq,level,source,message}]}.
  ' || 'INSERT INTO ITERIA_AI.VALIDATE_RUN_LOGS (run_id, seq, log_level, log_source, message)
  SELECT TO_NUMBER(:run_id),
         NVL(jt.seq, ROWNUM),
         SUBSTR(NVL(jt.lvl, ''INFO''), 1, 16),
         SUBSTR(jt.src, 1, 64),
         SUBSTR(jt.msg, 1, 4000)
    FROM JSON_TABLE(l_body, ''$.entries[*]''
           COLUMNS (
             seq NUMBER         PATH ''$.seq'',
             lvl VARCHAR2(16)   PATH ''$.level'',
             src VARCHAR2(64)   PATH ''$.source'',
             msg VARCHAR2(4000) PATH ''$.message''
           )) jt
   WHERE jt.msg IS NOT NULL;
  l_n := SQL%ROWCOUNT;
  COMMIT;
  HTP.PRN(''{"inserted":'' || l_n || '',"run_id":'' || TO_NUMBER(:run_id) || ''}'');
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"err":"'' || REPLACE(SUBSTR(SQLERRM,1,400),''"'',''\"'') || ''"}'');
END;');

  ORDS.DEFINE_TEMPLATE(
