      p_comments       => NULL,
      p_source         => 
'BEGIN
  :status := 200;
  -- patch_flow_link_json comes from VALIDATE_PERSIST_PKG (the package that
  -- throws on the live payload). Flow-linking is non-fatal to a run, so catch
  -- its error and return 200 instead of letting it 500.
  BEGIN
    HTP.p(ITERIA_AI.VALIDATE_PERSIST_PKG.patch_flow_link_json(
      TO_NUMBER(:run_id), :body_text));
  EXCEPTION WHEN OTHERS THEN
    HTP.p(''{"ok":false,"error":"flow-link skipped"}'');
  END;
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.p(''{"error":"'' || REPLACE(SUBSTR(SQLERRM, 1, 400), ''"'', ''\"'') || ''"}'');
END;');

