      p_source         => 
'DECLARE
  v_sql CLOB;
BEGIN
  :status := 200;
  v_sql :=
    ''SELECT path_key, module, site_id, test_status, can_transact,''
    || '' duration_ms, error_message,''
    || '' TO_CHAR(created_at, ''''YYYY-MM-DD"T"HH24:MI:SS"Z"'''') AS tested_at''
    || '' FROM (''
    || '' SELECT t.*, ROW_NUMBER() OVER (PARTITION BY path_key ORDER BY created_at DESC NULLS LAST) rn''
    || '' FROM ITERIA_AI.VALIDATE_PATH_TEST_RESULTS t) x''
    || '' WHERE x.rn = 1 ORDER BY path_key'';
  BEGIN
    ITERIA_AI.VU_QUERY_PKG.run_as_json(v_sql, 0, 500);
  EXCEPTION
    WHEN OTHERS THEN
      BEGIN VU_QUERY_PKG.run_as_json(v_sql, 0, 500);
      EXCEPTION WHEN OTHERS THEN HTP.PRN(''{"items":[]}''); END;
  END;
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"items":[],"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300),''"'',''\"'') || ''"}'');
END;');

