      p_source         => 
'SELECT
    a.artifact_id,
    a.kind         AS artifact_kind,
    a.url          AS artifact_url,
    a.content_type,
    a.bytes,
    TO_CHAR(a.created_at, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') AS created_at
  FROM ITERIA_AI.VALIDATE_RUN_ARTIFACTS a
 WHERE a.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key") FROM dual)
