  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'runs/:run_id/artifacts',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'runs/:run_id/artifacts',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Register artifact — non-v1 alias',
      p_source         => 
'DECLARE
  v_tenant_id    NUMBER;
  v_run_id       NUMBER := TO_NUMBER(:run_id);
  v_body         CLOB;
  v_kind         VARCHAR2(50);
  v_url          VARCHAR2(2000);
  v_content_type VARCHAR2(200);
  v_bytes        NUMBER;
BEGIN
  v_tenant_id := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
  IF v_tenant_id IS NULL THEN
    :status := 401;
    HTP.PRN(''{"error":"unauthorized"}'');
    RETURN;
  END IF;
  BEGIN ADMIN.VALIDATE_CTX_PKG.set_tenant(v_tenant_id); EXCEPTION WHEN OTHERS THEN NULL; END;
  v_body := :body_text;
  IF v_body IS NULL OR DBMS_LOB.GETLENGTH(v_body) = 0 THEN
    v_body := iteria_ai.blob_to_clob_utf8(:body);
  END IF;
  IF v_body IS NULL OR DBMS_LOB.GETLENGTH(v_body) = 0 THEN
    :status := 400;
    HTP.PRN(''{"error":"empty request body"}'');
    RETURN;
  END IF;
  APEX_JSON.parse(v_body);
  v_kind         := SUBSTR(APEX_JSON.get_varchar2(''kind''), 1, 50);
  v_url          := SUBSTR(APEX_JSON.get_varchar2(''url''), 1, 2000);
  v_content_type := SUBSTR(APEX_JSON' || '.get_varchar2(''content_type''), 1, 200);
  v_bytes        := NVL(APEX_JSON.get_number(''bytes''), 0);
  IF v_kind IS NULL OR v_url IS NULL THEN
    :status := 400;
    HTP.PRN(''{"error":"kind and url are required"}'');
    RETURN;
  END IF;
  INSERT INTO ITERIA_AI.VALIDATE_RUN_ARTIFACTS
    (tenant_id, run_id, kind, url, content_type, bytes, created_at)
  VALUES
    (v_tenant_id, v_run_id, v_kind, v_url, v_content_type, v_bytes, SYSTIMESTAMP);
  COMMIT;
  :status := 201;
  HTP.PRN(''{"ok":true,"run_id":'' || v_run_id || '',"kind":"'' || REPLACE(v_kind, ''"'', ''\"'') || ''"}'');
EXCEPTION WHEN OTHERS THEN
  BEGIN ROLLBACK; EXCEPTION WHEN OTHERS THEN NULL; END;
  :status := 500;
  HTP.PRN(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300), ''"'', ''\"'') || ''"}'');
END;');

