      p_module_name    => 'validate',
      p_pattern        => 'navigator-nodes',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Oracle Navigator node registry (global, fndGlobalItemNodeId)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'navigator-nodes',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_items_per_page => 10000,
      p_mimes_allowed  => NULL,
      p_comments       => 'Load all navigator nodes for agent FndOverview navigation',
      p_source         => 
'SELECT node_id, node_kind, label, parent_label, shell, app, url_template
   FROM ITERIA_AI.ORACLE_NAVIGATOR_NODES
  WHERE tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key") FROM dual)
  ORDER BY node_id');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'navigator-nodes',
      p_method             => 'GET',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'navigator-nodes',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Bulk upsert navigator nodes from catalog_import',
      p_source         => 
'
DECLARE
    v_json      JSON_OBJECT_T := JSON_OBJECT_T.parse(:body);
    v_items     JSON_ARRAY_T  := v_json.get_array(''entries'');
    v_item      JSON_OBJECT_T;
    v_count     NUMBER := 0;
    v_tid       NUMBER := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
    v_node_id   VARCHAR2(255);
    v_node_kind VARCHAR2(50);
    v_label     VARCHAR2(255);
    v_parent    VARCHAR2(255);
    v_shell     VARCHAR2(50);
    v_app       VARCHAR2(50);
    v_url       VARCHAR2(1000);
    v_src       VARCHAR2(100);
BEGIN
    IF v_tid IS NULL THEN
        :status := 400;
        HTP.p(''{"error":"missing or unknown X-Tenant-Key"}'' );
    ELSE
        FOR i IN 0 .. v_items.get_size - 1 LOOP
            v_item := TREAT(v_items.get(i) AS JSON_OBJECT_T);
            v_node_id   := v_item.get_string(''node_id'');
            CONTINUE WHEN v_node_id IS NULL;
            v_node_kind := v_item.get_string(''node_kind'');
            v_label     := v_item.get_string(''label'');
            v_parent    :' || '= v_item.get_string(''parent_label'');
            v_shell     := v_item.get_string(''shell'');
            v_app       := v_item.get_string(''app'');
            v_url       := v_item.get_string(''url_template'');
            v_src       := v_item.get_string(''source_tag'');
            MERGE INTO ITERIA_AI.ORACLE_NAVIGATOR_NODES t
            USING (SELECT v_tid AS tenant_id, v_node_id AS node_id FROM dual) s
            ON (t.tenant_id = s.tenant_id AND t.node_id = s.node_id)
            WHEN MATCHED THEN UPDATE SET
                node_kind = v_node_kind, label = v_label, parent_label = v_parent,
                shell = v_shell, app = v_app, url_template = v_url, source_tag = v_src
            WHEN NOT MATCHED THEN INSERT
                (tenant_id, node_id, node_kind, label, parent_label, shell, app, url_template, source_tag)
            VALUES (v_tid, v_node_id, v_node_kind, v_label, v_parent, v_shell, v_app, v_url, v_src);
            v_count := v_count + 1;
        END LOOP;
        COMM' || 'IT;
        :status := 200;
        HTP.p(''{"upserted":'' || v_count || ''}'' );
    END IF;
EXCEPTION WHEN OTHERS THEN
    ROLLBACK; :status := 500;
    HTP.p(''{"error":"'' || SQLERRM || ''"}'' );
END;');

  ORDS.DEFINE_PARAMETER(
      p_module_name        => 'validate',
      p_pattern            => 'navigator-nodes',
      p_method             => 'POST',
      p_name               => 'X-Tenant-Key',
      p_bind_variable_name => 'X-Tenant-Key',
      p_source_type        => 'HEADER',
      p_param_type         => 'STRING',
      p_access_method      => 'IN',
      p_comments           => 'Per-tenant routing token (auto-registered by FIX_HEADER_BINDING.sql)');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'tenant/navigation-readiness',
      p_priority       => 0,
      p_etag_type      => 'NONE',
      p_etag_query     => NULL,
      p_comments       => 'Per-tenant page-library navigation readiness rollup');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'tenant/navigation-readiness',
      p_method         => 'GET',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Rollup: library rows nav-ready vs total + navigator node count',
      p_source         => 
'DECLARE
  v_tid           NUMBER;
  v_library_total NUMBER := 0;
  v_nav_ready     NUMBER := 0;
  v_node_count    NUMBER := 0;
  v_catalog_total NUMBER := 0;
  v_pct           NUMBER := 0;
BEGIN
  v_tid := ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:"X-Tenant-Key");
  IF v_tid IS NULL THEN
    :status := 401;
    HTP.PRN(''{"error":"unauthorized"}'');
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_library_total
    FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY p
   WHERE p.tenant_id = v_tid;

  SELECT NVL(SUM(
           CASE WHEN
             (p.deep_url IS NOT NULL
              AND LENGTH(TRIM(p.deep_url)) > 40
              AND INSTR(LOWER(p.deep_url), ''fusewelcome'') = 0
              AND (INSTR(LOWER(p.deep_url), ''fndoverview'') = 0
                   OR INSTR(LOWER(p.deep_url), ''fndglobalitemnodeid'') > 0))
             OR (p.observed_rest_paths IS NOT NULL AND LENGTH(TRIM(p.observed_rest_paths)) > 4)
             OR (p.menu_path_json IS NOT NULL AND LENGTH(TRIM(p.menu_path_json)) > 4)
         ' || '    OR EXISTS (
                  SELECT 1 FROM ITERIA_AI.ORACLE_NAVIGATOR_NODES n
                   WHERE n.tenant_id = p.tenant_id AND n.node_id = p.path_key)
           THEN 1 ELSE 0 END), 0) INTO v_nav_ready
    FROM ITERIA_AI.VALIDATE_PAGE_LIBRARY p
   WHERE p.tenant_id = v_tid;

  SELECT COUNT(*) INTO v_node_count
    FROM ITERIA_AI.ORACLE_NAVIGATOR_NODES n
   WHERE n.tenant_id = v_tid;

  BEGIN
    SELECT COUNT(*) INTO v_catalog_total
      FROM ITERIA_AI.VALIDATE_API_CATALOG c
     WHERE c.is_active = ''Y'';
  EXCEPTION WHEN OTHERS THEN
    v_catalog_total := 0;
  END;

  IF v_library_total > 0 THEN
    v_pct := ROUND(100 * v_nav_ready / v_library_total, 1);
  END IF;

  :status := 200;
  HTP.PRN(
    ''{"tenant_id":'' || v_tid
    || '',"library_total":'' || v_library_total
    || '',"nav_ready_count":'' || v_nav_ready
    || '',"nav_ready_pct":'' || v_pct
    || '',"navigator_node_count":'' || v_node_count
    || '',"rest_catalog_count":'' || v_catalog_total
    || '',"ready_for_bulk_runs"' || ':'' || CASE WHEN v_pct >= 85 THEN ''true'' ELSE ''false'' END
    || ''}''
  );
EXCEPTION WHEN OTHERS THEN
  :status := 500;
  HTP.PRN(''{"error":"'' || REPLACE(SUBSTR(SQLERRM,1,300), ''"'', ''\"'') || ''"}'');
END;');

