      p_mimes_allowed  => 'application/json',
      p_comments       => 'Alias of v_crawl_runs_summary/',
      p_source         => 
'SELECT r.run_id,
        (SELECT MAX(j.job_id)
           FROM ITERIA_AI.VALIDATE_JOBS j
          WHERE j.run_id = r.run_id OR j.job_id = r.run_id) AS job_id,
        r.tenant_id, r.status, r.oracle_version, r.crawl_type,
        r.credential_set, r.crawled_by, r.is_baseline, r.total_api_paths,
        r.total_nav_paths, r.total_oic_flows,
        NVL(r.total_api_paths,0)+NVL(r.total_nav_paths,0)+NVL(r.total_oic_flows,0) AS total_paths,
        r.started_at,
        r.completed_at,
        CASE WHEN r.completed_at IS NOT NULL AND r.started_at IS NOT NULL
             THEN ROUND((CAST(r.completed_at AS DATE)-CAST(r.started_at AS DATE))*86400)
             ELSE NULL END AS duration_seconds
   FROM ITERIA_AI.VALIDATE_CRAWL_RUNS r
  WHERE r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
  ORDER BY r.completed_at DESC NULLS LAST, r.started_at DESC NULLS LAST');

