  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'validate',
      p_pattern        => 'process-flows/:flow_id/history',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => 'Unified flow timeline — runs, self-heals, UI nav, human edits');

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'validate',
      p_pattern        => 'process-flows/:flow_id/history',
      p_method         => 'GET',
      p_source_type    => 'json/query',
      p_items_per_page => 500,
      p_mimes_allowed  => 'application/json',
      p_comments       => 'Runs + heals + navigation + human edits for one flow',
      p_source         => 
'SELECT event_type, run_id, step_num, summary, actor, healed_to, detail_json, event_at
   FROM (
    SELECT ''run'' AS event_type,
           r.run_id,
           CAST(NULL AS NUMBER) AS step_num,
           SUBSTR(
             ''Run #'' || r.run_id || '' '' || NVL(r.status, ''?'')
             || CASE WHEN r.grade IS NOT NULL THEN '' · grade '' || r.grade ELSE '''' END
             || CASE WHEN NVL(r.healed_count, NVL(r.heal_count, 0)) > 0
                     THEN '' · '' || NVL(r.healed_count, NVL(r.heal_count, 0)) || '' healed'' ELSE '''' END,
             1, 4000) AS summary,
           NVL(r.triggered_by, ''agent'') AS actor,
           CAST(NULL AS VARCHAR2(4000)) AS healed_to,
           CAST(NULL AS VARCHAR2(4000)) AS detail_json,
           NVL(r.completed_at, r.started_at) AS event_at,
           1 AS sort_pri
      FROM ITERIA_AI.VALIDATE_SCRIPT_RUNS r
     WHERE r.linked_flow_id = :flow_id
       AND r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
      ' || ' AND LOWER(NVL(r.status, ''x'')) NOT IN (''dismissed'', ''archived'', ''hidden'')
    UNION ALL
    SELECT ''self_heal'',
           s.run_id,
           s.step_num,
           SUBSTR(''Step '' || s.step_num || '': '' || NVL(s.step_label, '''')
                  || '' self-healed'', 1, 4000),
           ''playwright'',
           SUBSTR(NVL(s.step_divergence, ''''), 1, 4000),
           CAST(NULL AS VARCHAR2(4000)),
           NVL(r.completed_at, r.started_at),
           2
      FROM ITERIA_AI.VALIDATE_SCRIPT_STEP_RESULTS s
      JOIN ITERIA_AI.VALIDATE_SCRIPT_RUNS r ON r.run_id = s.run_id
     WHERE r.linked_flow_id = :flow_id
       AND r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
       AND UPPER(NVL(s.pass_fail, ''x'')) = ''HEALED''
    UNION ALL
    SELECT ''ui_navigation'',
           s.run_id,
           s.step_num,
           SUBSTR(''Step '' || s.step_num || '' UI navigation ('' || NVL(s.nav_method, ''?'') || '')'', 1, 4000),
           ''playwright'',
           CAST(NUL' || 'L AS VARCHAR2(4000)),
           SUBSTR(NVL(s.ui_action_detail, ''''), 1, 4000),
           NVL(r.completed_at, r.started_at),
           3
      FROM ITERIA_AI.VALIDATE_SCRIPT_STEP_RESULTS s
      JOIN ITERIA_AI.VALIDATE_SCRIPT_RUNS r ON r.run_id = s.run_id
     WHERE r.linked_flow_id = :flow_id
       AND r.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
       AND (s.ui_action_detail IS NOT NULL
            OR NVL(s.nav_method, ''x'') NOT IN ('''', ''direct'', ''none''))
    UNION ALL
    SELECT ''healed_label'',
           h.run_id,
           CAST(NULL AS NUMBER),
           SUBSTR(''Label heal: "'' || h.original || ''" → "'' || h.healed_to || ''"'', 1, 4000),
           ''ai_analyst'',
           SUBSTR(h.healed_to, 1, 4000),
           CAST(NULL AS VARCHAR2(4000)),
           NVL(h.last_used, SYSTIMESTAMP),
           4
      FROM ITERIA_AI.VALIDATE_HEALED_LABELS h
      JOIN ITERIA_AI.VALIDATE_SCRIPT_RUNS r ON r.run_id = h.run_id
     WHERE r.linked_flow_id = :' || 'flow_id
       AND h.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
    UNION ALL
    SELECT h.event_type,
           h.run_id,
           h.step_num,
           SUBSTR(h.summary, 1, 4000),
           NVL(h.actor, ''human''),
           CAST(NULL AS VARCHAR2(4000)),
           SUBSTR(NVL(h.detail_json, ''''), 1, 4000),
           h.created_at,
           5
      FROM ITERIA_AI.VALIDATE_PROCESS_FLOW_HISTORY h
     WHERE h.flow_id = :flow_id
       AND h.tenant_id = (SELECT ADMIN.VALIDATE_CTX_PKG.resolve_api_key(:x_tenant_key) FROM dual)
   )
  ORDER BY event_at DESC NULLS LAST
 FETCH FIRST 75 ROWS ONLY');

